#include <stddef.h> // for size_t
#include <stdlib.h> // for malloc and free

char** safe_string_array_allocation(char** input_strings, size_t array_size) {
    size_t total_length = 0;
    size_t i;

    if (input_strings == NULL || array_size == 0) {
        return NULL;
    }

    for (i = 0; i < array_size; i++) {
        total_length += strlen(input_strings[i]) + 1; // +1 for null terminator
    }

    char** output_strings = malloc(sizeof(char*) * array_size + total_length);
    if (output_strings == NULL) {
        free(input_strings); // free any previously allocated resources if malloc fails
        return NULL;
    }

    for (i = 0; i < array_size; i++) {
        size_t current_string_length = strlen(input_strings[i]);
        memcpy(output_strings[i] = output_strings + i * (sizeof(char*) + current_string_length),
               input_strings[i],
               current_string_length + 1);
    }

    return output_strings;
}
