#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct Transaction {
    int id;
    time_t timestamp;
    double weight;
} Transaction;

typedef struct Metrics {
    int num_transactions;
    double max_weighted_sum;
    int max_transaction_id;
} Metrics;

pthread_mutex_t metrics_lock = PTHREAD_MUTEX_INITIALIZER;
Metrics metrics = {0};

bool transaction_is_valid(Transaction* transaction, time_t current_time) {
    const int three_seconds = 3;
    const int one_second = 1;
    time_t transaction_age = current_time - transaction->timestamp;

    if (transaction_age > three_seconds * one_second) {
        return false;
    }

    pthread_mutex_lock(&metrics_lock);
    metrics.num_transactions++;
    pthread_mutex_unlock(&metrics_lock);

    return true;
}

double calculate_weighted_sum(Transaction* transactions, int num_transactions) {
    double weighted_sum = 0.0;

    for (int i = 0; i < num_transactions; i++) {
        weighted_sum += transactions[i].weight;
    }

    return weighted_sum;
}

void* filter_transactions(void* arg) {
    Transaction* transactions = (Transaction*) arg;
    time_t current_time;
    double max_weighted_sum = 0.0;
    int max_transaction_id = -1;

    current_time = time(NULL);

    for (int i = 0; i < MAX_NUM_TRANSACTIONS; i++) {
        if (transaction_is_valid(&transactions[i], current_time)) {
            double weighted_sum = calculate_weighted_sum(transactions, i + 1);

            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                max_transaction_id = transactions[i].id;
            }
        }
    }

    pthread_mutex_lock(&metrics_lock);
    metrics.max_weighted_sum = max_weighted_sum;
    metrics.max_transaction_id = max_transaction_id;
    pthread_mutex_unlock(&metrics_lock);

    return NULL;
}

int main() {
    Transaction transactions[MAX_NUM_TRANSACTIONS];
    pthread_t thread;

    // Initialize transactions array
    // ...

    pthread_create(&thread, NULL, filter_transactions, transactions);
    pthread_join(thread, NULL);

    printf("Maximum weighted sum: %.2f\n", metrics.max_weighted_sum);
    printf("Corresponding transaction ID: %d\n", metrics.max_transaction_id);

    return 0;
}
```

