    if ((bund = malloc(sizeof(resource_bundle_t))) == NULL) {
        fclose(file);
        return -ENOMEM;
    }

    if ((items = calloc(file_size / BUNDLE_ITEM_SIZE, sizeof(bundle_item_t))) == NULL) {
        free(bund);
        fclose(file);
        return -ENOMEM;
    }

    bund->item_count = file_size / BUNDLE_ITEM_SIZE;
    bund->items = items;

