#include <string.h>
#include <stdlib.h>
#include <stdbool.h>

char *add_slash(const char *input, size_t size_limit) {
    size_t input_len = strlen(input);

    // Check if input string length exceeds the size limit
    if (input_len >= size_limit) {
        free(input); // Free input memory if it was allocated
        return NULL;
    }

    // Allocate memory for the new string with a null terminator and an additional byte for the slash
    char *output = malloc(input_len + 2);
    if (output == NULL) {
        free(input); // Free input memory if it was allocated
        return NULL;
    }

    // Copy the input string to the output string
    memcpy(output, input, input_len);

    // Append the slash character
    output[input_len] = '/';

    // Add a null terminator
    output[input_len + 1] = '\0';

    return output;
}
