typedef struct node {
    int64_t offset;
    struct node *left;
    struct node *right;
} node_t;

node_t* bst_insert(node_t **root, int64_t offset) {
    if (*root == NULL) {
        *root = malloc(sizeof(node_t));
        if (*root == NULL) {
            return NULL;
        }
        (*root)->offset = offset;
        (*root)->left = NULL;
        (*root)->right = NULL;
    } else {
        node_t *current = *root;
        node_t *parent = NULL;

        while (current != NULL) {
            parent = current;

            if (offset < current->offset) {
                current = current->left;
            } else {
                current = current->right;
            }
        }

        node_t *new_node = malloc(sizeof(node_t));
        if (new_node == NULL) {
            free(parent);
            return NULL;
        }

        new_node->offset = offset;
        new_node->left = NULL;
        new_node->right = NULL;

        if (offset < parent->offset) {
            parent->left = new_node;
        } else {
            parent->right = new_node;
        }
    }

    return *root;
}
