#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

#define MAX_LINE_LENGTH 4096

typedef struct {
    size_t str_len;
    char str[MAX_LINE_LENGTH];
} line_data_t;

size_t process_file(const char *filename, size_t *num_strings, size_t *num_counts) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return 0;
    }

    size_t num_lines = 0;
    line_data_t lines[MAX_LINE_LENGTH];
    bool in_string = false;
    bool in_count = false;
    size_t str_index = 0;

    while (fgets(lines[num_lines].str, MAX_LINE_LENGTH, file)) {
        num_lines++;

        for (size_t i = 0; i < num_lines; i++) {
            if (lines[i].str[0] == '\'' && !in_count) {
                in_string = true;
                str_index = i;
                continue;
            }

            if (lines[i].str[0] == '!' && !in_string) {
                in_count = true;
                continue;
            }

            if (in_string && lines[i].str[0] != '\'' && lines[i].str[0] != '\0') {
                size_t new_size = strlen(lines[str_index].str) + strlen(&lines[i].str[1]) + 2;
                char *new_str = realloc(lines[str_index].str, new_size);

                if (!new_str) {
                    fclose(file);
                    return 0;
                }

                strcat(new_str, &lines[i].str[1]);
                lines[str_index].str_len = new_size;
            }

            if (in_count && lines[i].str[0] == '\n') {
                (*num_strings)++;
                in_string = false;
                in_count = false;
            }
        }
    }

    fclose(file);

    if (in_string) {
        size_t new_size = strlen(lines[str_index].str) + 1;
        char *new_str = realloc(lines[str_index].str, new_size);

        if (!new_str) {
            return 0;
        }

        lines[str_index].str[new_size - 1] = '\0';
        (*num_strings)++;
    }

    for (size_t i = 0; i < num_lines; i++) {
        if (lines[i].str[0] == '!' && !in_string) {
            (*num_counts)++;
        }
    }

    free(lines);
    return (*num_strings) + (*num_counts);
}
