void array_copy(size_t input_size, const void *input, void *output, size_t output_size) {
    if (input_size > output_size) {
        // Expand the output array if necessary
        size_t new_size = input_size;
        void *new_output = realloc(output, new_size * sizeof(char));

        if (new_output == NULL) {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        output = new_output;
    }

    memcpy(output, input, input_size * sizeof(char));
}

void array_expand(size_t *array_size, const size_t input_size, char *array) {
    size_t new_size = *array_size;

    if (new_size < input_size) {
        // Expand the array
        new_size *= 2; // Double the size for simplicity
        char *new_array = realloc(array, new_size * sizeof(char));

        if (new_array == NULL) {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        array = new_array;
        *array_size = new_size;
    }

    // Copy the input array into the expanded array
    array_copy(input_size, array, array, *array_size * sizeof(char));
}

void array_init(size_t *array_size, char *array, size_t initial_size) {
