void compress_tiff(TIFF *in_tiff, uint8 *buffer, size_t buffer_size) {
    TIFF *out_tiff = TIFFOpen("output.tiff", "w");
    if (!out_tiff) {
        free(buffer);
        return;
    }

    if (TIFFGetField(in_tiff, TIFFTAG_IMAGEWIDTH, NULL) ||
        TIFFGetField(in_tiff, TIFFTAG_IMAGELENGTH, NULL) ||
        TIFFGetField(out_tiff, TIFFTAG_IMAGEWIDTH, NULL) ||
