    size_t image_length = *(size_t*)(in_tiff->tiffData + 4);
    size_t row_size = TIFFScanlineSize(in_tiff);

    if (buffer_size < image_length * row_size) {
        TIFFClose(out_tiff);
        free(buffer);
        return;
    }

    for (size_t row = 0; row < image_length; ++row) {
        size_t nrow = row + TIFFScanlineSize(in_tiff);
        if (nrow > image_length) nrow = image_length;

        uint8 *src_ptr = buffer + row * image_width;
        uint8 *dst_ptr = malloc(row_size);
        if (!dst_ptr) {
            TIFFClose(out_tiff);
            free(buffer);
            return;
        }

        for (size_t col = 0; col < image_width; ++col) {
            size_t index = image_width - col - 1;
            dst_ptr[index] = src_ptr[col];
