        if (TIFFWriteScanline(out_tiff, dst_ptr, row) < 0) {
            free(dst_ptr);
            TIFFClose(out_tiff);
            free(buffer);
            return;
        }

        free(dst_ptr);
        src_ptr += row_size;
    }

    TIFFClose(out_tiff);
    free(buffer);
}
