#define POOL_SIZE 1024

typedef struct {
    void *data;
    size_t size;
    struct list_head node;
} pool_entry_t;

struct pool {
    size_t size;
    pool_entry_t *entries;
    struct list_head head;
};

static struct pool *pool;

static int pool_init(void) {
    if (pool) {
        return -1;
    }

    pool = calloc(1, sizeof(struct pool));
    if (!pool) {
        return -1;
    }

    pool->size = POOL_SIZE;
    pool->entries = calloc(POOL_SIZE, sizeof(pool_entry_t));
    if (!pool->entries) {
        free(pool);
        return -1;
    }

    INIT_LIST_HEAD(&pool->head);
    pool->size = POOL_SIZE;

    return 0;
}

static void *pool_alloc(size_t size) {
    pool_entry_t *entry;

    if (pool_init < 0) {
        return NULL;
    }

    list_for_each_entry(&pool->head, entry, node) {
        if (entry->size >= size) {
