#include <stdint.h> // for uint8_t, size_t
#include <stddef.h> // for NULL
#include <stdlib.h> // for malloc, free
#include <string.h> // for memset, memcpy
#include <unistd.h> // for write

// Global state variable
volatile uint8_t awaiting_ack = 0;

// Helper function for calculating the checksum
static uint16_t calc_checksum(const uint8_t *data, size_t len) {
    uint16_t sum = 0;
    while (len > 1) {
        sum += *data++;
        len--;
    }
    if (len > 0) {
        sum += *((const uint8_t *)data);
    }
    sum = (sum >> 8) + (sum & 0xff);
    sum = (sum >> 8) + (sum & 0xff);
    return sum;
}

// Function to transmit a packet with checksum
void transmit_packet(const uint8_t *packet, size_t len) {
    // Check if packet is NULL
    if (packet == NULL) {
        return;
    }

    // Allocate buffer for packet and checksum
    uint8_t *buffer = malloc(len + 2);
    if (buffer == NULL) {
        return;
    }

    // Copy packet data to buffer
    memcpy(buffer, packet, len);

    // Calculate checksum and store it in the last two bytes of the buffer
    uint16_t checksum = calc_checksum(packet, len);
    buffer[len] = checksum >> 8;
    buffer[len + 1] = checksum & 0xff;

    // Send packet and checksum to serial communication channel
    size_t num_bytes_sent = write(fileno(stdin), buffer, len + 2);
    if (num_bytes_sent != (len + 2)) {
        free(buffer);
        return;
    }

    // Set global state variable to indicate that an acknowledgement is awaited
    awaiting_ack = 1;

    // Free allocated memory
    free(buffer);
}
