#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define POLLSET_INITIAL_SIZE 16
#define POLLSET_GROWTH_FACTOR 2

typedef struct Pollset {
    int fd_max;
    int fd_count;
    int *fds;
} Pollset;

void pollset_init(Pollset *ps) {
    size_t size = sizeof(Pollset) + (POLLSET_INITIAL_SIZE * sizeof(int));
    ps->fds = (int *)calloc(POLLSET_INITIAL_SIZE, sizeof(int));
    if (!ps->fds) {
        ps->fd_max = -1;
        return;
    }
    ps->fd_count = 0;
    ps->fd_max = POLLSET_INITIAL_SIZE;
    if (ps->fds == NULL) {
        ps->fd_max = -1;
        free(ps);
        return;
    }
    ps->fds += POLLSET_INITIAL_SIZE;
    ps->fd_max *= POLLSET_GROWTH_FACTOR;
    ps->fds = (int *)realloc(ps->fds, size);
    if (ps->fds == NULL) {
        free(ps->fds);
        free(ps);
        ps->fd_max = -1;
        return;
    }
}

void pollset_add(Pollset *ps, int fd) {
    if (ps->fd_count >= ps->fd_max) {
        size_t new_size = ps->fd_max * POLLSET_GROWTH_FACTOR;
        ps->fds = (int *)realloc(ps->fds, sizeof(Pollset) + new_size * sizeof(int));
        if (ps->fds == NULL) {
            ps->fd_max = -1;
            return;
        }
        ps->fd_max *= POLLSET_GROWTH_FACTOR;
    }
    ps->fds[ps->fd_count++] = fd;
}

void pollset_free(Pollset *ps) {
    free(ps->fds);
    free(ps);
}

void pollset_destroy(Pollset *ps) {
    pollset_free(ps);
    memset(ps, 0, sizeof(Pollset));
}
