// Define the file information struct
typedef struct {
    const char* fileName;
    const char* defaultExtension;
    const char* initialDir;
    const char* title;
    uint16_t mode;
    bool addToRecentDocs;
    bool isDefaultPathHtml;
    const char* comFilterList;
    uint16_t selectedType;
} FileInfo;

// Function to create and populate a new QDict object with file opening options
QDict* createFileOpeningOptionsQDict(const QDict* inputOptions, const FileInfo* fileInfo) {
    // Allocate memory for the new QDict object
    QDict* newOptions = tr_new(tr_variant, 1);
    if (!newOptions) {
        // Memory allocation failed, return NULL
        return NULL;
    }

    // Initialize the new QDict object
    tr_variantInitDict(newOptions, inputOptions);

    // Populate the new QDict object with the file opening options
    if (fileInfo->fileName) {
        tr_variantAdd(newOptions, "fileName", tr_variantNewString(fileInfo->fileName));
    }

    if (fileInfo->defaultExtension) {
        tr_variantAdd(newOptions, "defaultExtension", tr_variantNewString(fileInfo->defaultExtension));
    }

    if (fileInfo->initialDir) {
        // Validate the initial directory and allocate memory for it if valid
        size_t len = strlen(fileInfo->initialDir) + 1;
        char* initialDir = malloc(len);
        if (!initialDir) {
            // Memory allocation failed, clean up the new QDict and return NULL
            tr_variantClean(newOptions);
            tr_variantFree(newOptions);
            return NULL;
        }
        strcpy(initialDir, fileInfo->initialDir);

        tr_variantAdd(newOptions, "initialDir", tr_variantNewString(initialDir));
        free(initialDir);
    }

    if (fileInfo->title) {
        tr_variantAdd(newOptions, "title", tr_variantNewString(fileInfo->title));
    }

    if (fileInfo->mode >= 0 && fileInfo->mode <= modeSave) {
        tr_variantAdd(newOptions, "mode", tr_variantNewInt32((int32_t)fileInfo->mode));
    }

    if (fileInfo->addToRecentDocs) {
        tr_variantAdd(newOptions, "addToRecentDocs", tr_variantNewBool(fileInfo->addToRecentDocs));
    }

    if (fileInfo->isDefaultPathHtml) {
        tr_variantAdd(newOptions, "isDefaultPathHtml", tr_variantNewBool(fileInfo->isDefaultPathHtml));
    }

    if (fileInfo->comFilterList) {
        size_t len = strlen(fileInfo->comFilterList) + 1;
        char* comFilterList = malloc(len);
        if (!comFilterList) {
            // Memory allocation failed, clean up the new QDict and return NULL
            tr_variantClean(newOptions);
            tr_variantFree(newOptions);
            return NULL;
        }
        strcpy(comFilterList, fileInfo->comFilterList);

        tr_variantAdd(newOptions, "comFilterList", tr_variantNewString(comFilterList));
        free(comFilterList);
    }

    if (fileInfo->selectedType >= 0) {
        tr_variantAdd(newOptions, "selectedType", tr_variantNewInt32((int32_t)fileInfo->selectedType));
    }

    return newOptions;
}
