char* generate_shared_secret(const char* input, time_t time_stamp, int entropy) {
    unsigned char md5_digest[MD5_DIGEST_LENGTH];
    char secret[SECRET_LENGTH + 1];

    // Concatenate inputs
    size_t input_length = strlen(input);
    size_t total_length = input_length + sizeof(time_stamp) + sizeof(entropy);
    char input_and_metadata[total_length];
    memcpy(input_and_metadata, input, input_length);
    memcpy(input_and_metadata + input_length, &time_stamp, sizeof(time_stamp));
    memcpy(input_and_metadata + input_length + sizeof(time_stamp), &entropy, sizeof(entropy));

