    MD5_CTX md5_context;
    MD5_Init(&md5_context);
    MD5_Update(&md5_context, input_and_metadata, total_length);
    MD5_Final(md5_digest, &md5_context);

    // Convert the binary digest to a hexadecimal string
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(secret + i * 2, "%02x", md5_digest[i]);
