void read_file_and_count_lines(const char *filename, uint64_t *lines_count) {
    FILE *file = fopen(filename, "r");
    char buffer[4096];
    size_t bytes_read;
    size_t current_line_length = 0;
    uint64_t current_line_count = 0;

    if (!file) {
