    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        current_line_length = strlen(buffer);

        if (current_line_length > 0 && buffer[current_line_length - 1] == '\n') {
            current_line_count++;
        }
    }

    if (feof(file)) {
        *lines_count = current_line_count;
    } else {
        perror("Error reading file");
        exit(EXIT_FAILURE);
    }

    fclose(file);
}

