#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_DIMENSIONS 10
#define MAX_BUFFER_SIZE 1024

typedef struct {
    int dimensions[MAX_DIMENSIONS];
    size_t max_line_length;
} LogMessage;

void initialize_buffers_and_arrays(LogMessage *t) {
    int i;

    // Validate dimensions of the log message buffer
    for (i = 0; i < MAX_DIMENSIONS; i++) {
        if (t->dimensions[i] < 0) {
            fprintf(stderr, "Invalid dimension value: %d\n", t->dimensions[i]);
            exit(EXIT_FAILURE);
        }
    }

    // Calculate the maximum size of the log message buffer, excluding the header size
    t->max_line_length = sizeof(LogMessage) + sizeof(int) * MAX_DIMENSIONS;

    // Allocate memory for the log message buffer
    t->log_message = malloc(t->max_line_length);
    if (t->log_message == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for a buffer to store the dimensions string
    char *dimensions_buffer = malloc(MAX_BUFFER_SIZE);
    if (dimensions_buffer == NULL) {
        perror("Memory allocation failed");
        free(t->log_message);
        exit(EXIT_FAILURE);
    }

    // Initialize and allocate memory for a 2D array
    size_t array_size = sizeof(int) * MAX_DIMENSIONS * MAX_DIMENSIONS;
    int **array = malloc(sizeof(int *) * MAX_DIMENSIONS);
    for (i = 0; i < MAX_DIMENSIONS; i++) {
        array[i] = malloc(sizeof(int) * MAX_DIMENSIONS);
        if (array[i] == NULL) {
            perror("Memory allocation failed");
            for (int j = 0; j < i; j++) {
                free(array[j]);
            }
            free(array);
            free(t->log_message);
            free(dimensions_buffer);
            exit(EXIT_FAILURE);
        }
    }

    // Log the message to the debug log with the dimensions of the buffers and arrays
    snprintf(dimensions_buffer, MAX_BUFFER_SIZE, "Dimensions: (%d, %d, ...)",
             t->dimensions[0], t->dimensions[1]);
    for (i = 2; i < MAX_DIMENSIONS; i++) {
        strcat(dimensions_buffer, ", ");
        strcat(dimensions_buffer, int_to_string(t->dimensions[i]));
    }

    log_message(LOG_DEBUG, "Initialized buffers and arrays:\nLog message buffer size: %zu bytes\nDimensions: %s",
                t->max_line_length, dimensions_buffer);

    free(dimensions_buffer);
    for (i = 0; i < MAX_DIMENSIONS; i++) {
        free(array[i]);
    }
    free(array);
    free(t->log_message);
}

