#include <stddef.h> // For size_t and NULL
#include <stdlib.h> // For malloc and free
#include <linux/list.h> // For struct list_head and INIT_LIST_HEAD

// Define the data structure and its nodes
typedef struct record {
    int data;
    struct knode *next;
} record;

typedef struct knode {
    record data;
    struct list_head list;
} knode;

// Function prototype
knode *allocate_nodes(size_t size, int order);

// Allocate memory for a single knode node
static inline knode *allocate_knode() {
    knode *node = kmalloc(sizeof(knode), GFP_KERNEL);
    if (!node) {
        return NULL;
    }
    INIT_LIST_HEAD(&node->data.next);
    return node;
}

// Allocate memory for a record node and its associated knode
static inline record *allocate_record() {
    record *record = malloc(sizeof(record));
    if (!record) {
        return NULL;
    }
    return record;
}

// Allocate memory for the given number of nodes
knode *allocate_nodes(size_t size, int order) {
    size_t num_nodes = (size - sizeof(knode)) / (sizeof(record) + sizeof(knode));
    knode *root = NULL;
    knode *current = NULL;

    // Allocate memory for the root node
    root = allocate_knode();
    if (!root) {
        goto error;
    }

    // Allocate memory for the remaining nodes
    for (int i = 0; i < num_nodes; i++) {
        current = allocate_knode();
        if (!current) {
            goto error_free_root;
        }

        // Enqueue the current node to the root node
        list_add(&current->data.next, &root->data.next);
    }

    return root;

error_free_root:
    kfree(root);
error:
    for (int i = 0; i < num_nodes; i++) {
        current = (knode *)((char *)root + sizeof(knode) + i * (sizeof(record) + sizeof(knode)));
        kfree(current);
    }
    return NULL;
}
