bool keyword_matches(const char *keyword, const char *entry_keyword) {
    size_t keyword_len = strlen(keyword);
    size_t entry_len = strlen(entry_keyword);

    if (keyword_len > entry_len) {
        return false;
    }

    return strncmp(entry_keyword, keyword, keyword_len) == 0;
}

HelpEntry *search_help_list(HelpEntry *head, const char *keyword) {
    HelpEntry *current = head;

    while (current != NULL) {
        pthread_mutex_lock(&current->mutex);
        if (keyword_matches(keyword, current->keyword)) {
            print_help_entry(current);
            break;
        }
        current = current->next;
        pthread_mutex_unlock(&current->mutex);
    }

    return NULL;
}

void print_help_list(HelpEntry *head, const char *keyword) {
    if (head == NULL) {
        printf("No help entries found.\n");
        return;
    }

    HelpEntry *current = head;

    while (current != NULL) {
        pthread_mutex_lock(&current->mutex);
        if (keyword == NULL || keyword_matches(keyword, current->keyword)) {
            print_help_entry(current);
        }
        current = current->next;
        pthread_mutex_unlock(&current->mutex);
    }
}

void init_help_entry(HelpEntry *entry, const char *keyword, const char *description) {
    strncpy(entry->keyword, keyword, MAX_HELP_ENTRY_LEN);
    strncpy(entry->description, description, MAX_HELP_ENTRY_LEN);
    entry->next = NULL;
    pthread_mutex_init(&entry->mutex, NULL);
}

