    HelpEntry *entry = malloc(sizeof(HelpEntry));
    if (entry != NULL) {
        init_help_entry(entry, keyword, description);
    }
    return entry;
}

void destroy_help_list(HelpEntry *head) {
    HelpEntry *current = head;
    HelpEntry *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

