#define MAX_LINE_LENGTH 4096

void create_http_request(char **request, const char *verb, const char *path, const char *http_version) {
    size_t verb_len = strlen(verb);
    size_t path_len = strlen(path);
    size_t http_version_len = strlen(http_version);
    size_t request_size = verb_len + path_len + http_version_len + 2 * (path_len + http_version_len) + 2;

    char *request_str = malloc(request_size + 1);
    if (request_str == NULL) {
        perror("Memory allocation failed");
        return;
    }

    strcpy(request_str, verb);
    strcat(request_str, " ");
    strcat(request_str, path);
    strcat(request_str, " ");
    strcat(request_str, http_version);
    strcat(request_str, "\r\n");

    size_t num_tokens = 1;
    char *token = strtok(request_str, " ");
    *request = malloc((request_size + 1) * num_tokens);
    if (*request == NULL) {
        free(request_str);
        perror("Memory allocation failed");
        return;
    }

    strcpy(*request, request_str);
    *request += verb_len + 1; // Skip verb and space

    while ((token = strtok(NULL, " ")) != NULL) {
        size_t token_len = strlen(token);
        memmove(*request + strlen(*request), token, token_len + 1);
        *request += token_len + 1;
        num_tokens++;
    }

    free(request_str);
}
