#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>

#define FLASH_ENV_PREFIX "FLASH_"

typedef struct FlashRange {
    uint32_t start;
    uint32_t end;
    uint16_t bank_width;
    uint16_t sector_count;
} FlashRange;

void parse_range_string(const char *range_str, FlashRange *flash_range) {
    char *token = strtok(const_cast<char *>(range_str), ",");
    flash_range->start = strtoul(token, NULL, 16);

    token = strtok(NULL, ",");
    flash_range->end = strtoul(token, NULL, 16);

    token = strtok(NULL, ",");
    flash_range->bank_width = strtoul(token, NULL, 10);

    token = strtok(NULL, ",");
    flash_range->sector_count = strtoul(token, NULL, 10);
}

void print_flash_info(const FlashRange *flash_range, const char *device_name) {
    printf("%s flash memory info:\n", device_name);
    printf("Bank width: %d bytes\n", flash_range->bank_width);
    printf("Sector count: %d\n", flash_range->sector_count);
    printf("Base address: 0x%08x\n", flash_range->start);
    printf("End address: 0x%08x\n", flash_range->end);
}

void set_env_variables(const char *device_name, const FlashRange *flash_range) {
    char base_env[32], sector_env[32], end_env[32];

    snprintf(base_env, sizeof(base_env), "%sBASE=%lx", FLASH_ENV_PREFIX, (long)flash_range->start);
    putenv(base_env);

    snprintf(sector_env, sizeof(sector_env), "%sSECTOR_COUNT=%d", FLASH_ENV_PREFIX, flash_range->sector_count);
    putenv(sector_env);

    snprintf(end_env, sizeof(end_env), "%sEND=%lx", FLASH_ENV_PREFIX, (long)flash_range->end);
    putenv(end_env);
}

void flash_info(const char *device_name, const char *range_str) {
    FlashRange flash_range;
    parse_range_string(range_str, &flash_range);
    print_flash_info(&flash_range, device_name);
    set_env_variables(device_name, &flash_range);
}
