typedef struct {
    EVP_CIPHER_CTX *ctx;
} aes_context;

aes_context *aes_init(const unsigned char *password) {
    aes_context *ctx = malloc(sizeof(aes_context));
    unsigned char key[AES_BLOCK_SIZE + AES_KEY_SIZE];
    unsigned char iv[AES_BLOCK_SIZE];

    if (ctx == NULL) {
        return NULL;
    }

