char * get_full_path(const char * dir_path, const char * file_name, bool * exists) {
  size_t dir_len = strlen(dir_path);
  size_t file_len = strlen(file_name);
  size_t total_len = dir_len + file_len + 2; // +2 for '/' and '\0'
  char * full_path = malloc(total_len + 1);
  if (!full_path) {
    if (exists) *exists = false;
    return NULL;
  }
  strncpy(full_path, dir_path, dir_len);
  full_path[dir_len] = '/';
  strncpy(full_path + dir_len + 1, file_name, file_len + 1);
  full_path[total_len] = '\0';

  struct stat st;
  if (stat(full_path, &st) < 0) {
    if (errno == ENOENT) { // File not found
      if (exists) *exists = false;
    } else { // Other error
      free(full_path);
      if (exists) *exists = false;
      return NULL;
    }
  } else {
    if (exists) *exists = true;
  }

  return full_path;
}
