#define MAX_BIND_PARAMS 100

typedef struct {
    MYSQL_BIND bind[MAX_BIND_PARAMS];
    int num_binds;
} bind_params;

void mysql_prepare_and_bind(MYSQL *conn, const char *query, bind_params *params) {
    MYSQL_STMT *stmt;
    int i;

    if (mysql_stmt_prepare(conn, query, strlen(query)) != 0) {
        fprintf(stderr, "Error preparing statement: %s\n", mysql_error(conn));
        return;
    }

    stmt = mysql_use_result(mysql_store_result(conn));
