    for (i = 0; i < params->num_binds; ++i) {
        params->bind[i].buffer_type = MYSQL_TYPE_NULL;
        params->bind[i].buffer = NULL;
        params->bind[i].length = 0;
        params->bind[i].is_null = 0;
    }
}

int mysql_execute_prepared_statement(MYSQL *conn, const char *query, bind_params *params) {
    MYSQL_STMT *stmt;
    int i, num_rows = 0;

    mysql_prepare_and_bind(conn, query, params);

    stmt = mysql_stmt_store_result(mysql_stmt_prepare(conn, query, strlen(query)));

    if (stmt == NULL) {
        fprintf(stderr, "Error preparing statement: %s\n", mysql_error(conn));
        return 0;
