#include <stdint.h>
#include <stdlib.h>
#include <time.h>

void seed_rng(void) {
    unsigned seed[32];
    if (!rand_r(seed)) {
        unsigned long t;
        t = time(NULL);
        srand(t);
        for (int i = 0; i < 32; i++) {
            seed[i] = rand();
        }
    }
}

uint32_t generate_random_number(uint32_t board_size) {
