#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>

static size_t format_len = strlen("desired_format_string");

long long count_files_with_format(const char *path, const char *format) {
    long long count = 0;
    DIR *dir;
    struct dirent *entry;
    struct stat file_stat;
    char full_path[1024];

    if (!(dir = opendir(path))) {
        return count;
    }

    while ((entry = readdir(dir)) != NULL) {
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);
        if (stat(full_path, &file_stat) < 0) {
            continue;
        }

        if (S_ISDIR(file_stat.st_mode)) {
            count += count_files_with_format(full_path, format);
            continue;
        }

        size_t str_len = strlen(entry->d_name);
        if (str_len > format_len) {
            continue;
        }

        char *filename = malloc(str_len + format_len + 1);
        strcpy(filename, entry->d_name);
        strncat(filename, ":", format_len + 1);
        strncat(filename, format, format_len);

        if (strstr(filename, format) != NULL) {
            count++;
        }

        free(filename);
    }

    closedir(dir);
    return count;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <starting_directory>\n", argv[0]);
        return 1;
    }

    long long count = count_files_with_format(argv[1], "desired_format_string");
    printf("Number of files with the desired format: %lld\n", count);
    return 0;
