// Function to validate file name and path
int validate_file_name_and_path(const char *file_name, const char *file_path) {
    // Validate file name
    size_t file_name_len = strlen(file_name);
    if (file_name_len > MAX_FILE_NAME_LENGTH - 1) {
        perror("File name too long");
        return -1;
    }

    // Validate file path
    size_t path_len = strlen(file_path);
    if (path_len > MAX_PATH_LENGTH - 1) {
        perror("Path too long");
        return -1;
    }

    // Check if file path is absolute
    if (file_path[0] == '/') {
        // Absolute path, no need to add the file name
        strcpy(dir_entry.path, file_path);
        strcpy(dir_entry.name, file_name);
    } else {
        // Relative path, add file name to parent directory path
        size_t parent_path_len = strlen(file_path) - 1;
        if (file_path[parent_path_len] != '/') {
            parent_path_len++;
            file_path[parent_path_len] = '\0';
        }

        strcpy(dir_entry.path, file_path);
        strcat(dir_entry.path, "/");
        strcat(dir_entry.path, file_name);
    }

    return 0;
}

