    progress->total_steps = 10; // Set the total number of steps
    progress->current_step = 0;

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, task_progress_thread, progress);

    pthread_join(thread_id, NULL);
}

int get_current_step(struct task_progress *progress) {
    pthread_mutex_lock(&progress->lock);
    int current_step = progress->current_step;
    pthread_mutex_unlock(&progress->lock);
    return current_step;
}

void update_progress(struct task_progress *progress, int new_step) {
    pthread_mutex_lock(&progress->lock);
    progress->current_step = new_step;
