// Function to validate filename for unsafe characters and sequences
bool is_safe_filename(const char *filename) {
    size_t i;
    for (i = 0; filename[i] != '\0'; i++) {
        if (filename[i] == '.' && (i == 0 || i == strlen(filename) - 1)) {
            continue; // Dot at the beginning or end is allowed
        }
        if (filename[i] == '/' || filename[i] == '\\') {
