char *concat_filename_extension(const char *filename, const char *extension) {
    size_t filename_len = strlen(filename);
    size_t extension_len = strlen(extension);
    size_t new_string_len = filename_len + extension_len + 2; // +2 for '\0' and '.'

    // Validate path length before concatenation
    if (new_string_len > GIT_PATH_MAX) {
        perror("Path length exceeds maximum allowed length");
        return NULL;
    }

    char *new_string = safe_calloc(new_string_len, sizeof(char));
    if (new_string == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Concatenate filename and extension
    strncat(new_string, filename, filename_len + 1); // +1 for '\0' at the end of filename
    if (filename[filename_len - 1] != '.') {
        strcat(new_string, "."); // Add '.' before extension
        filename_len++;
    }
    strcat(new_string, extension);

    // Null-terminate the new string
    new_string[new_string_len - 1] = '\0';

    return new_string;
}
