char *process_line(char *input, size_t *input_len) {
    size_t len = *input_len;
    size_t i = len;

    // Check for null input
    if (input == NULL) {
        return NULL;
    }

    // Find the last occurrence of a newline or carriage return character
    while (i > 0 && (input[i - 1] != '\n' && input[i - 1] != '\r')) {
        i--;
    }

    if (i == len) {
