    memmove(&input[i - 1], &input[len - 1], len - i);
    len -= (i - 1);
    input_len = &len;

    // Allocate new memory for the modified string and append a newline character
    char *result = realloc(input, len + 1);
    if (result == NULL) {
        // If realloc fails, free the original memory and return NULL
        free(input);
        return NULL;
    }

    result[len] = '\n';
    len++;
    input = result;

    return input;
}
