int set_filter(pcap_t *handle, struct bpf_program *prog, char *filter) {
    char errbuf[PCAP_ERRBUF_SIZE];
    char filter_buf[MAX_FILTER_LEN];
    int filter_len = strlen(filter);

    if (filter_len > MAX_FILTER_LEN) {
