char **get_feed_list() {
    char *feed_env = getenv("FEEDS");
    if (feed_env == NULL) {
        fprintf(stderr, "Missing required environment variable: FEEDS\n");
        exit(EXIT_FAILURE);
    }
    char *token = strtok(feed_env, ":");
    size_t num_feeds = 0;
    char **feeds = malloc(MAX_FEEDS * sizeof(char *));
