#include <stddef.h> // for size_t
#include <string.h> // for memmove and strlen

size_t insert_substring(char *str, size_t start_pos, const char *substr) {
    size_t len_str = strlen(str);
    size_t len_substr = strlen(substr);

    // Check if there's enough space to insert the substring
    if (start_pos + len_substr > len_str) {
        // Reallocate memory for the new string length
        size_t new_len = len_str + len_substr + 1; // +1 for null terminator
        char *new_str = realloc(str, new_len);

        if (new_str == NULL) {
            // Memory allocation failed, return original string length
            free(str);
            return len_str;
        }

        str = new_str;
    }

    // Move the substring to the target position
    memmove(&str[start_pos + len_substr], substr, len_substr + 1);

    // Update the start position to the new length
    start_pos += len_substr;

    // Return the new length of the modified string
    return len_str + len_substr;
}
