#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/nvpair.h>

void append_parity(char **path, nvlist_t *config) {
    int parity_level;
    char *parity_str;

    if (nvlist_lookup_uint64(config, "raidz_parity_level", &parity_level) != 0) {
        // Device is not a RAIDZ device, return the input path unmodified
        return;
    }

    // Allocate memory for the parity level string
    parity_str = malloc(17 * sizeof(char)); // Assuming parity level is a decimal number up to 15 digits long
    if (parity_str == NULL) {
        perror("malloc");
        return;
    }

    // Convert parity level to string and concatenate it to the path
    snprintf(parity_str, sizeof(parity_str), "%llx", (unsigned long long)parity_level);
    size_t path_len = strlen(*path);
    size_t parity_len = strlen(parity_str);
    char *new_path = malloc(path_len + parity_len + 2); // +1 for '_' and +1 for '\0'
    if (new_path == NULL) {
        free(parity_str);
        perror("malloc");
        return;
    }

    // Concatenate parity level to the path
    strncpy(new_path, *path, path_len);
    strncat(new_path, "_", 1);
    strncat(new_path, parity_str, parity_len + 1);
    strncat(new_path, "\0", 1);

    // Free old path and set new path to the returned value
    free(*path);
    *path = new_path;
}
