    int length;
    void *data;
    struct hash_entry *next;
} hash_entry;

hash_entry *hash_table[HASH_TABLE_SIZE];

TEE_Result init_hash_context(void *ctx, const char *key, size_t key_len) {
    hash_entry *entry;
    int hash;

    if (key_len > 32 || key_len < 0) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    // Initialize Blake2s context
    blake2b_init((blake2b_state *)ctx, 0);

    // Hash the key to find the hash table index
    blake2b((const uint8_t *)key, key_len, &hash, sizeof(hash), (uint8_t *)ctx);

