void display_message(const char *message, int importance) {
    size_t message_length = strlen(message);
    size_t remaining_space = MAX_LINE_LENGTH - message_length;
    char *formatted_message = NULL;

    if (importance > 0) {
        formatted_message = malloc(MAX_LINE_LENGTH + strlen(IMPORTANT_PREFIX) + 1);
