            perror("Memory allocation failed");
            return;
        }
        strcpy(formatted_message, IMPORTANT_PREFIX);
        strcat(formatted_message, message);
    } else {
        formatted_message = strdup(message);
    }

    if (remaining_space > 0) {
        size_t space_needed = strlen(formatted_message) + 1;
        if (space_needed <= remaining_space) {
            printf("%s\n", formatted_message);
            free(formatted_message);
            return;
        }

        size_t cut_position = remaining_space - 1;
        while (cut_position > 0 && formatted_message[cut_position] != ' ') {
            cut_position--;
