void safe_copy(const void* src, void* dest, size_t size) {
    void* temp = malloc(size);
    if (temp == NULL) {
        // handle out-of-memory error
        return;
    }

    if (size > 0) {
        size_t src_remaining = size;
        char* src_buffer = (char*) src;
        char* dest_buffer = (char*) dest;

