#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <inttypes.h>

#define HASH_TABLE_ORDER 101
#define HASH_TABLE_SIZE (HASH_TABLE_ORDER * sizeof(bucket_t))

typedef struct {
    char key[256];
    void *value;
    bool active;
} pair_t;

typedef struct {
    pair_t *entries;
} bucket_t;

typedef struct {
    bucket_t *buckets;
} hashtable_t;

void *hash_str(const char *str) {
    uint64_t hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash;
}

size_t hashmask(size_t order) {
    return order - 1;
}

pair_t *hashtable_find_pair(hashtable_t *hashtable, bucket_t *bucket, const char *key, size_t hash) {
    pair_t *pair;

    for (pair = bucket->entries; pair; pair = pair->next) {
        if (strcmp(pair->key, key) == 0 && pair->active)
            return pair;

        hash += hash_str(pair->key);
    }

    return NULL;
}

int hashtable_lookup(hashtable_t *hashtable, const char *key, void **value) {
    int collisions = 0;
    bucket_t *bucket;
    pair_t *pair;
    size_t hash;

    *value = NULL;

    hash = hash_str(key) & hashmask(hashtable->order);
    bucket = &hashtable->buckets[hash];

    pair = hashtable_find_pair(hashtable, bucket, key, hash);

    if (pair) {
        *value = pair->value;
        collisions = 1;
    }

    return collisions;
}

hashtable_t *hashtable_init() {
    hashtable_t *hashtable;

    hashtable = calloc(1, HASH_TABLE_SIZE);
    if (!hashtable)
        return NULL;

    hashtable->buckets = (bucket_t *) ((uint8_t *) hashtable + sizeof(hashtable_t));

    return hashtable;
