static void parse_int(const char **input, int64_t *out) {
    int base = 10;
    int64_t value = 0;
    bool negative = false;

    if (**input == '-') {
        negative = true;
        (*input)++;
    }

    while (isdigit(**input)) {
        value = value * base + (**input - '0');
        (*input)++;
    }

    if (negative) {
        *out = -value;
    } else {
        *out = value;
    }
}

static void parse_float(const char **input, double *out) {
    int64_t int_part = 0;
    double float_part = 0.0;
    int exponent = 0;
    bool is_float = false;
    int64_t temp;

    while (isdigit(**input)) {
        parse_int(input, &temp);
        int_part = int_part * 10 + temp;
    }

    if (**input == '.') {
        (*input)++;
        while (isdigit(**input)) {
            parse_int(input, &temp);
            float_part += temp / pow(10.0, (double)(*input - *input + 1));
            (*input)++;
        }
        is_float = true;
    }

    if (**input == 'e' || **input == 'E') {
