#define MIN_BACKOFF 1000
#define MAX_JITTER 500

struct mqtt_context {
    struct async_client *client;
    pthread_mutex_t lock;
};

int mqtt_exponential_backoff(struct mqtt_context *ctx) {
    int status = ASYNC_OK;
    int retries = 0;
    struct timeval start_time, current_time;
    long backoff = MIN_BACKOFF;
    long jitter;

    if (pthread_mutex_lock(&ctx->lock) != 0) {
        fprintf(stderr, "Failed to acquire lock\n");
        return ASYNC_ERROR;
    }

    gettimeofday(&start_time, NULL);

    while (retries < MAX_RETRIES && status != ASYNC_SUCCESS) {
        status = async_send_message(ctx->client, NULL, 0, NULL, 0);

        if (status != ASYNC_SEND_IN_PROGRESS && status != ASYNC_SEND_FAILED) {
            break;
        }

        gettimeofday(&current_time, NULL);
        long elapsed = (current_time.tv_sec - start_time.tv_sec) * 1000 +
                      (current_time.tv_usec - start_time.tv_usec) / 1000;

        if (status == ASYNC_SEND_FAILED && elapsed < backoff) {
            usleep(backoff - elapsed);
            backoff *= 2;
            jitter = (rand() % (MAX_JITTER + 1)) + 1;
            backoff += jitter;
            retries++;
            continue;
        }

        if (status == ASYNC_SEND_FAILED) {
            fprintf(stderr, "MQTT message send failed with error %d\n", status);
        }
    }

    if (pthread_mutex_unlock(&ctx->lock) != 0) {
        fprintf(stderr, "Failed to release lock\n");
        return ASYNC_ERROR;
    }

    if (status != ASYNC_SUCCESS) {
        fprintf(stderr, "MQTT connection failed with error %d\n", status);
        return ASYNC_ERROR;
    }

    return ASYNC_SUCCESS;
}
