#include <openssl/md5.h>

#define MD5_STRLEN 16

char* generate_shared_secret(const char* path, int timestamp) {
    char path_str[256]; // Assuming maximum path length
    char time_str[17]; // Assuming maximum integer to string conversion length
    unsigned char md5_digest[MD5_STRLEN];
    MD5_CTX md5;

    // Validate input
    if (strlen(path) > 255 || (timestamp < 0 && timestamp != INT_MAX)) {
        return NULL;
    }

    // Convert path to string
    strcpy(path_str, path);

    // Convert timestamp to string
    snprintf(time_str, sizeof(time_str), "%d", timestamp);

    // Initialize MD5 context
    MD5_Init(&md5);

    // Update MD5 context with path string
    MD5_Update(&md5, path_str, strlen(path_str));

    // Update MD5 context with timestamp string
    MD5_Update(&md5, time_str, strlen(time_str));

    // Finalize MD5 hash
    MD5_Final(md5_digest, &md5);

    // Allocate memory for the hexadecimal encoded shared secret
    size_t hex_len = 2 * MD5_STRLEN;
    char* hex_secret = malloc(hex_len);

    // Convert binary hash to hexadecimal string
    for (int i = 0; i < MD5_STRLEN; i++) {
        snprintf(path_str, sizeof(path_str), "%02x", md5_digest[i]);
        strcat(hex_secret, path_str);
    }

    return hex_secret;
}
