#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

void insert_line(char *buffer, size_t *length, int line_number, const char *line_content) {
    size_t current_position = line_number * (*length / MAX_LINE_LENGTH) * MAX_LINE_LENGTH;
    size_t remaining_space_on_line = MAX_LINE_LENGTH - (current_position % MAX_LINE_LENGTH);
    size_t line_length = strlen(line_content);

    // Check if there is enough space to insert the new line without overwriting existing content
    if (remaining_space_on_line < line_length) {
        fprintf(stderr, "Not enough space to insert new line at current position\n");
        return;
    }

    // Move all characters from the end of the line to the new position, plus one for the null terminator
    memmove(current_position + line_length, buffer + current_position, remaining_space_on_line - line_length);

    // Insert the new line at the current position
    strncat(buffer + current_position, line_content, line_length + 1);

    // Update the length of the buffer
    *length += line_length + 1;
}
