void encryptDES_ECB(unsigned char key[3][KEYSIZE / 8], unsigned char plaintext[PLAINTEXT_LENGTH], unsigned char result[3][BLOCK_SIZE / 8]) {
    DES_crypt_t des;
    unsigned char iv[8] = {0}; // Initialization Vector, set to zero for ECB mode

    // Initialize DES context
    DES_init(&des, key[0], DES_ENCRYPT);

    // Encrypt first block
    DES_crypt_cbc(&des, iv, plaintext, plaintext, sizeof(plaintext));
    memcpy(result[0], plaintext, BLOCK_SIZE);

    // Encrypt second block
