    // Encrypt third block
    plaintext += BLOCK_SIZE;
    DES_crypt_cbc(&des, iv, plaintext, plaintext, sizeof(plaintext));
    memcpy(result[2], plaintext, BLOCK_SIZE);

    // Clean up
    DES_finish(&des);
}
