#include <vector>
#include <algorithm>
#include <numeric>

struct Pair {
    int value;
    bool selected;
};

int find_best_combination(const std::vector<Pair>& pairs, int target_sum) {
    int min_num_selected = INT32_MAX;
    int sum = 0;
    std::vector<Pair> selected_pairs;

    for (const auto& pair : pairs) {
        if (!pair.selected) {
            int remaining_sum = target_sum - sum;
            if (remaining_sum < 0 || abs(remaining_sum) > pair.value) {
                continue;
            }

            sum += pair.value;
            selected_pairs.push_back(pair);
            min_num_selected = std::min(min_num_selected, (int)selected_pairs.size());
        }
    }

    if (sum != target_sum) {
        for (auto& pair : selected_pairs) {
            pair.selected = false;
            sum -= pair.value;
        }
        return -1;
    }

    return std::make_pair(sum, min_num_selected);
}
