#include <iostream>
#include <string>
#include <thread>
#include <mutex>
#include <sys/socket.h>
##include <arpa/inet.h>
#include <unistd.h>
#include <cstring>
#include <cerrno>
#include <stdexcept>

const int MAX_BUFFER_SIZE = 1024;

class RobotClient {
private:
    int _socket;
    std::string _ipAddress;
    int _port;
    std::mutex _mutex;

public:
    RobotClient(const std::string& ipAddress, int port) : _ipAddress(ipAddress), _port(port), _socket(-1) {
        _socket = socket(AF_INET, SOCK_STREAM, 0);
        if (_socket < 0) {
            throw std::runtime_error("Failed to create socket: " + std::string(strerror(errno)));
        }

        sockaddr_in serverAddress;
        serverAddress.sin_family = AF_INET;
        serverAddress.sin_port = htons(_port);
        inet_pton(AF_INET, _ipAddress.c_str(), &serverAddress.sin_addr);

        if (connect(_socket, (sockaddr*)&serverAddress, sizeof(serverAddress)) < 0) {
            close(_socket);
            _socket = -1;
            throw std::runtime_error("Failed to connect to robot: " + std::string(strerror(errno)));
        }
    }

    ~RobotClient() {
        disconnect();
        close(_socket);
    }

    void disconnect() {
        if (_socket >= 0) {
            shutdown(_socket, SHUT_RDWR);
            _socket = -1;
        }
    }

    void sendCommand(const std::string& command) {
        std::lock_guard<std::mutex> lock(_mutex);

        if (_socket < 0) {
            throw std::runtime_error("Not connected to robot");
        }

        send(_socket, command.c_str(), command.size(), 0);
    }

    std::string receiveResponse() {
        std::string response;
        char buffer[MAX_BUFFER_SIZE];
        int bytesReceived = recv(_socket, buffer, MAX_BUFFER_SIZE, 0);

        if (bytesReceived <= 0) {
            if (bytesReceived == 0) {
                disconnect();
                throw std::runtime_error("Robot disconnected");
            } else {
                throw std::runtime_error("Error receiving response: " + std::string(strerror(errno)));
            }
        }

        response.assign(buffer, bytesReceived);
        return response;
    }
};

int main() {
    std::string ipAddress = "192.168.1.1";
    int port = 1234;

    try {
        RobotClient robotClient(ipAddress, port);

        std::string command = "move_forward 10";
        robotClient.sendCommand(command);
        std::string response = robotClient.receiveResponse();
        std::cout << "Received response: " << response << std::endl;

        std::this_thread::sleep_for(std::chrono::seconds(5));

        robotClient.disconnect();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
