#define MAX_ENV_VAR_LENGTH 1024

typedef struct {
    char *name;
    char *value;
} EnvVar;

EnvVar *env_vars = NULL;
size_t env_vars_count = 0;

void remove_env_var(const char *name) {
    size_t i;
    for (i = 0; i < env_vars_count; ++i) {
        if (strcmp(env_vars[i].name, name) == 0) {
            free(env_vars[i].name);
            free(env_vars[i].value);
            memmove(&env_vars[i], &env_vars[i + 1], (env_vars_count - i - 1) * sizeof(EnvVar));
            --env_vars_count;
            break;
        }
    }
}

void set_env_var(const char *name, const char *value) {
    size_t i;
    for (i = 0; i < env_vars_count; ++i) {
        if (strcmp(env_vars[i].name, name) == 0) {
            free(env_vars[i].value);
            env_vars[i].value = strdup(value);
            return;
        }
    }

    EnvVar new_env_var = {.name = strdup(name), .value = strdup(value)};
    env_vars = realloc(env_vars, sizeof(EnvVar) * (env_vars_count + 1));
    env_vars[env_vars_count++] = new_env_var;
}

