#include <string>
#include <vector>
#include <stdexcept>

enum Tile { EMPTY, WALL, FLOOR };

std::vector<std::vector<Tile>> load_map_from_string(const std::string& input) {
    size_t row_size = 0;
    size_t col_num = 0;
    size_t pos = 0;

    // Find the number of columns and the size of each row
    while (pos < input.size() && std::isspace(input[pos])) {
        col_num++;
        pos++;
    }
    if (pos >= input.size()) {
        throw std::invalid_argument("Empty input string");
    }
    row_size = std::distance(input.cbegin(), input.cbegin() + pos);

    std::vector<std::vector<Tile>> map(static_cast<size_t>(std::ceil(input.size() / (row_size + col_num))),
                                       std::vector<Tile>(row_size));

    size_t current_pos = 0;
    for (size_t row = 0; row < map.size(); ++row) {
        for (size_t col = 0; col < map[row].size(); ++col) {
            if (current_pos >= input.size()) {
                throw std::runtime_error("Input string is too short");
            }
            char c = input[current_pos];
            current_pos++;

            if (std::isspace(c)) {
                if (col != 0) {
                    throw std::runtime_error("Invalid delimiter between tiles in a row");
                }
                continue;
            }

            switch (c) {
                case 'W': map[row][col] = WALL; break;
                case 'F': map[row][col] = FLOOR; break;
                case 'E': map[row][col] = EMPTY; break;
                default:
                    throw std::runtime_error("Invalid tile value: " + c);
            }
        }
    }

    if (current_pos < input.size()) {
        throw std::runtime_error("Input string is too long");
    }

    return map;
}
