using namespace std;

void manageEntities(ComponentManager& componentManager, float deltaTime) {
    static unordered_map<int, Entity*> entities; // Store entities by their ID
    static vector<Entity*> entitiesToDestroy;

    // Subscribe to new entities
    for (auto entityPacket : getNewEntities()) {
        Entity* entity = componentManager.createEntity(entityPacket.getType(), entityPacket.getPosition(), entityPacket.getUniqueId());
