#include <iostream>
#include <map>
#include <memory>

struct PageData {
    int page_id;
    char* page_data;
};

class PagePool {
private:
    std::map<int, std::unique_ptr<PageData>> page_map;

public:
    PagePool() {}

    // Create a new page with given identifier and initialize PageData with null pointer
    void create_page(int page_id) {
        std::unique_ptr<PageData> new_page(new PageData{page_id, nullptr});
        page_map[page_id] = std::move(new_page);
    }

    // Retrieve the page with the given identifier, returns a null pointer if not found
    PageData* get_page(int page_id) {
        auto it = page_map.find(page_id);
        if (it == page_map.end()) {
            return nullptr;
        }
        return it->second.get();
    }

    // Delete the page with the given identifier and remove it from the map
    void delete_page(int page_id) {
        auto it = page_map.find(page_id);
        if (it == page_map.end()) {
            std::cerr << "Page with id " << page_id << " not found.\n";
            return;
        }
        page_map.erase(it);
    }
};
