#include <random>
#include <vector>

template<typename DataType>
void randomizeSparseMatrix(std::vector<DataType>& values, std::vector<size_t>& indices, size_t numRows, size_t numCols, bool isCSC) {
    std::mt19937 generator; // Mersenne Twister pseudo-random number generator
    std::uniform_int_distribution<size_t> distribution(0, numRows - 1); // uniform distribution in the range [0, numRows - 1]

    if (isCSC) {
        for (size_t i = 0; i < indices.size(); ++i) {
            size_t row = distribution(generator);
            sizes_t col = indices[i];
            std::swap(values[i], values[row * numCols + col]);
            std::swap(indices[i], indices[row * numCols + col]);
        }
    } else { // CSR
        for (size_t i = 0; i < values.size(); ++i) {
            size_t row = i / numCols;
            size_t col = i % numCols;
            if (row < numRows && col >= 0 && col < numCols) {
                std::uniform_int_distribution<DataType> distribution(std::min(values[i], numRows - row - 1), std::min(values[i], numRows - row));
                values[i] = distribution(generator);
            }
        }
    }
}
