#include <stdio.h>
#include <stdlib.h>
#include <mysql.h>
#include <string.h>
#include <stdbool.h>

#define MIN_BLOCK_SIZE 1024 * 1024

typedef struct {
    MYSQL* db;
    MYSQL_ROW row;
    MYSQL_RES* res;
    size_t keys_count;
    size_t current_key;
    uint64_t file_size;
} LoadDataContext;

void load_data_key(LoadDataContext* context) {
    if (context->current_key >= context->keys_count) {
        return;
    }

    if (context->file_size + context->db->rows_affected > MIN_BLOCK_SIZE) {
        context->db->commit();
        context->file_size = 0;
    }

    context->row = mysql_fetch_row(context->res);
    if (!context->row) {
        context->db->commit();
        return;
    }

    if (mysql_query(context->db, "INSERT INTO table_name (key1, key2, ...) VALUES (?, ?, ...)") != 0) {
        fprintf(stderr, "Error: %s\n", mysql_error(context->db));
        context->db->rollback();
        return;
    }

    context->file_size += mysql_affected_rows(context->db);
    context->current_key++;
}

void load_data(const char* db_name, const char* table_name, const char** keys, size_t keys_count) {
    LoadDataContext context = {0};
    context.db = mysql_init(NULL);
    context.db->reconnect = true;

    if (!mysql_real_connect(context.db, "", "", db_name, 0, NULL, 0, NULL)) {
        fprintf(stderr, "Error: %s\n", mysql_error(context.db));
        exit(1);
    }

    if (mysql_query(context.db, "USE table_name") != 0) {
        fprintf(stderr, "Error: %s\n", mysql_error(context.db));
        mysql_close(context.db);
        exit(1);
    }

    context.res = mysql_query(context.db, "SELECT * FROM table_name");
    if (!context.res) {
        fprintf(stderr, "Error: %s\n", mysql_error(context.db));
        mysql_close(context.db);
        exit(1);
    }

    context.keys_count = keys_count;

    for (context.current_key = 0; context.current_key < context.keys_count; context.current_key++) {
        load_data_key(&context);
    }

    mysql_free_result(context.res);
    mysql_close(context.db);
}
