        for (Vertex j = std::next(i); j != last; ++j) {
            if (i != j) { // Skip self-loops
                temp_list.emplace_back(*i, *j);
                adj_list[*i].degree++;
                adj_list[*j].degree++;
            }
        }
    }

    // Transfer edges from temporary list to adjacency list
    for (auto &edge : temp_list) {
        adj_list[edge.first].head.emplace_back(std::make_unique<std::list<Vertex>::value_type>(edge.second));
