#include <cstdint>
#include <cmath> // for round function

int64_t EstimateStorageRequirement(double threshold, int num_angles) {
  constexpr double KB = 1024.0;
  constexpr double MB = KB * KB;
  constexpr double GB = MB * KB;
  constexpr double TB = GB * KB;

  int64_t storage_in_bytes = static_cast<int64_t>(num_angles * sizeof(double) * (1 + std::ceil(threshold / 32.0)));
  int64_t storage_unit = KB; // default unit is KB

  if (storage_in_bytes >= TB) {
    storage_unit = TB;
    storage_in_bytes /= TB;
  } else if (storage_in_bytes >= GB) {
    storage_unit = GB;
    storage_in_bytes /= GB;
  } else if (storage_in_bytes >= MB) {
    storage_unit = MB;
    storage_in_bytes /= MB;
  }

  return round(storage_in_bytes * storage_unit);
}
