#define MAX_PATH_LENGTH 256

bool is_safe_directory(const char *path) {
    size_t base_path_len = strlen("/safe/directory/");
    size_t path_len = strlen(path);

    if (path_len < base_path_len) {
        return false;
    }

    if (strncmp("/safe/directory/", path, base_path_len) != 0) {
        return false;
    }

    char normalized_path[MAX_PATH_LENGTH];
    if (realpath(path, normalized_path) == NULL) {
        perror("Error normalizing path");
        return false;
    }

    if (strncmp(normalized_path, "/safe/directory/", base_path_len) != 0) {
        free(normalized_path);
        return false;
    }

    free(normalized_path);
    return true;
}

