#include <GL/gl.h> // OpenGL header
#include <vector> // For storing expected pixel values
#include <cstdlib> // For std::exit in case of validation failure

void verify_pixels(GLuint framebuffer, std::vector<unsigned char> expected_pixels, int width, int height, int format, int type) {
    GLint read_buffer; // OpenGL read buffer identifier
    GLenum pixels_format, pixels_type;
    GLsizeiptr read_buffer_size;
    unsigned char *read_buffer_data;

    // Set the read buffer to the specified framebuffer
    glBindFramebuffer(GL_READ_FRAMEBUFFER, framebuffer);

    // Get the format and type of the pixels in the framebuffer
    glGetFramebufferAttachmentParameteriv(GL_READ_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE, &pixels_format);
    glGetFramebufferAttachmentParameteriv(GL_READ_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE, &pixels_type);

    // Check that the format and type match the expected values
    if (pixels_format != GL_FRAMEBUFFER && pixels_type != type) {
        std::cerr << "Invalid pixel format or type in framebuffer!" << std::endl;
        std::exit(EXIT_FAILURE);
    }

    // Determine the size of the read buffer based on the number of pixels
    read_buffer_size = width * height * sizeof(unsigned char);

    // Allocate memory for the read buffer and bind it as the read buffer
    read_buffer_data = new unsigned char[read_buffer_size];
    glReadBuffer(GL_COLOR_ATTACHMENT0);
    glReadPixels(0, 0, width, height, GL_RED, GL_UNSIGNED_CHAR, read_buffer_data);

    // Compare the read pixels with the expected pixels
    for (size_t i = 0; i < expected_pixels.size(); i++) {
        if (expected_pixels[i] != read_buffer_data[i]) {
            std::cerr << "Expected pixel value at index " << i << " did not match the read pixel value!" << std::endl;
            std::cerr << "Expected: 0x" << std::hex << static_cast<int>(expected_pixels[i]) << std::dec << std::endl;
            std::cerr << "Read:    0x" << std::hex << static_cast<int>(read_buffer_data[i]) << std::dec << std::endl;
            std::exit(EXIT_FAILURE);
        }
    }

    // Free the memory allocated for the read buffer
    delete[] read_buffer_data;

    // Unbind the read buffer
    glBindFramebuffer(GL_READ_FRAMEBUFFER, 0);
}
