pthread_key_t tls_key; // thread-local storage key
uint64_t tls_value; // thread-local storage value

int rand_init() {
    int err;

    // Initialize thread-local storage key
    err = pthread_key_create(&tls_key, NULL);
    if (err) {
        perror("pthread_key_create");
        return err;
    }

    // Initialize thread-local storage value with a random seed
    err = pthread_setspecific(tls_key, &tls_value);
    if (err) {
        perror("pthread_setspecific");
        pthread_key_delete(tls_key);
        return err;
    }

    // Generate a random seed for the thread-local storage value
    secrets_urandom(&tls_value, sizeof(tls_value));

    return 0;
}

int RandUInt64() {
    pthread_t self = pthread_self();
    uint64_t new_value;

    // Initialize thread-local storage if not already initialized
    if (!pthread_getspecific(tls_key)) {
        int err = rand_init();
        if (err) {
            perror("rand_init");
            return err;
        }
    }

    // Copy the current thread-local storage value to a new variable
    pthread_getspecific(tls_key, &new_value);

    // Generate a new random number based on the current thread-local storage value
    secrets_urandom(&new_value, sizeof(new_value));

    // Update the thread-local storage value with the new random number
    pthread_setspecific(tls_key, &new_value);

    // Return the old thread-local storage value as the random number
    return (int)new_value;
}
