#include <iostream>
#include <vector>
#include <chrono>
#include <random>

const int WIDTH = 1024;
const int HEIGHT = 768;

void fillRandomImage(std::vector<std::vector<int>>& image) {
  std::random_device rd;
  std::mt19937 gen(rd());
  std::uniform_int_distribution<> dis(0, 255);

  image.resize(HEIGHT);
  for (auto& row : image) {
    row.resize(WIDTH);
    std::generate(row.begin(), row.end(), [&]() { return dis(gen); });
  }
}

auto measureAccessTime(const std::vector<std::vector<int>>& image, int x, int y) {
  auto start = std::chrono::high_resolution_clock::now();
  image[y][x];
  auto end = std::chrono::high_resolution_clock::now();
  return std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
}

void testAccessMethods(const std::vector<std::vector<int>>& image) {
  int x = 0, y = 0;

  auto start = std::chrono::high_resolution_clock::now();
  for (int i = 0; i < 100000; i++) {
    image[y][x];
  }
  auto directAccessTime = std::chrono::duration_cast<std::chrono::nanoseconds>(
      std::chrono::high_resolution_clock::now() - start).count();

  start = std::chrono::high_resolution_clock::now();
  for (int i = 0; i < 100000; i++) {
    int temp = image[y][x];
    image[y][x] = temp + 1;
    temp = image[y][x];
    image[y][x] = temp;
  }
  auto boundaryClampingTime = std::chrono::duration_cast<std::chrono::nanoseconds>(
      std::chrono::high_resolution_clock::now() - start).count();

  start = std::chrono::high_resolution_clock::now();
  for (int i = 0; i < 100000; i++) {
    image.at(y).at(x).first++;
  }
  auto scalarAccessTime = std::chrono::duration_cast<std::chrono::nanoseconds>(
      std::chrono::high_resolution_clock::now() - start).count();

  std::cout << "Direct access time: " << directAccessTime << " ns\n";
  std::cout << "Boundary clamping time: " << boundaryClampingTime << " ns\n";
  std::cout << "Scalar access time: " << scalarAccessTime << " ns\n";
}

int main() {
  std::vector<std::vector<int>> image(HEIGHT, std::vector<int>(WIDTH));
  fillRandomImage(image);

  std::cout << "Filled image with random values.\n";
  testAccessMethods(image);

  return 0;
}
