#include <cstddef> // for size_t
#include <cstring> // for memmove, memset
#include <new> // for std::nothrow

template <typename PixelType>
void verticalFlip(PixelType** image, std::size_t width, std::size_t height) {
  if (!image || !width || !height) {
    return;
  }

  // Allocate memory for the temporary array
  PixelType* temp_image = static_cast<PixelType*>(::operator new(sizeof(PixelType) * width * (height + 1)));
  if (!temp_image) {
    throw std::bad_alloc();
  }

  // Copy the input image data to the temporary array
  std::size_t image_size = width * height;
  std::size_t temp_image_size = width * (height + 1);
  std::size_t temp_image_stride = width * sizeof(PixelType);

  std::memcpy(temp_image, image, image_size * sizeof(PixelType));

  // Flip the image data in the temporary array
  for (std::size_t y = 0; y < height; ++y) {
    std::size_t src_offset = y * temp_image_stride;
    std::size_t dest_offset = (height - y - 1) * temp_image_stride;

    std::memmove(temp_image + dest_offset, temp_image + src_offset, temp_image_stride);
  }

  // Copy the flipped image data back to the input array
  std::memcpy(image, temp_image, image_size * sizeof(PixelType));

  // Restore the default alignment of the pixels in the input array
  std::memset(temp_image + image_size, 0, temp_image_size - image_size);

  // Free the temporary array
  ::operator delete(temp_image, std::nothrow);
}
