#include <stdio.h>
#include <stdlib.h>
#include <elf.h>

void print_symbol(Elf_Internal_Sym *sym, char *strtab, size_t strtab_size) {
  const char *sstr = sym ? strtab + sym->st_name : "_<unknown_symbol_name>";
  printf("%p %lu %s\n", (void *)sym->st_value, sym->st_size, sstr);
}

void process_symbols(Elf *elf, Elf_Scn *section, char *strtab, size_t strtab_size) {
  Elf_Internal_Sym *sym = NULL;
  Elf_Data *strdata = NULL;
  size_t strtab_len = 0;
  int ret = 0;

  if (section == NULL || section->sh_type != SHT_SYMTAB) {
    fprintf(stderr, "Invalid section type: %d\n", section->sh_type);
    return;
  }

  strdata = elf_getdata(elf, section->sh_link);
  if (strdata == NULL || strdata->d_size < 1) {
    fprintf(stderr, "Failed to retrieve string table\n");
    return;
  }

  strtab = (char *)elf_getdata(elf, section->sh_link)->d_buf;
  strtab_len = strdata->d_size;

  sym = elf_sym_iter(elf, section, ELF_SYM_UNDEF | ELF_SYM_STAB, NULL);
  while (sym != NULL) {
    print_symbol(sym, strtab, strtab_len);
    sym = elf_sym_iter(elf, section, ELF_SYM_UNDEF | ELF_SYM_STAB, sym);
  }

  elf_sym_end(elf, section);

  if (strdata) {
    elf_data_destroy(strdata);
  }
}

void print_dynamic_symbols(Elf *elf, Elf_Scn *section, char *strtab, size_t strtab_size) {
  if (section == NULL || section->sh_type != SHT_DYNSYM) {
    fprintf(stderr, "Invalid section type: %d\n", section->sh_type);
    return;
  }

  process_symbols(elf, section, strtab, strtab_size);
}

int main(int argc, char **argv) {
  Elf *elf = NULL;
  Elf_Scn *section = NULL;
  int ret = 0;

  if (argc != 2) {
    fprintf(stderr, "Usage: %s <elf_file>\n", argv[0]);
    return 1;
  }

  elf = elf_begin(argv[1], ELF_C_READ, NULL);
  if (elf == NULL) {
    fprintf(stderr, "Failed to open file: %s\n", argv[1]);
    return 1;
  }

  section = elf_getscn(elf, 0);
  print_dynamic_symbols(elf, section, NULL, 0);

  elf_end(elf);

  return 0;
}
