// Function to ensure proper initialization and cleanup of SHA-256 context
static void sha256_init_ctx(SHA256_CTX *ctx) {
    if (SHA256_Init(ctx) != 1) {
        SHA256_CTX old_ctx;
        SHA256_Init(&old_ctx); // Free old resources
        SHA256_Final(NULL, ctx, SHA256_DIGEST_LENGTH); // Free new resources
        SHA256_Init(ctx); // Re-initialize
    }
}

// Function to compute hash value of given string using SHA-256
uint8_t hash_string_sha256(const char *str, size_t len) {
    SHA256_CTX ctx;
    uint8_t hash[SHA256_DIGEST_LENGTH];

    sha256_init_ctx(&ctx); // Initialize context
    SHA256_Update(&ctx, str, len); // Update context with input data
    SHA256_Final(hash, &ctx); // Get hash value

    // Free resources
    SHA256_Init(&ctx);

    return len; // Return length for successful hash computation
}

