#include <stdio.h>
#include <stdlib.h>
#include <cdio/cdio.h>

char *calculate_discid(CDIO_CD_ROM *cd) {
    if (!cd) {
        fprintf(stderr, "Invalid CD-ROM structure\n");
        return NULL;
    }

    uint64_t sum = 0;
    for (uint i = 0; i < cd->number_of_tracks; i++) {
        if (cd->tracks[i].length == 0) {
            continue;
        }
        sum += cd->tracks[i].lba;
    }

    double result = (double)sum / 0xff;
    if (result == 0) {
        fprintf(stderr, "Error: Sum of track LBAs is zero\n");
        return NULL;
    }

    uint32_t discid[4];
    memcpy(discid, &((uint32_t)result), sizeof(discid));

    char discid_str[18];
    snprintf(discid_str, sizeof(discid_str), "%08x%08x%08x%08x", discid[0], discid[1], discid[2], discid[3]);

    // Debug log
    fprintf(stderr, "Calculated DISCID: %s\n", discid_str);

    return strdup(discid_str);
}
