#include <cstdio>
#include <cstdint>
#include <string>
#include <vector>

constexpr size_t MAX_QUERY_LENGTH = 4096;

struct UrlComponents {
    std::string host;
    std::string path;
    bool is_cgi = false;
    bool has_filename = false;
    bool has_permalink = false;
    int depth = 0;
    int score = 0;
};

// Helper function to check if a character is a reserved character in a query string
bool is_reserved_char(char c) {
    static const std::vector<char> reserved_chars = {'(', ')', '[', ']', '{', '}', ';', ':', '&', '=', '+', '$', ',', '*'};
    return std::find(reserved_chars.begin(), reserved_chars.end(), c) != reserved_chars.end();
}

// Helper function to encode a single character for a query string
void encode_char(std::string& query, char c) {
    if (c >= ' ' && c != '+' && !is_reserved_char(c)) {
        query.push_back(c);
    } else {
        char encoded[3];
        snprintf(encoded, sizeof(encoded), "%%%02X", static_cast<unsigned char>(c));
        query.append(encoded, 3);
    }
}

// Function to generate a query string for a search engine
std::string generate_query_string(const std::string& url) {
    UrlComponents url_components;
    std::sscanf(url.c_str(), "http://%[^/]%[^?]%*[?&]%[^&]%[^&]%[^&]%[^&]%[^&]%n",
                url_components.host.data(), url_components.path.data(),
                &url_components.depth, &url_components.is_cgi,
                &url_components.has_filename, &url_components.has_permalink, &url_components.score);

    std::string query;
    snprintf(query.data(), MAX_QUERY_LENGTH, "host=%s&path_depth=%d&non_cgi=%d&filename=%d&permalink=%d&score=%d",
             url_components.host.c_str(), url_components.depth, !url_components.is_cgi, url_components.has_filename, url_components.has_permalink, url_components.score);

    // Encode any reserved characters in the query string
    for (size_t i = 0; i < query.size(); ++i) {
        if (is_reserved_char(query[i])) {
            encode_char(query, query[i]);
        }
    }

    return query;
}
