#include <iostream>
#include <filesystem>
#include <vector>
#include <numeric>
#include <stdexcept>

namespace fs = std::filesystem;

constexpr size_t MAX_DESCRIPTOR_LENGTH = 1024;

struct Descriptor {
  uint8_t data[MAX_DESCRIPTOR_LENGTH];
  bool has_alpha;
};

void load_descriptor(const fs::path& file_path, Descriptor& descriptor) {
  std::ifstream file(file_path, std::ios::binary);

  if (!file.is_open()) {
    throw std::runtime_error("Failed to open file: " + file_path.string());
  }

  file.read(reinterpret_cast<char*>(&descriptor.data), MAX_DESCRIPTOR_LENGTH);

  if (file.gcount() != MAX_DESCRIPTOR_LENGTH) {
    throw std::runtime_error("Invalid descriptor length in file: " + file_path.string());
  }

  file.close();
}

size_t get_num_descriptors(const std::vector<fs::path>& file_paths) {
  size_t num_descriptors = 0;

  for (const auto& file_path : file_paths) {
    Descriptor descriptor;
    try {
      load_descriptor(file_path, descriptor);
      num_descriptors++;
    } catch (const std::exception& e) {
      std::cerr << "Error loading descriptor from file: " << file_path.string() << ": " << e.what() << std::endl;
    }
  }

  return num_descriptors;
}

std::vector<Descriptor> load_descriptors(const std::vector<fs::path>& file_paths, bool include_alpha) {
  size_t num_descriptors = get_num_descriptors(file_paths);
  std::vector<Descriptor> descriptors(num_descriptors);

  for (size_t i = 0; i < num_descriptors; i++) {
    load_descriptor(file_paths[i], descriptors[i]);
    descriptors[i].has_alpha = include_alpha;
  }

  return descriptors;
}

std::vector<uint8_t> load_descriptors_to_matrix(const std::vector<Descriptor>& descriptors) {
  size_t num_descriptors = descriptors.size();
  size_t descriptor_length = descriptors[0].data_length();
  std::vector<uint8_t> matrix(num_descriptors * descriptor_length);

  std::copy(descriptors.begin(), descriptors.end(), std::begin(matrix));

  return matrix;
}
