} Edge;

void init_graph(Edge *graph, int num_nodes) {
    for (int i = 0; i < num_nodes; i++) {
        graph[i].node1 = i;
        graph[i].node2 = -1;
        graph[i].visited = false;
    }
}

bool add_edge(Edge *graph, int num_nodes, const char *edge) {
    int node1, node2;
    sscanf(edge, "%d-%d", &node1, &node2);

    if (node1 >= num_nodes || node2 >= num_nodes || node1 < 0 || node2 < 0) {
        return false;
    }

    if (graph[node1].node2 != -1 || graph[node2].node2 != -1) {
        return false;
    }

    graph[node1].node2 = node2;
    graph[node2].node2 = node1;

    return true;
}

int connected_components(Edge *graph, int num_nodes) {
    int num_components = 0;

    for (int i = 0; i < num_nodes; i++) {
        if (graph[i].visited) {
            continue;
        }

        int component = i;
        stack_t stack;
        stack_init(&stack, sizeof(int), 1024);
        stack_push(&stack, component);
        graph[component].visited = true;

        while (!stack_is_empty(&stack)) {
            int curr = stack_top(&stack);
            stack_pop(&stack);

            for (int j = 0; j < num_nodes; j++) {
                if (graph[j].node1 == curr || graph[j].node2 == curr) {
                    if (!graph[j].visited) {
                        stack_push(&stack, j);
                        graph[j].visited = true;
                    }
                }
            }
        }

        num_components++;
    }

    stack_destroy(&stack);
    return num_components;
}

