FILE *open_file(const char *filename, const char *mode) {
    FILE *file_ptr = fopen(filename, mode);
    if (file_ptr == NULL) {
        errno = errno;
        perror("Error opening file");
        return NULL;
    }

    return file_ptr;
}

void write_message(FILE *file_ptr, const char *message, size_t message_len) {
    size_t bytes_written;

    if (fwrite(message, message_len, 1, file_ptr) != 1) {
        perror("Error writing message to file");
        fclose(file_ptr);
        exit(EXIT_FAILURE);
    }

    if (ferror(file_ptr)) {
        perror("Error writing message to file");
        fclose(file_ptr);
        exit(EXIT_FAILURE);
    }

    bytes_written = ftell(file_ptr);
    fseek(file_ptr, 0, SEEK_SET);

    if (bytes_written != message_len) {
        perror("Error: Written message length does not match expected length");
        fclose(file_ptr);
        exit(EXIT_FAILURE);
    }
}

void close_file(FILE *file_ptr) {
    if (fclose(file_ptr) != 0) {
        perror("Error closing file");
        exit(EXIT_FAILURE);
    }
}

void read_message(FILE *file_ptr, char *buffer, size_t buffer_size) {
    size_t bytes_read;

    if (fread(buffer, 1, buffer_size - 1, file_ptr) < (buffer_size - 1)) {
        perror("Error reading message from file");
        fclose(file_ptr);
        exit(EXIT_FAILURE);
    }

    buffer[buffer_size - 1] = '\0';

    if (ferror(file_ptr)) {
        perror("Error reading message from file");
        fclose(file_ptr);
        exit(EXIT_FAILURE);
    }
}
