        const CIMValueArray& array = value.GetArray();
        str += "[";

        for (size_t i = 0; i < array.GetLength(); ++i) {
            appendCIMValueToString(array.GetValue(i), str);
            if (i < array.GetLength() - 1) {
                str += ", ";
            }
        }

        str += "]";
        return;
    }

    std::string valueStr;
    if (value.ConvertToString(valueStr)) {
        str += valueStr;
    } else {
        str += "Invalid value";
    }
}
