    if (rc != LCB_SUCCESS) {
        std::cerr << "Error connecting to server: " << lcb_strerror(cluster, rc) << std::endl;
        lcb_free(cluster);
        return 1;
    }

    lcb_bucket_t* bucket = lcb_bucket_new(cluster, bucket_name, LCB_WATCH_NONE);

    if (!bucket) {
        std::cerr << "Error creating bucket: " << lcb_strerror(cluster, rc) << std::endl;
        lcb_disconnect(cluster);
        lcb_free(cluster);
        return 1;
    }

    lcb_ITEM_STAT stat;
    lcb_item_t* item = lcb_fetch(bucket, query_string, 0, &stat);

    if (!item) {
        if (stat.rc != LCB_ITEM_NOT_FOUND) {
            std::cerr << "Error fetching item: " << lcb_strerror(cluster, stat.rc) << std::endl;
        }
        lcb_bucket_free(bucket);
        lcb_disconnect(cluster);
        lcb_free(cluster);
        return 1;
    }

