constexpr size_t GRID_WIDTH = 10;
constexpr size_t GRID_HEIGHT = 10;

class ToroidalGrid {
public:
    uint32_t GetCellIdentifier(uint32_t x, uint32_t y) {
        if (x >= GRID_WIDTH || y >= GRID_HEIGHT) {
            // Handle out-of-bounds coordinates
            return 0;
        }

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, GRID_WIDTH * GRID_HEIGHT);

        // Generate unique identifier for the cell
        uint32_t identifier = dis(gen);

        // Handle toroidal grid edges
        if (x < GRID_WIDTH / 2) {
            identifier += (GRID_WIDTH * GRID_HEIGHT - (GRID_WIDTH * (GRID_HEIGHT - y) + (GRID_WIDTH - x) * GRID_HEIGHT)) * 2;
        }
        if (y < GRID_HEIGHT / 2) {
            identifier += (GRID_WIDTH * (GRID_HEIGHT - y) + (GRID_WIDTH - x) * GRID_HEIGHT) * GRID_WIDTH;
        }

        return identifier;
    }
};
