#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <openssl/md5.h>

static int validate_input(const uint8_t *input, size_t length) {
    if (length < 1) {
        return -2;
    }

    if (length > INT32_MAX) {
        return -3;
    }

    return 0;
}

static int hash_input(const uint8_t *input, size_t length, uint8_t output[16]) {
    int status = validate_input(input, length);
    if (status < 0) {
        return status;
    }

    MD5_CTX md5_context;
    MD5_Init(&md5_context);
    MD5_Update(&md5_context, input, length);
    MD5_Final(output, &md5_context);

    return 0;
}

static void hex_encode(const uint8_t *input, size_t length, char *output) {
    for (size_t i = 0; i < length; ++i) {
        char byte_str[3];
        sprintf(byte_str, "%02x", input[i]);
        strcat(output, byte_str);
    }
}

int hash_byte_array(const uint8_t *input, size_t length) {
    int status = validate_input(input, length);
    if (status < 0) {
        return status;
    }

    uint8_t md5_hash[16];
    status = hash_input(input, length, md5_hash);
    if (status < 0) {
        return status;
    }

    char hex_output[65];
    hex_encode(md5_hash, sizeof(md5_hash), hex_output);

    // Return the hexadecimal hash as a null-terminated string
    size_t hex_length = strlen(hex_output);
    if (hex_length > 64) {
        return -1; // Hash is too long
    }

    // Copy the hexadecimal hash to a new buffer with a null terminator
    char output[65];
    memcpy(output, hex_output, hex_length + 1);

    return 0; // Hash is valid
}
