#include <chrono>
#include <random>
#include <iostream>

struct NetworkSender {
    int max_packet_rate = 10; // Maximum packet rate per second
    int current_packet_rate = 0;
    int current_packet_number = 0;
    int monitoring_start_packet = 0;
    int monitoring_duration_packets = 0;
    std::chrono::high_resolution_clock::time_point monitoring_start_time;
    double rtt = 0.0;
    double packet_loss_rate = 0.0;
    bool is_monitoring = false;

    void send_packet(int packet_number) {
        current_packet_number = packet_number;

        if (packet_number >= max_packet_rate * 1.7 && !is_monitoring) {
            monitoring_start_packet = packet_number;
            monitoring_start_time = std::chrono::high_resolution_clock::now();
            is_monitoring = true;
            std::cout << "Monitoring started. Current packet number: " << packet_number << std::endl;
            monitoring_duration_packets = std::rand() % ((int)(max_packet_rate * 1.7) + 1) + (int)(max_packet_rate * 1.1);
        }

        if (is_monitoring) {
            auto current_time = std::chrono::high_resolution_clock::now();
            auto elapsed_time = std::chrono::duration_cast<std::chrono::microseconds>(current_time - monitoring_start_time).count();
            rtt = elapsed_time / 2.0; // Round-trip time is half the elapsed time

            if (current_packet_number % 10 == 0) { // Simulate packet loss every 10 packets
                std::cout << "Packet loss detected. Current packet number: " << current_packet_number << std::endl;
                packet_loss_rate++;
            }

            if (current_packet_number >= monitoring_start_packet + monitoring_duration_packets) {
                is_monitoring = false;
                std::cout << "Monitoring stopped. Current packet number: " << current_packet_number << std::endl;
                std::cout << "RTT: " << rtt / 1000.0 << "ms" << std::endl;
                std::cout << "Packet loss rate: " << packet_loss_rate << "%" << std::endl;
                packet_loss_rate = 0.0;
            }
        }

        current_packet_rate++;
    }
};
