#include <cstring>
#include <string.h>
#include <cstdio>

std::string replaceByteWithHex(std::string str, size_t offset, const std::string& hex) {
    if (offset >= str.length()) {
        throw std::out_of_range("Offset out of range.");
    }

    char hexValue[3]; // assuming hex is a two-digit hexadecimal string
    std::strncpy(hexValue, hex.c_str(), 3);
    hexValue[2] = '\0'; // ensure null terminator

    char newByte = static_cast<char>(std::strtoul(hexValue, nullptr, 16));

    char newStr[str.length() + 1]; // allocate space for the modified string
    std::strncpy(newStr, str.c_str(), offset); // copy the prefix
    newStr[offset] = newByte; // replace the byte
    std::strncpy(newStr + offset + 1, str.c_str() + offset, str.length() - offset); // copy the suffix
    newStr[str.length()] = '\0'; // ensure null terminator

    std::string result(newStr); // create the result string
    return result;
}
