using namespace std;

bool withinEpsilon(int target, int sum, int epsilon) {
    return abs(target - sum) <= epsilon;
}

struct IntegerWithWeight {
    int value;
    int weight;

    IntegerWithWeight(int value, int weight) : value(value), weight(weight) {}
};

struct CompareIntegerWithWeight {
    bool operator()(const IntegerWithWeight& a, const IntegerWithWeight& b) {
        return a.weight > b.weight;
    }
};

int selectSubset(const vector<int>& integers, int target, int epsilon, int& numSelected) {
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dis(0, integers.size() - 1);

    unordered_map<int, int> runningSum;
    vector<IntegerWithWeight> candidates;

    for (int i = 0; i < integers.size(); ++i) {
        int value = integers[i];
        int weight = abs(value - target);
        candidates.push_back(IntegerWithWeight(value, weight));
        runningSum[value] += weight;
    }

    sort(candidates.begin(), candidates.end(), CompareIntegerWithWeight());

    int sum = 0;
    int numCandidates = candidates.size();
    numSelected = 0;

    while (numSelected < min(numCandidates, (int)ceil(0.5 + (double)numCandidates / epsilon))) {
        int index = dis(gen);
        int value = candidates[index].value;

        if (withinEpsilon(target, sum + value, epsilon)) {
            sum += value;
            numSelected++;
            continue;
        }

        if (runningSum.find(value) != runningSum.end()) {
            sum += value;
            numSelected++;
            runningSum.erase(value);
        } else {
            continue;
        }
    }

    return sum;
}
