#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <stdbool.h>

#define MAX_FILE_NAME_LENGTH 256
#define MAX_PATH_LENGTH 1024

typedef enum { WAV, UNKNOWN } FileFormat;

bool is_wav_format(const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        perror("Error opening file");
        return false;
    }

    char header[4] = { 0 };
    size_t bytes_read = fread(header, sizeof(char), 4, fp);
    fclose(fp);

    if (bytes_read != 4 || memcmp(header, "RIFF", 4) || memcmp(header + 8, "WAVE", 4)) {
        return false;
    }

    return true;
}

char *load_sound_file(const char *path, const char *extension) {
    char file_name[MAX_FILE_NAME_LENGTH];
    strcpy(file_name, path);
    strcat(file_name, "/");
    strcat(file_name, extension);

    FILE *fp = fopen(file_name, "rb");
    if (!fp) {
        perror("Error opening file");
        return strdup("File not found.");
    }

    fseek(fp, 0, SEEK_END);
    size_t file_size = ftell(fp);
    rewind(fp);

    char *sound_data = malloc(file_size);
    size_t bytes_read = fread(sound_data, sizeof(char), file_size, fp);
    fclose(fp);

    if (bytes_read != file_size) {
        free(sound_data);
        return strdup("Error reading file.");
    }

    FileFormat file_format = UNKNOWN;
    if (is_wav_format(file_name)) {
        file_format = WAV;
    } else {
        free(sound_data);
        return strdup("Invalid file format.");
    }

    return sound_data;
}
