// Function to perform atomic addition on aligned memory location
inline int64_t atomic_add_aligned(volatile int64_t* location, int64_t value) {
    int32_t old;
    do {
        old = *location;
    } while (!__sync_add_and_fetch(location, value + old));
    return old;
}

// Function to perform atomic addition on unaligned memory location
inline int64_t atomic_add_unaligned(volatile void* location, int64_t value, size_t size) {
    int32_t* aligned_location = static_cast<int32_t*>(const_cast<void*>(location));
