#include <string.h>
#include <errno.h>

#define MAX_FILENAME_LENGTH 256
#define DATA_BUFFER_SIZE 1024

int save_data_to_file(const char *filename, const char *data) {
    FILE *file;
    size_t file_size = strlen(data) + 1;
    char *absolute_filename = malloc(MAX_FILENAME_LENGTH * sizeof(char));
    int ret = 0;

    if (strchr(filename, '/') || strchr(filename, '\\')) {
        free(absolute_filename);
        errno = EINVAL;
        return -1;
    }

    strcpy(absolute_filename, "./");
    strcat(absolute_filename, filename);
    strcat(absolute_filename, ".txt");

    file = fopen(absolute_filename, "w");
    if (file == NULL) {
        free(absolute_filename);
        errno = errno;
        return -1;
    }

    size_t bytes_written = fwrite(data, 1, file_size, file);
    if (bytes_written != file_size) {
        ret = -1;
    }

    if (ferror(file)) {
        ret = -1;
    }

    if (ret < 0) {
        char error_message[1024];
        strerror_r(errno, error_message, sizeof(error_message));
        fprintf(stderr, "Error writing to file '%s': %s\n", absolute_filename, error_message);
    }

    fclose(file);
    free(absolute_filename);

    return ret;
}
