#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <wchar.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>

#define MAX_FILE_SIZE ((size_t)-1)
#define MAX_BUFFER_SIZE 4096

int read_file_to_unicode_string(const char *path, wchar_t **out_str, int *err_rc) {
    int file_fd;
    struct stat file_stat;
    size_t file_size;
    wchar_t *buffer;
    size_t bytes_read;
    int ret;

    if (stat(path, &file_stat) < 0) {
        *err_rc = errno;
        return -1;
    }

    if (S_ISDIR(file_stat.st_mode)) {
        *err_rc = ENOTDIR;
        return -1;
    }

    file_size = file_stat.st_size;

    buffer = (wchar_t *)calloc(MAX_BUFFER_SIZE, sizeof(wchar_t));
    if (!buffer) {
        *err_rc = errno;
        return -1;
    }

    file_fd = open(path, O_RDONLY);
    if (file_fd < 0) {
        free(buffer);
        *err_rc = errno;
        return -1;
    }

    bytes_read = fread(buffer, sizeof(wchar_t), MAX_BUFFER_SIZE, (FILE *)file_fd);
    if (bytes_read < 0) {
        close(file_fd);
        free(buffer);
        *err_rc = errno;
        return -1;
    }

    if (file_size > MAX_FILE_SIZE) {
        close(file_fd);
        free(buffer);
        *err_rc = ENOMEM;
        return -1;
    }

    if (file_size > bytes_read) {
        size_t remaining = file_size - bytes_read;
        wchar_t *new_buffer;

        new_buffer = (wchar_t *)realloc(buffer, (MAX_BUFFER_SIZE + remaining) * sizeof(wchar_t));
        if (!new_buffer) {
            close(file_fd);
            free(buffer);
            *err_rc = errno;
            return -1;
        }

        ret = fread(new_buffer + bytes_read, sizeof(wchar_t), remaining, (FILE *)file_fd);
        if (ret < 0) {
            free(new_buffer);
            close(file_fd);
            *err_rc = errno;
            return -1;
        }

        free(buffer);
        buffer = new_buffer;
    }

    *out_str = buffer;
    *err_rc = 0;

    close(file_fd);

    return 0;
}
