const int MAX_INDEX = std::numeric_limits<int>::max() / 2; // Max index for array bounds check

int find_best_combination(const std::vector<std::pair<int, bool>>& pairs, int target) {
    int total = 0;
    std::vector<int> selected;
    std::mt19937 gen(std::random_device{}());
    std::uniform_int_distribution<> dis(0, pairs.size() - 1);

    while (total < target) {
        int index = dis(gen);
        int value = pairs[index].first;

        if (!pairs[index].second && total + value <= target) {
            total += value;
            selected.push_back(value);
            pairs[index].second = true;
        }
    }

    if (total > target) {
        for (int i = selected.size() - 1; i >= 0; --i) {
            pairs[std::find(pairs.begin(), pairs.end(), std::make_pair(selected[i], true))->first].second = false;
            total -= selected[i];
        }
        return -1;
    }

    return total;
}
