#define SERVER_NAME_REGEX "^[^:]+(?=:)[^ ]+"

typedef struct {
    char *server_name;
    char *password;
} server_credentials_t;

server_credentials_t extract_server_credentials(const char *input_string) {
    server_credentials_t credentials = {NULL, NULL};
    regex_t regex;
    regmatch_t match;

    if (regex_comp(&regex, SERVER_NAME_REGEX, REG_EXTENDED | REG_NEWLINE)) {
        regex_free(&regex);
        return (server_credentials_t){NULL, NULL};
    }

    if (regex_search(input_string, &regex, &match, 1, 0)) {
        size_t server_name_length = match.rm_eo - match.rm_so;
        credentials.server_name = malloc(server_name_length + 1);
        strncpy(credentials.server_name, input_string + match.rm_so, server_name_length + 1);

        size_t password_start_index = match.rm_eo;
        size_t password_length = strlen(input_string + password_start_index);
        credentials.password = malloc(password_length + 1);
        strncpy(credentials.password, input_string + password_start_index, password_length + 1);
    } else {
        free(credentials.server_name);
        free(credentials.password);
        regex_free(&regex);
        return (server_credentials_t){NULL, NULL};
    }

    regex_free(&regex);
    return credentials;
}
