#include <random> // For std::random_device and std::mt19937
#include <vector> // For std::vector
#include <type_traits> // For std::ptrdiff_t

// Function to initialize the random number generator with a random seed
void init_random() {
    static std::random_device rd; // Will be initialized only once on program start
    static std::mt19937 gen(rd()); // Mersenne Twister generator
}

// Secure random number generator function
std::ptrdiff_t secure_random() {
    init_random(); // Ensure random seed is initialized
    std::uniform_int_distribution<> dis(0, 1000000); // Distribution between 0 and 1000000
    return dis(std::mt19937{std::random_device{}()}); // Generate and return random number
}

// Template version of the secure random number generator function
template <typename T>
std::ptrdiff_t secure_random(std::vector<T>& vec) {
    init_random(); // Ensure random seed is initialized
    std::uniform_int_distribution<> dis(0, static_cast<int>(vec.size()) - 1); // Distribution based on vector size
    std::mt19937 gen(std::random_device{}()); // Mersenne Twister generator
    std::ptrdiff_t index = dis(gen); // Generate and return random index
    return index;
