    std::vector<std::string> components;
    std::smatch match;
    std::regex urlRegex(R"((\w+)://([^/?#]+))");

    if (std::regex_search(url, match, urlRegex)) {
        components.push_back(match.str(1)); // protocol
        std::size_t hostPortBegin = match.spos() + match.length();

        std::regex hostPortRegex(R"((:[0-9]+)?|[^/?#]+)");
        if (std::regex_search(url, match, hostPortRegex, hostPortBegin)) {
            components.push_back(match.str()); // host and port
            std::size_t portBegin = match.spos();
            std::size_t portEnd = match.slen();
            if (match.length() > match.str().length()) {
                components.push_back(match.str().substr(portBegin + 1, portEnd - portBegin - 1)); // port
            }
        } else {
            components.push_back(match.str()); // host
        }

        std::size_t pathBegin = match.spos() + match.length();
        std::regex pathRegex(R"([^?#]*)");
        if (std::regex_search(url, match, pathRegex, pathBegin)) {
            components.push_back(match.str()); // path
        }
    }

    return components;
}
