#include <stdlib.h>
#include <stdio.h>
#include "sktypes.h" // Assuming SkScalar is defined here
#include "skmem.h" // Assuming sk_malloc_throw is defined here

SkDashPathEffect* CreateDashPathEffect(const SkScalar intervals[], int count, SkScalar phase, bool scaleToFit) {
    SkDashPathEffect* dashEffect = NULL;
    SkScalar totalLength = 0;

    // Allocate memory for the SkDashPathEffect struct using sk_malloc_throw
    dashEffect = (SkDashPathEffect*)sk_malloc_throw(sizeof(SkDashPathEffect));

    // Check if memory allocation was successful
    if (!dashEffect) {
        return NULL;
    }

    // Initialize the fIntervals and fCount fields
    dashEffect->fIntervals = intervals;
    dashEffect->fCount = count;

    // Calculate the total length of the intervals
    for (int i = 0; i < count; ++i) {
        totalLength += intervals[i];
    }

    // Initialize the fIntervalLength field
    dashEffect->fIntervalLength = totalLength;

    // If scaleToFit is true, calculate the dash pattern length to fit the stroke width
    if (scaleToFit) {
        // Calculate the stroke width and scale the dash pattern length accordingly
        // (Assuming a function to get the stroke width is available)
        SkScalar strokeWidth = GetStrokeWidth();
        totalLength = strokeWidth / dashEffect->fIntervalLength * dashEffect->fIntervalLength;
        dashEffect->fIntervalLength = totalLength;
    }

    // Set the phase
    dashEffect->fPhase = phase;

    return dashEffect;
}
