#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>

#pragma pack(push, 1)
typedef struct {
    char CURP[10];
    char celular[10];
    char partido[5];
} DataPacket;
#pragma pack(pop)

int main() {
    int sockfd;
    int port = 12345;
    int addrlen;
    struct sockaddr_in serv_addr;
    DataPacket data = {"1234567890-1", "1112223334", "ABCDE"};
    char buffer[1024];
    socklen_t len;
    ssize_t n;

    // Initialize socket descriptor to an invalid value
    sockfd = -1;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Initialize serv_addr structure
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(port);
    serv_addr.sin_addr.s_addr = htonl(INADDR_ANY);

    // Send data packet
    if ((n = sendto(sockfd, &data, sizeof(DataPacket), 0, (struct sockaddr *)&serv_addr, sizeof(serv_addr))) < 0) {
        perror("sendto");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Receive response
    addrlen = sizeof(serv_addr);
    if ((n = recvfrom(sockfd, buffer, sizeof(buffer), 0, (struct sockaddr *)&serv_addr, &addrlen)) < 0) {
        perror("recvfrom");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Validate response size
    if (n > sizeof(buffer)) {
        fprintf(stderr, "Invalid response size: %ld\n", (long)n);
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Print response
    printf("Received response:\n");
    printf("CURP: %s\n", buffer);
    printf("celular: %s\n", buffer + sizeof(DataPacket.CURP));
    printf("partido: %s\n", buffer + sizeof(DataPacket.CURP) + sizeof(DataPacket.celular));

    // Close socket
    close(sockfd);

    // Exit with success status
    exit(EXIT_SUCCESS);
}
