void process_video(int width, int height) {
    char input_width[MAX_INPUT_LENGTH];
    char input_height[MAX_INPUT_LENGTH];
    char command[MAX_COMMAND_LENGTH];

    // Convert input width and height to strings
    sprintf(input_width, "%d", width);
    sprintf(input_height, "%d", height);

    // Build command string using strcat and sprintf functions
    strcpy(command, "./video_processing_tool ");
    strcat(command, "--width=");
