    strcat(command, " ");
    strcat(command, "--height=");
    strcat(command, input_height);

    // Execute the command using popen function which is safer than system()
    FILE *pipe = popen(command, "r");
    if (pipe == NULL) {
        perror("popen failed");
        exit(EXIT_FAILURE);
    }

    // Read the output of the command and print it
    char buffer[128];
    size_t num_read;
    while ((num_read = fread(buffer, sizeof(char), sizeof(buffer), pipe)) > 0) {
        fwrite(buffer, sizeof(char), num_read, stdout);
    }

    pclose(pipe);
}

int main() {
    int width, height;

    printf("Enter frame width: ");
    scanf("%d", &width);

    printf("Enter frame height: ");
    scanf("%d", &height);

    process_video(width, height);

    return 0;
}
