    TorHandler &operator=(const TorHandler &) = delete;

    TorHandler(const std::string &private_key) {
        tor = tor_initdb("/tmp/tor_data", NULL);
        if (tor == nullptr) {
            throw std::runtime_error("Failed to initialize Tor database");
        }

        fd = tor_ctrl_socket(tor);
        if (fd < 0) {
            throw std::runtime_error("Failed to create Tor control socket");
        }

        std::string cmd = "ADD_ONION " + private_key + "\n";
        int ret = tor_ctrl_send(tor, cmd.c_str(), cmd.size(), 0);
        if (ret < 0) {
            throw std::runtime_error("Failed to create Tor hidden service: " + std::string(tor_strerror(ret)));
        }

        char response[4096];
        ret = tor_ctrl_recv(tor, response, sizeof(response), 0);
        if (ret < 0) {
            throw std::runtime_error("Failed to receive Tor hidden service address: " + std::string(tor_strerror(ret)));
        }

        onion_address = response;
        std::size_t pos = onion_address.find("\n");
        if (pos != std::string::npos) {
            onion_address = onion_address.substr(0, pos);
        }
    }

    TorCtrlAuth *get_auth() {
        return tor_new_auth_anonymous(tor);
    }
};

