#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <cstring>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <cstdlib>

std::string calculate_sha256_hmac(const std::string& message, const std::string& secret) {
    if (message.empty() || secret.empty()) {
        throw std::invalid_argument("Message and secret cannot be empty.");
    }

    const size_t secret_length = secret.length();
    const size_t message_length = message.length();

    unsigned char digest[SHA256_DIGEST_LENGTH];
    unsigned char key[SHA256_DIGEST_LENGTH];
    unsigned char iv[SHA256_DIGEST_LENGTH];

    std::memcpy(key, secret.c_str(), secret_length);
    std::memset(iv, 0x00, SHA256_DIGEST_LENGTH);

    HMAC(EVP_sha256(), key, secret_length, (unsigned char*)message.c_str(), message_length, iv, digest, SHA256_DIGEST_LENGTH);

    std::vector<unsigned char> hex_digest(SHA256_DIGEST_LENGTH * 2);
    for (size_t i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        char str[3];
        snprintf(str, sizeof(str), "%02x", digest[i]);
        hex_digest[i * 2] = str[0];
        hex_digest[i * 2 + 1] = str[1];
    }

    return std::string(hex_digest.begin(), hex_digest.end());
}
```

