float* create_2d_array_and_compute_differences(size_t lLBytes, size_t height) {
    if (lLBytes < (MIN_WIDTH * MIN_HEIGHT * sizeof(float))) {
        throw std::invalid_argument("Insufficient memory for 2D array.");
    }

    size_t width = static_cast<size_t>(std::sqrt(static_cast<float>(lLBytes) / sizeof(float)));
