        }
    }

    for (size_t i = 0; i < height; ++i) {
        for (size_t j = 0; j < width; ++j) {
            float current_element = array[i][j];

            if (i > 0)
                array[i][j] += array[i - 1][j] - current_element;

            if (j > 0)
                array[i][j] += array[i][j - 1] - array[i][j];

