template<typename T>
class DynamicArray {
private:
    size_t capacity;
    size_t size;
    T* data;

public:
    DynamicArray() : capacity(0), size(0), data(nullptr) {}

    DynamicArray(size_t initial_capacity) : capacity(initial_capacity), size(0), data(new T[initial_capacity]) {
        if (data == nullptr) {
            std::cerr << "Error: Failed to allocate memory for dynamic array.\n";
            throw std::bad_alloc();
        }
    }

    ~DynamicArray() {
        if (data != nullptr) {
            delete[] data;
        }
    }

    void push_back(const T& value) {
        if (size >= capacity) {
            capacity *= 2;
            T* new_data = new T[capacity];
            if (new_data == nullptr) {
                std::cerr << "Error: Failed to allocate memory for expanded dynamic array.\n";
                throw std::bad_alloc();
            }
            std::copy(data, data + size, new_data);
            delete[] data;
            data = new_data;
        }
        data[size++] = value;
    }

    const T& operator[](size_t index) const {
        if (index >= size) {
            std::cerr << "Error: Index out of bounds.\n";
            throw std::out_of_range("Index out of bounds");
        }
        return data[index];
    }

    T& operator[](size_t index) {
        if (index >= size) {
            std::cerr << "Error: Index out of bounds.\n";
            throw std::out_of_range("Index out of bounds");
        }
        return data[index];
    }

    size_t size() const {
        return size;
    }

    size_t capacity() const {
        return capacity;
    }
};
