class TestAllocator : public std::allocator<char> {
public:
    TestAllocator(size_t block_size, size_t num_blocks) : block_size(block_size), num_blocks(num_blocks) {}

    char* allocate(size_t n) {
        if (n > num_blocks * block_size) {
            std::cerr << "Error: Requested memory size exceeds the allocated limit." << std::endl;
            std::terminate();
        }

        char* result = static_cast<char*>(this->allocate(n * sizeof(char)));
        if (result == nullptr) {
            std::cerr << "Error: Failed to allocate memory." << std::endl;
            std::terminate();
        }

        // Store the address and size of the allocated block
        allocated_blocks.emplace_back(result, n);

        return result;
    }

    void deallocate(char* p, size_t n) {
        if (p == nullptr) {
            std::cerr << "Error: Null pointer passed to deallocate function." << std::endl;
            std::terminate();
        }

        for (auto& block : allocated_blocks) {
