static size_t error_capacity = 0;
static error_t *errors = NULL;

void error_handle_allocation_failure(char *fn_name) {
    fprintf(stderr, "%s: Failed to allocate memory for error messages.\n", fn_name);
    exit(EXIT_FAILURE);
}

void extend_error_array(size_t new_capacity) {
    error_t *new_errors;

    if (new_capacity > error_capacity) {
        new_errors = bpcalloc(new_capacity, sizeof(error_t));
        if (new_errors == NULL) {
            error_handle_allocation_failure(__func__);
        }

        if (errors != NULL) {
            memcpy(new_errors, errors, error_count * sizeof(error_t));
            bfree(errors, error_capacity * sizeof(error_t));
        }

        errors = new_errors;
        error_capacity = new_capacity;
    }
}

void add_error(int error_code, const char *error_message) {
    if (error_count == error_capacity) {
        extend_error_array(error_capacity + 16);
    }

    strncpy(errors[error_count].error_message, error_message, ERROR_MESSAGE_MAX_LENGTH);
    errors[error_count].error_code = error_code;
    error_count++;
}

void error(int error_code, const char *error_message) {
    add_error(error_code, error_message);
}
