            perror("Error executing command");
            exit(EXIT_FAILURE);
        }

        close(pipefd[1]);

        while ((bytes_read = read(pipefd[0], buffer, BUFFER_SIZE)) > 0) {
            len += bytes_read;

            if (len + BUFFER_SIZE > sizeof(char) * BUFFER_SIZE) {
