                if (output == NULL) {
                    perror("Error reallocating memory");
                    exit(EXIT_FAILURE);
                }
            }

            strncat(output, buffer, bytes_read);
        }

        close(pipefd[0]);
        waitpid(pid, NULL, WNOHANG); // Reap the child process
