        }
    }

    int initialize(int sample_rate) {
        this->sample_rate = sample_rate;

        // Validate sample rate
        if (sample_rate <= 0) {
            set_error("Invalid sample rate");
            return -1;
        }

        // Calculate required buffer size
        size_t frame_size = 2 * sizeof(int16_t); // 16-bit stereo
        size_t buffer_size = frame_size * sample_rate / 1000; // frames per second

        // Allocate buffer
        buffer.reset(static_cast<char*>(malloc(buffer_size)));
