#include <math.h>

#define NUM_POINTS 10

typedef struct {
    float x, y, z;
} Point;

float length(Point p1, Point p0) {
    return sqrtf(powf(p1.x - p0.x, 2.0f) + powf(p1.y - p0.y, 2.0f) + powf(p1.z - p0.z, 2.0f));
}

Point* compute_normals(Point* points) {
    Point* normals;
    int i, j;
    Point temp;

    if ((normals = alloca(NUM_POINTS * sizeof(Point))) == NULL) {
        perror("alloca failed");
        return NULL;
    }

    for (i = 0; i < NUM_POINTS; i++) {
        if (i > 0) {
            temp = points[i];
            points[i] = points[i - 1];
            points[i - 1] = temp;
        }

        for (j = 0; j < i; j++) {
            if (i == j) continue;

            temp = points[i];
            points[i] = points[i] - points[j];
            normals[i] = (1.0f / length(points[i], points[j]));
            points[i] = temp;

            points[j] = points[j] - points[i];
            points[i] = points[i] + points[j];
            points[j] = points[j] + normals[i];
        }
    }

    return normals;
}
