```cpp
#include <string>
#include <filesystem>
#include <iostream>
#include <error.h> // For errno and strerror

namespace fs = std::filesystem;

std::string generate_temp_file_name(const std::string& base_name) {
  std::string temp_name = base_name;
  int index = 0;

  while (fs::exists(temp_name + ".tmp")) {
    temp_name = base_name + "_" + std::to_string(index++) + ".tmp";
  }

  fs::path temp_path(temp_name);
  int fd = fs::create_directory_for_file(temp_path, 0600).value();
  if (fd == -1) {
    std::cerr << "Failed to create directory for temporary file: "
              << strerror(errno) << std::endl;
    return "";
  }

  temp_name = temp_path.filename().string();
  int file_fd = open(temp_name.c_str(), O_RDWR | O_CREAT | O_EXCL, 0600);
  if (file_fd == -1) {
    std::cerr << "Failed to create temporary file: "
              << strerror(errno) << std::endl;
    fs::remove(temp_path);
    return "";
  }

  close(file_fd);
  return temp_name;
}
```

