namespace fs = std::filesystem;

wchar_t* read_file(const wchar_t* path) {
    try {
        fs::wpath normalized_path = fs::absolute(path).make_preferred();
        if (!fs::is_regular_file(normalized_path)) {
            throw std::runtime_error("Path is not a valid file.");
        }

        size_t file_size = fs::file_size(normalized_path);
        wchar_t* buffer = new wchar_t[file_size + 1];

        std::ifstream file_stream(normalized_path, std::ios::in);
        if (!file_stream.is_open()) {
            throw std::runtime_error("Failed to open file.");
        }

        file_stream.read(buffer, file_size);
        if (file_stream.gcount() != file_size) {
            throw std::runtime_error("Error reading file.");
        }

        file_stream.close();
        buffer[file_size] = L'\0';

        return buffer;
    } catch (const std::exception& e) {
        wchar_t* error_message = new wchar_t[50];
        wcsncpy(error_message, e.what(), 50);
        wchar_t* error_string = wcsdup(error_message);
