#define MAX_NODES 1000

typedef struct {
    int data;
    bool visited;
    int dist;
} Node;

void bfs(int **adj_matrix, int num_nodes, int start_node, int *shortest_path) {
    Node *queue = m((num_nodes * sizeof(Node));
    int *parent = calloc(num_nodes, sizeof(int));
    bool *visited = calloc(num_nodes, sizeof(bool));
    int *distances = calloc(num_nodes, sizeof(int));

    for (int i = 0; i < num_nodes; i++) {
        distances[i] = INT_MAX;
        visited[i] = false;
    }

    queue[0].data = start_node;
    queue[0].visited = true;
    queue[0].dist = 0;

    int front = 0, rear = 0;

    while (front != rear) {
        int current_node = queue[front].data;

        for (int i = 0; i < num_nodes; i++) {
            if (adj_matrix[current_node][i] && !visited[i]) {
                int new_dist = distances[current_node] + 1;

                if (new_dist < distances[i]) {
                    distances[i] = new_dist;
                    parent[i] = current_node;
                    queue[rear].data = i;
                    queue[rear].visited = true;
                    queue[rear].dist = new_dist;
                    rear++;
                }
            }
        }

        front++;
    }

    int path_length = 0;
    int current_node = start_node;

    if (distances[start_node] == INT_MAX) {
        free(queue);
        free(parent);
        free(visited);
        free(distances);
        shortest_path = NULL;
        return;
    }

    shortest_path = malloc((distances[start_node] + 1) * sizeof(int));
    shortest_path[path_length++] = start_node;

    while (current_node != -1) {
        current_node = parent[current_node];
        shortest_path[path_length++] = current_node;
    }

    for (int i = path_length - 1; i >= 0; i--) {
        printf("%d ", shortest_path[i]);
    }
    printf("\n");

    free(queue);
    free(parent);
    free(visited);
    free(distances);
