    int storage_unit = 0;

    if (log_threshold > 12) {
        estimated_storage = static_cast<int>(threshold / TB);
        storage_unit = 3;
    } else if (log_threshold > 9) {
        estimated_storage = static_cast<int>(threshold / GB);
