using namespace std;
using namespace flann;

struct Point {
    float x, y, z;
    Point(float x, float y, float z) : x(x), y(y), z(z) {}
};

size_t knn_search(const vector<Point>& data, const Point& query, float radius, int k, vector<Index>& results) {
    IndexIndexKdTree<L2<float>> tree(data.begin(), data.size());
    TreeModel model(tree);
    SearchParams params;
    params.tree = &model;
    params.table = &results;
    params.k = k;

    // Perform search
    SearchResult result = model.search(query, radius, params);

    // Return number of neighbors found
    return result.distances.size();
}

int knn_search_3d(const vector<Point>& data, const Point& query, float radius, int k) {
    vector<Index> results;
    size_t num_neighbors = knn_search(data, query, radius, k, results);
    return static_cast<int>(num_neighbors);
}
