#include <iostream>
#include <string>
#include <vector>

struct NodeInfo {
    std::string name;
    int id;
    NodeInfo* prev;
    NodeInfo* next;
};

void checkNodeExists(const std::vector<NodeInfo>& nodes, const std::string& name) {
    for (const auto& node : nodes) {
        if (node.name == name) {
            return;
        }
    }

    throw std::runtime_error("Node not found in the network.");
}

NodeInfo* getNodeInfo(const std::vector<NodeInfo>& nodes, const std::string& name) {
    try {
        checkNodeExists(nodes, name);

        for (const auto& node : nodes) {
            if (node.name == name) {
                return &node;
            }
        }
    } catch (const std::runtime_error&) {
        throw;
    }

    // This should never be reached, but it's good practice to include this check.
    throw std::runtime_error("Internal error: Node not found.");
}
