#define ALPHABET_SIZE 256

typedef struct TrieNode {
    int count;
    struct TrieNode *children[ALPHABET_SIZE];
} TrieNode;

TrieNode* create_node() {
    TrieNode *new_node = (TrieNode *) malloc(sizeof(TrieNode));
    new_node->count = 0;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        new_node->children[i] = NULL;
    }
    return new_node;
}

void insert(TrieNode *root, const char *str, int length) {
    if (length == 0) {
        return;
    }

    int index = (int)str[0];
    if (root->children[index] == NULL) {
        root->children[index] = create_node();
    }
    insert(root->children[index], str + 1, length - 1);
    root->children[index]->count++;
}

int *count_characters(const char *str, int length) {
    TrieNode *root = create_node();
    insert(root, str, length);

    int *result = (int *) malloc(ALPHABET_SIZE * sizeof(int));
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        result[i] = root->children[i] ? root->children[i]->count : 0;
    }

    free(root);
    return result;
}
