#include <vector>
#include <thread>
#include <mutex>
#include <memory>
#include <stdexcept>
#include <cstdint>
#include <cmath>

struct Color {
    float r, g, b;

    Color(float r, float g, float b) : r(r), g(g), b(b) {}
};

class Camera {
public:
    virtual Color GetPixelColor(int x, int y) = 0;
};

class ViewModel {
public:
    virtual float GetWidth() const = 0;
    virtual float GetHeight() const = 0;
};

class ThreadPool {
private:
    std::vector<std::thread> threads;
    std::mutex mtx;
    std::condition_variable cv;
    bool done;

public:
    ThreadPool(size_t numThreads) : done(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            threads.emplace_back([this] {
                while (!done) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(mtx);
                        cv.wait(lock, [this] { return tasks.empty() || done; });
                        if (done) return;
                        task = std::move(tasks.front());
                        tasks.pop_front();
                    }
                    task();
                }
            });
        }
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(mtx);
            done = true;
        }
        cv.notify_all();
        for (auto& thread : threads) {
            thread.join();
        }
    }

    template<typename F, typename... Args>
    void Enqueue(F&& f, Args&&... args) {
        std::function<void()> task = std::bind(std::forward<F>(f), std::forward<Args>(args)...);
        {
            std::unique_lock<std::mutex> lock(mtx);
            tasks.emplace_back(std::move(task));
        }
        cv.notify_one();
    }

private:
    std::queue<std::function<void()>> tasks;
};

void RenderPixel(int width, int height, const Camera& camera, const ViewModel& viewModel, Color* image, int x, int y) {
    Color color = camera.GetPixelColor(x, y);
    image[y * width + x] = color;
}

void RenderImage(int width, int height, const Camera& camera, const ViewModel& viewModel, Color* image) {
    ThreadPool pool(std::thread::hardware_concurrency());

    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            pool.Enqueue([=] { RenderPixel(width, height, camera, viewModel, image, x, y); });
        }
    }

    pool.Join();
}
