#include <stdlib.h>
#include <string.h>
#include <ctype.h>

char* parse_name(const char* str, size_t* name_len) {
    size_t start = 0;
    size_t i = 0;

    // Skip leading whitespace
    for (; isspace((unsigned char)str[i]); i++);

    if (str[i] != ':') {
        if (name_len) *name_len = i;
        return NULL;
    }

    size_t end = i;
    for (i++; isalnum((unsigned char)str[i]) || (i < strlen(str) && isspace((unsigned char)str[i])) || str[i] == ':'; i++);

    if (name_len) *name_len = i - start;
    return strndup(&str[start], i - start);
}

char* parse_value(const char* str, size_t* value_len) {
    size_t start = 0;
    size_t i = 0;

    // Skip name and colon, and leading whitespace
    for (; isspace((unsigned char)str[i]); i++);
    for (; str[i] != ':' && str[i] != '\0'; i++);

    if (str[i] == '\0') {
        if (value_len) *value_len = 0;
        return NULL;
    }

    size_t end = i;
    for (i++; isalnum((unsigned char)str[i]) || (i < strlen(str) && isspace((unsigned char)str[i])); i++);

    if (value_len) *value_len = i - start;
    return strndup(&str[start], i - start);
}

char* parse_namevalue(const char* str) {
    char* name = parse_name(str, NULL);
    if (!name) return NULL;

    size_t name_len = strlen(name);
    char* value = parse_value(&str[name_len], NULL);

    free(name);
    if (!value) return NULL;

    size_t value_len = strlen(value);
    char* result = malloc(name_len + value_len + 2); // +2 for ':' and '\0'
    if (!result) {
        free(value);
        return NULL;
    }

    strcpy(result, name);
    strcat(result, ":");
    strcat(result, value);

    free(value);
    return result;
