using ThreadFunctionType = void(*)(void*); // define thread function type

// Helper function to delete thread handle and detach thread
void DeleteThreadAndDetach(HANDLE hThread) {
    if (hThread != INVALID_HANDLE_VALUE) {
        DWORD exitCode;
        if (!GetExitCodeThread(hThread, &exitCode)) {
            TerminateThread(hThread, EXIT_FAILURE);
        }
        CloseHandle(hThread);
    }
}

// Function to create a new thread using the provided function and argument
// Returns the thread identifier on success, INVALID_HANDLE_VALUE on failure
HANDLE CreateThreadWithErrorHandling(ThreadFunctionType threadFunc, void* arg) {
    HANDLE hThread = CreateThread(NULL, 0, threadFunc, arg, 0, NULL);

    if (hThread == INVALID_HANDLE_VALUE) {
        // Log error or display message here if needed
        // For simplicity, we'll just return the error code
        DWORD errorCode = GetLastError();
        DeleteThreadAndDetach(hThread);
        return errorCode;
    }

    return hThread;
}

// Function to delete thread handle and detach thread on destruction
struct ThreadDeleter {
    void operator()(HANDLE hThread) const {
        DeleteThreadAndDetach(hThread);
    }
};

// Wrap thread handle in a unique_ptr to ensure proper cleanup
using ThreadHandle = std::unique_ptr<HANDLE, ThreadDeleter>;

// Function to create a new thread and return a thread handle
