#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#define WORDS_MAX 10000
#define TOPICS_MAX 50
#define WORD_BITS 32

typedef struct {
    int64_t word;
    float freq;
} word_t;

typedef struct {
    int64_t topic;
    float prob;
} topic_prob_t;

void topic_modeling(const word_t *wp, const float *dp, size_t num_words, size_t num_topics, float **probs, size_t *sumdp, size_t *ztot) {
    size_t i, j, k;
    size_t words_per_topic = num_words / num_topics;
    size_t words_in_topic[TOPICS_MAX] = {0};
    size_t total_words = num_words;
    float sum_per_topic[TOPICS_MAX] = {0};

    *probs = malloc(num_words * sizeof(topic_prob_t));
    if (*probs == NULL) {
        *sumdp = 0;
        *ztot = 0;
        return;
    }

    *sumdp = calloc(num_topics, sizeof(float));
    if (*sumdp == NULL) {
        free(*probs);
        *sumdp = 0;
        *ztot = 0;
        return;
    }

    *ztot = calloc(num_topics, sizeof(size_t));
    if (*ztot == NULL) {
        free(*probs);
        free(*sumdp);
        *sumdp = 0;
        *ztot = 0;
        return;
    }

    for (i = 0; i < num_words; i++) {
        size_t topic_index = wp[i].word % num_topics;
        topic_prob_t *prob_ptr = &((*probs)[i]);
        prob_ptr->topic = topic_index;
        prob_ptr->prob = dp[topic_index] / total_words;
        words_in_topic[topic_index]++;
        sum_per_topic[topic_index] += prob_ptr->prob;
    }

    for (i = 0; i < num_topics; i++) {
        sumdp[i] = sum_per_topic[i];
        ztot[i] = words_in_topic[i];
    }

    for (i = 0; i < num_words; i++) {
        topic_prob_t *prob_ptr = &((*probs)[i]);
        for (j = 0; j < num_topics; j++) {
            for (k = 0; k < words_per_topic; k++) {
                if (wp[i + k].word == (wp[i].word + j)) {
                    prob_ptr->prob += dp[j] / total_words;
                    break;
                }
            }
        }
    }
}
