#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

int parse_file_blocks(const char *filename, long long *num_blocks, long long *blocks_indices) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    long long block_size = 4096; // Assuming each block is 4KB
    long long num_blocks_calculated = file_size / block_size;

    if (num_blocks_calculated * block_size != file_size) {
        fprintf(stderr, "Invalid file size\n");
        fclose(file);
        return -1;
    }

    *num_blocks = num_blocks_calculated;

    long long *indices = malloc(sizeof(long long) * num_blocks);
    if (!indices) {
        perror("Error allocating memory for indices");
        fclose(file);
        return -2;
    }

    for (long long i = 0; i < num_blocks; i++) {
        if (fread(&indices[i], sizeof(long long), 1, file) != 1) {
            perror("Error reading block index");
            free(indices);
            fclose(file);
            return -1;
        }
    }

    *blocks_indices = indices;
    fclose(file);
    return 0;
}
