#include <vector>
#include <cstddef>
#include <iostream>

using namespace std;

void gaussian_filter(const int image_width, const int image_height,
                     const int kernel_width, const int kernel_height,
                     const float kernel[][KERNEL_HEIGHT],
                     uchar image[][image_width], uchar filtered_image[][image_width]) {
    // Validate input parameters
    if (image_width <= 0 || image_height <= 0 || kernel_width <= 0 || kernel_height <= 0) {
        cerr << "Invalid image or kernel dimensions." << endl;
        return;
    }

    // Create temporary buffers for intermediate calculations
    vector<vector<float>> temp_image(image_height, vector<float>(image_width));
    vector<vector<float>> temp_filtered_image(image_height, vector<float>(image_width));

    // Copy input image data to temporary buffer
    for (size_t y = 0; y < image_height; ++y) {
        for (size_t x = 0; x < image_width; ++x) {
            temp_image[y][x] = static_cast<float>(image[y][x]);
        }
    }

    // Apply horizontal filter
    for (size_t y = 0; y < image_height; ++y) {
        for (size_t x = 0; x < image_width; ++x) {
            float sum = 0.0f;
            for (int kernel_x = 0; kernel_x < kernel_width; ++kernel_x) {
                int index = y * image_width + (x - kernel_x + image_width) % image_width;
                sum += temp_image[y][index] * kernel[kernel_x][kernel_height / 2];
            }
            temp_filtered_image[y][x] = sum;
        }
    }

    // Apply vertical filter
    for (size_t x = 0; x < image_width; ++x) {
        for (size_t y = 0; y < image_height; ++y) {
            float sum = 0.0f;
            for (int kernel_y = 0; kernel_y < kernel_height; ++kernel_y) {
                int index = (y - kernel_y + image_height) % image_height * image_width + x;
                sum += temp_filtered_image[index][x] * kernel[kernel_y][kernel_height / 2];
            }
            filtered_image[y][x] = static_cast<uchar>(sum);
        }
    }

    // Copy filtered image data from temporary buffer to output
    for (size_t y = 0; y < image_height; ++y) {
        for (size_t x = 0; x < image_width; ++x) {
            image[y][x] = filtered_image[y][x];
        }
    }
}
