struct DisjointSet {
    int parent, rank;

    DisjointSet() : parent(-1), rank(0) {}
};

class DisjointSetUnion {
private:
    std::vector<DisjointSet> sets;

public:
    DisjointSetUnion(size_t n) : sets(n) {
        for (auto& s : sets) {
            new (&s) DisjointSet();
        }
    }

    int find(int x) {
        if (sets[x].parent < 0) return x;
        return sets[x].parent = find(sets[x].parent);
    }

    void unionSet(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) return;

        if (sets[rootX].rank < sets[rootY].rank) {
            sets[rootX].parent = rootY;
        } else {
            sets[rootY].parent = rootX;
            if (sets[rootX].rank == sets[rootY].rank) {
                sets[rootX].rank++;
            }
        }
    }
};

