#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <errno.h>

#define MAX_PATH_LENGTH 4096

static char env_var[MAX_PATH_LENGTH];
static char software_tree[MAX_PATH_LENGTH];
static char driver_sub_tree[MAX_PATH_LENGTH];
static char filename[MAX_PATH_LENGTH];
static char full_path[MAX_PATH_LENGTH];

bool setup_sound_driver(void) {
    bool success = false;

    // Fetch the software tree location from environment variable or default location
    if (getenv("SOFTWARE_TREE", env_var) != NULL) {
        strcpy(software_tree, env_var);
    } else {
        strcpy(software_tree, "/opt/mysoftware"); // Default location
    }

    // Append the driver sub tree and filename to create the full path
    strcpy(driver_sub_tree, "/drivers/sound");
    strcpy(filename, "my_sound_driver.so");

    // Concatenate the software tree, driver sub tree, and filename
    strcpy(full_path, software_tree);
    strcat(full_path, "/");
    strcat(full_path, driver_sub_tree);
    strcat(full_path, "/");
    strcat(full_path, filename);

    // Validate the filename for unsafe characters and sequences
    if (validate_filename(filename)) {
        // Securely resolve the path before validation
        struct stat st;
        if (stat(full_path, &st) == 0 && S_ISDIR(st.st_mode)) {
            success = true;
        } else {
            perror("Error resolving path");
        }
    }

    return success;
}

bool validate_filename(const char *filename) {
    size_t len = strlen(filename);
    bool valid = true;

    // Validate the filename for unsafe characters and sequences
    for (size_t i = 0; i < len; i++) {
        if (filename[i] == '.' && (i > 0 && filename[i-1] == '.')) {
            valid = false;
            break;
        }
        if (filename[i] == '/') {
            valid = false;
            break;
        }
        if (filename[i] < 0 || filename[i] > 127) {
            valid = false;
            break;
        }
    }

    return valid;
}
