void encrypt_text(const char *key, const char *plaintext, char *ciphertext) {
    int i;
    for (i = 0; i < strlen(plaintext); i++) {
        if (isalpha(plaintext[i])) {
            int index = islower(plaintext[i]) ? (int)(plaintext[i] - 'a') : (int)(plaintext[i] - 'A');
