public static List<int> GenerateRandomList(int minValue, int maxValue, int numberOfElements)
{
    // Generate random integers using a cryptographically secure random number generator
    RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider();
    List<int> randomNumbers = new List<int>();

    for (int i = 0; i < numberOfElements; i++)
    {
        byte[] bytes = new byte[4];
        rng.NextBytes(bytes);
        int randomNumber = BitConverter.ToInt32(bytes, 0) % (maxValue - minValue + 1) + minValue;
        randomNumbers.Add(randomNumber);
    }

