    Random rnd = new Random();
    for (int i = randomNumbers.Count - 1; i > 0; i--)
    {
        int j = rnd.Next() % (i + 1);
        int temp = randomNumbers[i];
        randomNumbers[i] = randomNumbers[j];
        randomNumbers[j] = temp;
    }

    // Sort the list using a custom sorter function
    IComparer<int> customSorter = new CustomSorter();
    randomNumbers.Sort(customSorter);

    // Test whether the sorted list is equal to the original list
