    if (isEqual)
        Console.WriteLine("The sorted list is equal to the original list.");
    else
        Console.WriteLine("The sorted list is not equal to the original list.");

    return randomNumbers;
}

public static bool AreListsEqual<T>(List<T> list1, List<T> list2)
{
    if (list1.Count != list2.Count)
        return false;

    for (int i = 0; i < list1.Count; i++)
    {
        if (!EqualityComparer<T>.Default.Equals(list1[i], list2[i]))
            return false;
    }

    return true;
}

public class CustomSorter : IComparer<int>
{
    public int Compare(int x, int y)
    {
        return x.CompareTo(y);
    }
}
