public double[,] GenerateDisplacementField(int width, int height, double stepSize)
{
    if (width <= 0 || height <= 0 || stepSize <= 0)
    {
        throw new ArgumentException("Invalid image dimensions or step size.");
    }

    double[,] displacementField = new double[height, width];

    using (var rng = new RNGCryptoServiceProvider())
