```csharp using System; using System.Linq; using System.Text; using System.Security.Cryptography;

public class Matrix<T> where T : new()
{
    private int _rows, _columns;
    private T[] _matrix;

    public Matrix(int rows, int columns)
    {
        _rows = rows;
        _columns = columns;
        _matrix = new T[rows * columns];
        InitializeMatrix();
    }

    private void InitializeMatrix()
    {
        var randomNumberGenerator = new RNGCryptoServiceProvider();
        for (int i = 0; i < _matrix.Length; i++)
        {
            _matrix[i] = default(T);
            if (i < _rows * _columns)
            {
                byte[] randomBytes = new byte[sizeof(T)];
                randomNumberGenerator.NextBytes(randomBytes);
                _matrix[i] = BitConverter.IsLittleEndian
                    ? BitConverter.ToStruct<T>(randomBytes)
                    : BitConverter.IsWow64
                        ? ArchitectureHelper.ReverseEndian<T>(BitConverter.ToStruct<T>(randomBytes))
                        : BitConverter.ToStruct<T>(BitConverter.IsLittleEndian
                            ? ArchitectureHelper.ReverseBytes(randomBytes)
                            : randomBytes);
            }
        }
    }

    public T this[int row, int column]
    {
        get { return _matrix[row * _columns + column]; }
    }
}

public static class ArchitectureHelper
{
    public static T ReverseEndian<T>(T value) where T : struct
    {
        byte[] bytes = BitConverter.GetBytes(value);
        Array.Reverse(bytes);
        return BitConverter.ToStruct<T>(bytes);
    }

    public static byte[] ReverseBytes(byte[] bytes)
    {
        byte[] reversedBytes = new byte[bytes.Length];
        for (int i = 0; i < bytes.Length; i++)
        {
            reversedBytes[bytes.Length - i - 1] = bytes[i];
        }
        return reversedBytes;
    }
}
