public static int GetIntSettingFromXml(string xmlFilePath, string settingName) {
    if (string.IsNullOrEmpty(xmlFilePath) || string.IsNullOrEmpty(settingName)) {
        throw new ArgumentException("Both xmlFilePath and settingName must be provided.");
    }

    XDocument xmlDocument;
    try {
        xmlDocument = XDocument.Load(xmlFilePath);
    } catch (FileNotFoundException) {
        throw new FileNotFoundException($"The XML file '{xmlFilePath}' was not found.");
    } catch (XmlException ex) {
        throw new Exception($"An error occurred while parsing the XML file '{xmlFilePath}': {ex.Message}");
