public XmlDocument CreateXmlDocumentWithSafeBaseUri(string elementName, string attributeName, string attributeValue)
{
    XmlDocument document = new XmlDocument();
    document.LoadXml("<root></root>"); // Create an empty XML document

    XmlElement root = document.DocumentElement;
    XmlElement newElement = document.CreateElement(elementName);
    XmlAttribute newAttribute = document.CreateAttribute(attributeName);

    // Set the value of the new attribute
    newAttribute.Value = attributeValue;

    // Add the new attribute to the new element
    newElement.Attributes.Append(newAttribute);

    // Add the new element to the root element
    root.AppendChild(newElement);

    // Check the BaseURI property of the element and attribute
    if (newElement.BaseURI != document.BaseURI && newAttribute.BaseURI != document.BaseURI)
    {
        throw new ArgumentException("BaseURI of element and attribute must match the XML document's BaseURI.");
    }

    return document;
}

// Secure DocumentBuilderFactory configuration
private static void enableOrDisableExternalEntityParsing(DocumentBuilderFactory factory, bool enable)
{
    if (factory is DocumentBuilderFactory documentBuilderFactory)
    {
        documentBuilderFactory.SetFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        documentBuilderFactory.SetFeature("http://xml.org/sax/features/external-general-entities", false);
        documentBuilderFactory.SetFeature("http://xml.org/sax/features/external-parameter-entities", false);

        if (enable)
        {
            documentBuilderFactory.SetFeature("http://apache.org/xml/features/external-entity-loading", true);
        }
        else
        {
            documentBuilderFactory.SetFeature("http://apache.org/xml/features/external-entity-loading", false);
        }
    }
}
