```csharp using System;

public struct IntersectionType
{
    public bool IsThreeWay;
    public bool IsTurn;
}

public class TransformRotator
{
    public void RotateTransform(Transform transform, IntersectionType intersectionType)
    {
        if (transform == null)
            throw new ArgumentNullException(nameof(transform));

        if (intersectionType.IsThreeWay)
        {
            if (new Random().Next(2) == 0)
                transform.Rotate(Vector3.right, 90f);
            else
                transform.Rotate(Vector3.right, -90f);
        }
        else if (intersectionType.IsTurn)
        {
            transform.Rotate(Vector3.forward, -90f);
        }
        else
        {
            if (intersectionType.IsThreeWay)
                throw new ArgumentException("Three-way intersection type is not valid for a turn.", nameof(intersectionType));

            transform.Rotate(Vector3.right, intersectionType.IsLeft ? -90f : 90f);
        }
    }
}
