public static void InsertCassandraData(Session session, string keyspace, string table, IDictionary<string, byte[]> outgoingPayload, Action<byte[]> assertFunction)
{
    using (Cluster cluster = new Cluster())
    {
        cluster.AddContactPoint(new Uri("127.0.0.1")); // Replace with your contact point
        session = cluster.Connect(keyspace);

        if (session == null)
        {
            throw new Exception("Failed to connect to Cassandra session.");
        }

        if (outgoingPayload == null)
        {
            throw new ArgumentNullException(nameof(outgoingPayload));
        }

        if (outgoingPayload.Count != 1)
        {
            throw new ArgumentException("Outgoing payload must contain exactly one item.");
        }

        using (BatchStatement batch = new BatchStatement())
        {
            foreach (KeyValuePair<string, byte[]> entry in outgoingPayload)
            {
                byte[] key = entry.Key.ToUtf8Bytes();
                byte[] value = entry.Value;

                IStatement statement = new InsertStatement(keyspace, table, key)
                    .Value(new ByteArrayValue(value));

                batch.Add(statement);
            }

            IResult result = session.Execute(batch);

            if (result.IsError)
            {
                throw new Exception($"Error executing Cassandra statement: {result.Message}");
            }

            using (ResultSet resultSet = result.GetResultSet())
            {
                if (resultSet.IsEmpty)
                {
                    throw new Exception("No data returned from Cassandra.");
                }

                byte[] incomingPayload = resultSet.First().GetBytes();

                if (incomingPayload == null)
                {
                    throw new Exception("Incoming payload is null.");
                }

                if (incomingPayload.Length != outgoingPayload[0].Length)
                {
                    throw new Exception("Incoming and outgoing payloads have different lengths.");
                }

                bool contentsMatch = true;
                for (int i = 0; i < incomingPayload.Length; i++)
                {
