using System.Diagnostics;
using System.IO;
using System.Threading;

public static void StartProcessWithMonitor(ProcessStartInfo processInfo, string trackingFolder, int timeout)
{
    if (!Directory.Exists(trackingFolder))
    {
        throw new InvalidOperationException("Tracking folder does not exist.");
    }

    Process startedProcess = Process.Start(processInfo);

    string trackingFilePath = Path.Combine(trackingFolder, $"{startedProcess.Id}.pid");

    using (File.CreateText(trackingFilePath).Dispose()) { }

    Process sentinelProcess = new Process
    {
