            UseShellExecute = false,
            RedirectStandardOutput = false,
            RedirectStandardError = false
        }
    };

    sentinelProcess.Start();

    CancellationTokenSource cts = new CancellationTokenSource();

    Thread monitorThread = new Thread(() =>
    {
        if (!startedProcess.HasExited)
        {
            if (!cts.IsCancellationRequested)
            {
                cts.Cancel();
            }

            if (sentinelProcess.HasExited)
            {
                File.Delete(trackingFilePath);
                throw new TimeoutException("Process did not complete within the specified timeout.");
            }
        }
    });

    monitorThread.Start();

    startedProcess.WaitForExit(timeout);

    if (startedProcess.HasExited)
    {
        sentinelProcess.WaitForExit();
        File.Delete(trackingFilePath);
    }
    else
    {
        cts.Cancel();
        monitorThread.Join();
    }
}
