```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class TownDAO {
    private Connection connection;

    public Town addTown(String townName) throws SQLException {
        connection = DriverManager.getConnection("jdbc:your_database:your_database_url", "username", "password");
        connection.setAutoCommit(false); // begin transaction

        PreparedStatement insertStatement = connection.prepareStatement(
                "INSERT INTO Towns(name) VALUES(?)");
        insertStatement.setString(1, townName);
        int rowsAffected = insertStatement.executeUpdate();

        if (rowsAffected > 0) {
            PreparedStatement getLastIdStatement = connection.prepareStatement(
                    "SELECT id FROM Towns ORDER BY id DESC LIMIT 1");
            ResultSet resultSet = getLastIdStatement.executeQuery();
            if (resultSet.next()) {
                int lastId = resultSet.getInt("id");
                connection.commit(); // commit transaction
                Town town = new Town(lastId, townName);
                return town;
            }
        }

        connection.rollback(); // rollback transaction
        throw new SQLException("Failed to insert town.");
    }
}

class Town {
    int id;
    String name;

    public Town(int id, String name) {
        this.id = id;
        this.name = name;
    }
}
