using System.Xml.XPath;
using System.IO;

public static void AddSearcherToConfig(string configPath, string searcherName, string searcherType) {
    if (!File.Exists(configPath)) {
        throw new FileNotFoundException("Configuration file does not exist.");
    }

    XDocument configDoc = XDocument.Load(configPath);

    XElement searchersElement = configDoc.Root.Element("searchers") ?? configDoc.Root.Add(new XElement("searchers", new object[] { }));

    bool searcherExists = searchersElement.Elements("searcher").Any(e => (string)e.Attribute("name") == searcherName);

    if (searcherExists) {
