using System.Net;
using System.Security.Claims;
using System.Threading.Tasks;

public class AccountService
{
    private const string RedirectUrlKey = "ReturnUrl";

    public async Task<Uri> RegisterUserAsync(string email, string password, string fullName, Uri returnUrl = null)
    {
        try
        {
            // Validate input parameters
            if (string.IsNullOrWhiteSpace(email)) throw new ArgumentException("Email is required.");
            if (string.IsNullOrWhiteSpace(password)) throw new ArgumentException("Password is required.");
            if (string.IsNullOrWhiteSpace(fullName)) fullName = string.Empty;

            // Check if user already exists
            using (var client = new WebClient())
            {
                var apiUrl = "https://accountservice.com/api/users/email/" + email;
                var existingUserJson = await client.DownloadStringTaskAsync(apiUrl);
                if (!string.IsNullOrEmpty(existingUserJson)) throw new ArgumentException("Email is already in use.");
            }

            // Register user with account service
            using (var client = new WebClient())
            {
                var apiUrl = "https://accountservice.com/api/users";
                var userData = new
                {
                    Email = email,
                    Password = password,
                    FullName = fullName
                };
                var userDataJson = JsonConvert.SerializeObject(userData);
                client.Headers.Add("Content-Type", "application/json");
                var registrationResponse = await client.UploadStringTaskAsync(apiUrl, userDataJson);
                var registrationResponseJson = JsonConvert.DeserializeObject<RegistrationResponse>(registrationResponse);

                if (registrationResponseJson == null) throw new Exception("Failed to register user.");
                if (!registrationResponseJson.Success) throw new Exception("Registration failed with errors: " + registrationResponseJson.Message);

                // Save user claims
                var claims = new ClaimsPrincipal();
                claims.Claims.Add(new Claim(ClaimTypes.Email, email));
                claims.Claims.Add(new Claim(ClaimTypes.Name, fullName));
                var identity = new ClaimsIdentity(claims.Claims, "AccountService");
                Thread.CurrentPrincipal = identity;

                // Redirect to home page or return URL
                if (returnUrl != null) return returnUrl;
                return new Uri("https://myapp.com/home");
            }
        }
        catch (Exception ex)
        {
            // Log error and return error page
            return new Uri("https://myapp.com/error?message=" + WebUtility.UrlEncode(ex.Message));
        }
    }

    private class RegistrationResponse
    {
        public bool Success { get; set; }
        public string Message { get; set; }
    }
}
