    List<Tank> tanks = grid.Cast<Tank>()
        .Where(tank => tank != null && tank.x >= 0 && tank.x < grid.GetLength(0) && tank.y >= 0 && tank.y < grid.GetLength(1) && !tank.hasOutput)
