```csharp using System; using System.Threading;

public class Observation
{
    public int SequenceNumber { get; set; }
    public int ProducerThreadId { get; set; }
    public TimeSpan Latency { get; set; }
}

public class DemuxProducer<T, U> where T : new() where U : new()
{
    private int _sequenceNumber;
    private readonly ConcurrentQueue<U> _queue = new ConcurrentQueue<U>();
    private readonly object _lock = new object();

    public U Produce(int delayMilliseconds)
    {
        U result = new U();

        // Increment shared sequence number using Interlocked.Increment
        _sequenceNumber = Interlocked.Increment(ref _sequenceNumber);

        // Introduce random delay using Thread.Sleep
        Thread.Sleep(new Random().Next(delayMilliseconds) + delayMilliseconds);

        lock (_lock)
        {
            _queue.Enqueue(result);
        }

        return result;
    }

    public Observation Consume()
    {
        U result;

        if (_queue.TryDequeue(out result))
        {
            return new Observation
            {
                SequenceNumber = _sequenceNumber,
                ProducerThreadId = Thread.CurrentThread.ManagedThreadId,
                Latency = DateTime.Now - new DateTime(1970, 1, 1)
            };
        }
        else
        {
            throw new InvalidOperationException("Queue is empty.");
        }
    }
}

public class ProducerConsumerExample
{
    static void Main(string[] args)
    {
        DemuxProducer<int, Observation> producerConsumer = new DemuxProducer<int, Observation>();

        Thread producerThread = new Thread(() =>
        {
            for (int i = 0; i < 10; i++)
            {
                Observation observation = producerConsumer.Produce(new Random().Next(500));
                Console.WriteLine($"Produced item {observation.SequenceNumber} with latency {observation.Latency}");
            }
        });

        producerThread.Start();

        for (int i = 0; i < 10; i++)
        {
            Observation observation = producerConsumer.Consume();
            Console.WriteLine($"Consumed item {observation.SequenceNumber} with producer thread ID {observation.ProducerThreadId}");
        }

        producerThread.Join();
    }
}
```

