public class ViewDefinition
{
    public string Name { get; set; }
    public Type ViewType { get; set; }
    public List<string> Fields { get; set; }
}

public class ListViewGenerator
{
    private readonly List<Type> _supportedTypes;
    private readonly XDocument _xmlDocument;

    public ListViewGenerator(List<Type> supportedTypes, XDocument xmlDocument)
    {
        _supportedTypes = supportedTypes;
        _xmlDocument = xmlDocument;
    }

    public void GenerateViews()
    {
        if (_xmlDocument == null)
        {
            throw new ArgumentNullException(nameof(_xmlDocument));
        }

        var views = new List<ViewDefinition>();

        // Validate XML document
        if (!IsValidXmlDocument(_xmlDocument))
        {
            throw new ArgumentException("Invalid XML document.");
        }

        // Iterate through views in XML document that match the base type of the list
        var root = _xmlDocument.Root;
        var viewElements = root.Descendants("view");

        foreach (var viewElement in viewElements)
        {
            var listType = Type.GetType(viewElement.Attribute("type").Value);
            if (!_supportedTypes.Contains(listType))
            {
                continue;
            }

            var view = new ViewDefinition
            {
                Name = viewElement.Attribute("name").Value,
                ViewType = listType,
                Fields = new List<string>(viewElement.Descendants("field")
                    .Select(f => f.Value))
            };
            views.Add(view);
        }

        // Set default view and row limit for the list
        if (views.Count > 0)
        {
            var defaultViewElement = root.Descendants("defaultView").FirstOrDefault();
            if (defaultViewElement != null)
            {
                var defaultViewName = defaultViewElement.Value;
                var defaultView = views.FirstOrDefault(v => v.Name == defaultViewName);
                if (defaultView != null)
                {
                    SetDefaultView(views, defaultView);
                }
            }

            var rowLimitElement = root.Descendants("rowLimit").FirstOrDefault();
            if (rowLimitElement != null)
            {
                var rowLimit = int.Parse(rowLimitElement.Value);
                SetRowLimit(views, rowLimit);
            }
        }
    }

    private bool IsValidXmlDocument(XDocument document)
    {
        if (document == null)
        {
            return false;
        }

        try
        {
            document.Load(XmlReader.Null);
            return true;
        }
        catch (XmlException)
        {
            return false;
        }
    }

    private void SetDefaultView(List<ViewDefinition> views, ViewDefinition view)
    {
        if (views.Any(v => v.IsDefaultView))
        {
            throw new InvalidOperationException("A default view already exists.");
        }

        view.IsDefaultView = true;
    }

    private void SetRowLimit(List<ViewDefinition> views, int rowLimit)
    {
        if (rowLimit <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(rowLimit), "Row limit must be greater than zero.");
        }

        foreach (var view in views)
        {
            view.RowLimit = rowLimit;
        }
    }
}
