public static string GetFirstElementTrimmedValue(XPathNavigator navigator, string tagName)
{
    XPathExpression expression = XPathExpression.Compile(string.Format("//{0}", tagName));
    XPathNodeIterator iterator = navigator.Select(expression);

    if (iterator == null || iterator.Count == 0)
        return null;

    XPathNavigator currentNode = iterator.Current;
    string value = currentNode.Value.Trim();
    expression.Dispose();
    iterator.Dispose();

    return value;
}
