```csharp
using System;
using System.IO;
using PHP.Core;

public static void OpenIniFile(string filePath)
{
    if (!File.Exists(filePath))
    {
        Console.WriteLine($"Error: The specified file '{filePath}' does not exist.");
        return;
    }

    try
    {
        using (Stream stream = File.OpenRead(filePath))
        {
            using (MemoryStream memoryStream = new MemoryStream())
            {
                stream.CopyTo(memoryStream);
                memoryStream.Seek(0, SeekOrigin.Begin);

                int errorCode = PHP.Runtime.ini_scanner_init();
                if (errorCode < 0)
                {
                    Console.WriteLine($"Error: Failed to initialize ini scanner: {PHP.Runtime.ini_last_error()}");
                    return;
                }

                errorCode = PHP.Runtime.ini_scan_file(memoryStream, filePath);
                if (errorCode < 0)
                {
                    Console.WriteLine($"Error: Failed to parse ini file '{filePath}': {PHP.Runtime.ini_last_error()}");
                    PHP.Runtime.ini_scanner_destroy();
                    return;
                }

                PHP.Runtime.ini_scanner_destroy();
            }
        }

        Console.WriteLine($"Successfully opened and parsed ini file '{filePath}'.");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: Failed to open or parse ini file '{filePath}': {ex.Message}");
    }
}
