using System;
using System.Diagnostics;
using System.Text.RegularExpressions;

public class ApplicationSettings
{
    public static void SetSetting(string settingName, string value)
    {
        if (string.IsNullOrEmpty(settingName))
            throw new ArgumentException("Setting name cannot be null or empty.");

        if (string.IsNullOrEmpty(value))
            throw new ArgumentException("Value cannot be null or empty.");

        // Validate setting value to ensure it is a non-negative integer and within a specified range
        if (int.TryParse(value, out int intValue))
        {
            if (intValue < 0 || intValue > 100)
                throw new ArgumentOutOfRangeException("Value must be a non-negative integer between 0 and 100.");
        }
        else
        {
            throw new ArgumentException("Value must be a valid integer.");
        }

        // Set the application setting (example implementation)
        // ConfigurationManager.AppSettings[settingName] = value;
    }

    public static void OpenHyperlink(string url)
    {
        if (string.IsNullOrEmpty(url))
            throw new ArgumentException("URL cannot be null or empty.");

        // Validate URL scheme to ensure it is safe
        var uri = new Uri(url);
        if (uri.Scheme != Uri.UriSchemeHttp && uri.Scheme != Uri.UriSchemeHttps)
            throw new ArgumentException("Only HTTP and HTTPS URLs are allowed.");

        // Open the URL using Process.Start
        try
        {
            Process.Start(new ProcessStartInfo(url) { UseShellExecute = true });
        }
        catch (Exception ex)
        {
            // Escape exception message to prevent XSS
            string escapedMessage = Regex.Escape(ex.Message);
            throw new Exception($"Failed to open URL: {escapedMessage}");
        }
    }
}
