        .AddContactPoint("127.0.0.1")
        .WithPort(9042)
        .Build();

    return config;
}

public static void SetupTestKeyspaceAndTable(Cluster cluster)
{
    using (var session = cluster.Connect())
    {
        session.Execute("CREATE KEYSPACE IF NOT EXISTS test WITH replication = {'class': 'SimpleStrategy', 'replication_factor': 1}");
        session.ChangeKeyspace("test");
        session.Execute("CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY, name TEXT, age INT)");
    }
}

public static void ExecuteQueryWithCustomPayload(Cluster cluster, string query, byte[] payload)
{
    using (var session = cluster.Connect())
    using (var command = new PreparedStatement("INSERT INTO users (name, age) VALUES (?, ?)"))
    {
        command.Bind(query, payload);
        session.Execute(command);

        using (var resultSet = session.Execute(new SimpleStatement("SELECT * FROM users WHERE name = ?", query)))
        {
            using (var row = resultSet.FirstOrDefault())
            {
                if (row != null)
                {
                    Console.WriteLine($"Query executed successfully with result: id={row.Id}, name={row.Name}, age={row.Age}");
                }
                else
                {
                    Console.WriteLine("Query failed or no result was returned");
                }
            }
        }
    }
}

