    public async Task CreateAndPostThreadAndRedirect(string forumName, string threadTitle, string postContent)
    {
        // Create a new thread
        var thread = await _threadManager.CreateThreadAsync(forumName, threadTitle);

        // Post a message in the new thread
        await _forumClient.PostMessageAsync(thread.Id, postContent);

        // Publish both the thread and the post
        await _threadManager.PublishThreadAsync(thread.Id);
        await _forumClient.PublishMessageAsync(thread.Id, 0);

        // Redirect to the thread view with a success message
        string successMessage = $"Thread '{threadTitle}' created successfully.";
        string redirectUrl = _configuration["Forum:ThreadViewUrlTemplate"] + thread.Id;

        Response.Redirect(new Uri(redirectUrl + "?message=" + HttpUtility.UrlEncode(successMessage)));
    }
}
