public static int ExecuteCommandWithCallback(string command, Action<string> outputCallback, Action<string> errorCallback) {
    ProcessStartInfo startInfo = new ProcessStartInfo {
        FileName = "cmd.exe",
        Arguments = $"/c {command}",
