```csharp
using System;
using System.IO;
using System.Xml.Linq;
using System.Xml.XPath;

public static void UpdateXmlConfig(string filePath, string existingSectionName, XElement newSection)
{
    if (string.IsNullOrEmpty(filePath))
        throw new ArgumentException("File path cannot be null or empty.", nameof(filePath));

    if (!File.Exists(filePath))
        throw new FileNotFoundException("The specified file does not exist.", filePath);

    if (string.IsNullOrEmpty(existingSectionName))
        throw new ArgumentException("Existing section name cannot be null or empty.", nameof(existingSectionName));

    if (newSection == null)
        throw new ArgumentNullException(nameof(newSection), "New section cannot be null.");

    try
    {
        XDocument doc = XDocument.Load(filePath);

        var existingSection = doc.XPathSelectElement($"//{existingSectionName}");
        if (existingSection == null)
            throw new InvalidOperationException($"The section '{existingSectionName}' does not exist in the XML document.");

        existingSection.AddAfterSelf(newSection);

        using (var stream = new FileStream(filePath, FileMode.Create, FileAccess.Write, FileShare.None))
        {
            doc.Save(stream);
        }
    }
    catch (Exception ex)
    {
        throw new InvalidOperationException("An error occurred while updating the XML configuration file.", ex);
    }
}
