public ActionResult DeleteBlogPost(int postId, string redirectUrl)
{
    try
    {
        // Validate redirect URL to prevent malicious redirects
        if (!IsValidRedirectUrl(redirectUrl))
        {
            redirectUrl = "/Admin/Blogs"; // Default safe redirect
        }

        // Check authorization
        if (!User.IsInRole("Admin"))
        {
            return new HttpStatusCodeResult(HttpStatusCode.Forbidden, "Access denied.");
        }

        // Use service layer to delete the blog post
        var blogService = new BlogService();
        var result = blogService.DeleteBlogPost(postId);

        if (!result.Success)
        {
            // Log the error and return a generic error message
            Logger.LogError($"Failed to delete blog post {postId}: {result.ErrorMessage}");
            return new HttpStatusCodeResult(HttpStatusCode.InternalServerError, "An error occurred while deleting the blog post.");
        }

        // Notify relevant users about the deletion
        var notifier = new BlogNotifier();
        notifier.NotifyBlogPostDeleted(postId);

        // Redirect to the list of blogs for administrators
        return Redirect(redirectUrl);
    }
    catch (Exception ex)
    {
        // Log the exception and return a generic error message
        Logger.LogError($"Unexpected error deleting blog post {postId}: {ex.Message}");
        return new HttpStatusCodeResult(HttpStatusCode.InternalServerError, "An unexpected error occurred.");
    }
}

private bool IsValidRedirectUrl(string url)
{
    // Validate the redirect URL to ensure it's a safe, relative URL
    return !string.IsNullOrEmpty(url) && Uri.IsWellFormedUriString(url, UriKind.Relative);
}
