public static void UpdateXmlFile(string filePath, string xPathToElementToInsertAfter, XElement newElement) {
  if (string.IsNullOrEmpty(filePath) || string.IsNullOrEmpty(xPathToElementToInsertAfter) || newElement == null) {
    throw new ArgumentNullException();
  }

  XDocument document = XDocument.Load(filePath);
  XElement elementToInsertAfter = document.XPathSelectElement(xPathToElementToInsertAfter);

  if (elementToInsertAfter == null) {
    throw new ElementNotFoundException("Element not found.");
  }

  XElement newElementCopy = newElement.DeepClone() as XElement;
  XElement nextElement = elementToInsertAfter.NextNode as XElement;

  if (nextElement != null) {
    newElementCopy.AddNextSelf(nextElement);
  }

  elementToInsertAfter.AddNextSelf(newElementCopy);

  document.Save(filePath);
}

public class ElementNotFoundException : Exception {
  public ElementNotFoundException(string message) : base(message) { }
}
