using System;
using System.Collections.Generic;
using System.IO;
using System.Xml;

public class ConfigurationLoader
{
    public static Dictionary<string, string> LoadConfiguration(string configPath)
    {
        var configSettings = new Dictionary<string, string>();

        try
        {
            // Validate and sanitize the input path
            if (string.IsNullOrWhiteSpace(configPath) || !File.Exists(configPath))
            {
                throw new FileNotFoundException("Configuration file not found or path is invalid.");
            }

            // Create a secure XmlReaderSettings to prevent XXE attacks
            var settings = new XmlReaderSettings
            {
                DtdProcessing = DtdProcessing.Prohibit,
                XmlResolver = null
            };

            using (var reader = XmlReader.Create(configPath, settings))
            {
                var doc = new XmlDocument();
                doc.Load(reader);

                // Ensure the root element exists
                var root = doc.DocumentElement;
                if (root == null)
                {
                    throw new XmlException("The configuration file does not contain a root element.");
                }

                // Parse the configuration settings
                foreach (XmlNode node in root.ChildNodes)
                {
                    if (node.NodeType == XmlNodeType.Element)
                    {
                        string key = node.Name;
                        string value = node.InnerText;
                        configSettings[key] = value;
                    }
                }
            }
        }
        catch (FileNotFoundException ex)
        {
            Console.WriteLine($"File not found: {ex.Message}");
        }
        catch (XmlException ex)
        {
            Console.WriteLine($"XML parsing error: {ex.Message}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }

        return configSettings;
    }
}
