public static int ExecuteProcessWithCallback(string path, string[] arguments, Action<string> outputCallback, Action<string> errorCallback) {
    ProcessStartInfo startInfo = new ProcessStartInfo {
        FileName = path,
        Arguments = string.Join(" ", arguments),
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        UseShellExecute = false,
        CreateNoWindow = true,
    };

    using (Process process = new Process()) {
        process.StartInfo = startInfo;
        process.OutputDataReceived += (sender, args) => outputCallback(args.Data);
        process.ErrorDataReceived += (sender, args) => errorCallback(args.Data);

        process.Start();
        process.BeginOutputReadLine();
        process.BeginErrorReadLine();

        process.WaitForExit();
        return process.ExitCode;
    }
}
