using System.Security.Cryptography;

public IActionResult RegisterUser(RegisterModel model)
{
    if (ModelState.IsValid)
    {
        if (model.Password != model.ConfirmPassword)
        {
            ModelState.AddModelError("Passwords", "Passwords do not match.");
            return View("Register");
        }

        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] hashedPassword = sha256.ComputeHash(Encoding.UTF8.GetBytes(model.Password));
            string hashedPasswordString = BitConverter.ToString(hashedPassword).Replace("-", "").ToLower();

            User user = new User
            {
                Username = model.Username,
                Email = model.Email,
                PasswordHash = hashedPasswordString
            };

            if (_context.Users.Any(u => u.Username == user.Username))
            {
                ModelState.AddModelError("Username", "Username already exists.");
                return View("Register");
            }

            if (_context.Users.Any(u => u.Email == user.Email))
            {
                ModelState.AddModelError("Email", "Email already exists.");
                return View("Register");
            }

            _context.Users.Add(user);
            _context.SaveChanges();

            return RedirectToAction("Index", "Home");
        }
    }

    return View("Register");
