```csharp using System; using System.Data.SqlClient;

public async Task<int> GetNextVersionAsync(int streamId, int currentVersion, string connectionString)
{
    int nextVersion = currentVersion;

    using (SqlConnection connection = new SqlConnection(connectionString))
    {
        await connection.OpenAsync();

        using (SqlCommand command = new SqlCommand("GetNextVersion", connection))
        {
            command.CommandType = CommandType.StoredProcedure;
            command.Parameters.AddWithValue("@StreamId", streamId);
            command.Parameters.AddWithValue("@CurrentVersion", currentVersion);
            command.Parameters.Add("@NextVersion", SqlDbType.Int).Direction = ParameterDirection.Output;

            await command.ExecuteNonQueryAsync();

            nextVersion = (int)command.Parameters["@NextVersion"].Value;
        }
    }

    return nextVersion;
}

// Stored Procedure for GetNextVersion
CREATE PROCEDURE GetNextVersion
    @StreamId INT,
    @CurrentVersion INT,
    @NextVersion INT OUTPUT
AS
BEGIN
    SELECT TOP 1 Version
    INTO @NextVersion
    FROM StreamVersions
    WHERE StreamId = @StreamId AND Version > @CurrentVersion
    ORDER BY Version ASC

    IF @@ROWCOUNT = 0
    BEGIN
        SET @NextVersion = -1
    END
END
