public static bool EstablishRemoteConnection(string ipAddress, string userName, string password)
{
    if (string.IsNullOrEmpty(ipAddress) || string.IsNullOrEmpty(userName) || string.IsNullOrEmpty(password))
    {
        throw new ArgumentNullException();
    }

