public static int ValidateXPathAndInsertElement(string xmlFilePath, string xPathQuery) {
    int nodesBefore = 0;

    using (XmlDocument xmlDocument = new XmlDocument()) {
        xmlDocument.Load(xmlFilePath);
        nodesBefore = XPathSelectElements(xmlDocument, xPathQuery).Count;
    }

    using (XmlDocument updatedXmlDocument = new XmlDocument()) {
        updatedXmlDocument.Load(xmlFilePath);

        XmlNode newElement = updatedXmlDocument.CreateElement("newElement");
        XmlNode parentNode = XPathSelectElement(updatedXmlDocument, xPathQuery);

        if (parentNode != null) {
            parentNode.AppendChild(newElement);
        }

        xmlDocument = new XmlDocument(updatedXmlDocument.DocumentElement);
        int nodesAfter = XPathSelectElements(xmlDocument, xPathQuery).Count;

        if (nodesBefore != nodesAfter) {
            throw new Exception("Number of nodes before and after insertion is not the same.");
        }

        xmlDocument.Save(xmlFilePath);
    }

    using (XmlDocument finalXmlDocument = new XmlDocument()) {
        finalXmlDocument.Load(xmlFilePath);
        int finalNodes = XPathSelectElements(finalXmlDocument, xPathQuery).Count;

        if (nodesBefore != finalNodes) {
            throw new Exception("Number of nodes before and after insertion and file save is not the same.");
        }

        return nodesBefore;
    }
}

private static XmlNode XPathSelectElement(XmlDocument xmlDocument, string xPathQuery) {
    XPathNavigator navigator = xmlDocument.CreateNavigator();
    XPathNodeIterator iterator = navigator.Select(xPathQuery);

    if (iterator.MoveNext()) {
        return iterator.Current;
    }

    return null;
}

private static IEnumerable<XmlNode> XPathSelectElements(XmlDocument xmlDocument, string xPathQuery) {
    XPathNavigator navigator = xmlDocument.CreateNavigator();
    XPathNodeIterator iterator = navigator.Select(xPathQuery);

    List<XmlNode> nodes = new List<XmlNode>();

    while (iterator.MoveNext()) {
        nodes.Add(iterator.Current);
    }

    return nodes;
}
