public class RichTextBoxHyperlinkController : RichTextBox
{
    private bool _isCtrlPressed;

    public RichTextBoxHyperlinkController()
    {
        this.AllowDrop = false;
        this.TextChanged += TextChangedHandler;
        this.KeyDown += KeyDownHandler;
    }

    private void TextChangedHandler(object sender, EventArgs e)
    {
        this.FindAndFormatHyperlinks();
    }

    private void KeyDownHandler(object sender, KeyEventArgs e)
    {
        if (e.KeyCode == Keys.ControlKey && (e.Modifiers & Keys.KeyCode.Left || e.Modifiers & Keys.KeyCode.Right))
        {
            _isCtrlPressed = true;
        }
        else
        {
            _isCtrlPressed = false;
        }
    }

    private void FindAndFormatHyperlinks()
    {
        if (!_isCtrlPressed)
        {
            this.SelectionColor = Color.Black;
            this.SelectionBackColor = Color.White;
            this.FindText("(?i)\\b(https?://\\S+)", new MatchEventHandler(FormatHyperlink));
        }
    }

    private void FormatHyperlink(object sender, TextMatchEventArgs e)
    {
        if (e.Success)
        {
            this.SelectionColor = Color.Blue;
            this.SelectionBackColor = Color.FromArgb(192, 255, 255);
            this.SelectionFont = new Font(this.Font, FontStyle.Underline);
            this.SelectionStart = e.Index;
            this.SelectionLength = e.Length;
            this.ScrollToCaret();
            this.PerformEvent(new TextChangedEventArgs("TextChanged"));
        }
    }

    protected override void WndProc(ref Message m)
    {
        if (m.Msg == 0x0112 && _isCtrlPressed)
        {
            string url = this.Text.Substring(this.SelectionStart, this.SelectionLength).TrimStart('http://').TrimStart('https://');
            Process.Start(new ProcessStartInfo(url) { UseShellExecute = true });
            base.WndProc(ref m);
            this.ClearSelection();
        }
        else
        {
            base.WndProc(ref m);
        }
    }
}

