{
    private RichTextBoxHyperlinkController _richTextBoxHyperlinkController;

    public RichTextBoxDesignerHost()
    {
        _richTextBoxHyperlinkController = new RichTextBoxHyperlinkController();
        _richTextBoxHyperlinkController.Dock = DockStyle.Fill;
        this.ContainerContent = _richTextBoxHyperlinkController;
    }
}
