public class MobileDeviceTask : IMobileDeviceTask
{
    private NSObject _nsObject;
    private NSRunLoop _nsRunLoop;

    public MobileDeviceTask()
    {
        _nsObject = new NSObject("MobileDeviceTask");
        _nsRunLoop = NSRunLoop.Main;
    }

    public void BeginInvokeOnMainThread(Action action)
    {
        if (NSApplication.SharedApplication.MainWindow != null)
        {
