```csharp using System;
using System.Diagnostics;
using System.IO;
using System.Security.AccessControl;

public static void RunProcessAsRealUser(string userName, string password, string filePath, out int exitCode, out string errorMessage)
{
    exitCode = 0;
    errorMessage = string.Empty;

    try
    {
        using (new ImpersonationScope(WindowsIdentity.GetCurrent().Impersonate()))
        {
            using (WindowsIdentity newIdentity = new WindowsIdentity(userName, password))
            using (WindowsPrincipal principal = new WindowsPrincipal(newIdentity))
            {
                if (!principal.IsInRole(WindowsBuiltInRole.SeSecurityPrivilege))
                {
                    throw new SecurityException("The user does not have the required privileges.");
                }

                ProcessStartInfo processInfo = new ProcessStartInfo
                {
                    FileName = "cmd.exe",
                    Arguments = $"/c start /user:{userName} \"{filePath}\"",
                    UseShellExecute = false,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    CreateNoWindow = true
                };

                using (Process process = Process.Start(processInfo))
                {
                    using (StreamReader outputReader = process.StandardOutput)
                    using (StreamReader errorReader = process.StandardError)
                    {
                        string output = outputReader.ReadToEnd();
                        string error = errorReader.ReadToEnd();

                        if (process.ExitCode != 0)
                        {
                            errorMessage = $"Error starting process: {error}";
                            exitCode = process.ExitCode;
                            throw new Exception($"Error: {errorMessage}");
                        }

                        // Log any exceptions that occur during process startup
                        try
                        {
                            File.WriteAllText("process_output.txt", output);
                        }
                        catch (Exception ex)
                        {
                            errorMessage = $"Error writing process output to file: {ex.Message}";
                            exitCode = process.ExitCode;
                            throw;
                        }
                    }

                    process.WaitForExit();
                }
            }
        }
    }
    catch (Exception ex)
    {
        errorMessage = $"Error: {ex.Message}";
        exitCode = -1;
    }
}
