public static XmlDocument ValidateXmlDocument(XmlDocument xmlDocument, XmlSchema schema)
{
    if (xmlDocument == null || schema == null)
    {
        throw new ArgumentNullException();
    }

    using (var reader = XmlReader.Create(new StringReader(xmlDocument.InnerXml)))
    {
        var validator = new SchemaValidator();
        validator.Validate(schema, reader);

        if (validator.HasError)
        {
