{
    private bool _hasError;

    public bool HasError
    {
        get { return _hasError; }
    }

    public override void Warning(ValidationEventArgs args)
    {
        // Ignore warnings
    }

    public override void Error(ValidationEventArgs args)
    {
        _hasError = true;
    }

    public override void FatalError(ValidationEventArgs args)
    {
        _hasError = true;
    }
}

public static XmlSchema GetXmlSchema(string schemaFilePath)
{
    using (var stream = File.OpenRead(schemaFilePath))
    {
        return XmlSchema.Read(stream, null);
    }
}

public static XmlDocument CreateValidatingXmlDocument(string xmlString, XmlSchema schema)
{
    using (var reader = XmlReader.Create(new StringReader(xmlString)))
    {
        var document = new XmlDocument();
        document.Load(reader);

        using (var xmlReader = XmlReader.Create(new StringReader(xmlString)))
        {
            xmlReader.Schemas.Add(schema);
            document.Load(xmlReader);
        }

        return document;
    }
}

