                    string logQuery = "DELETE FROM TrackableItemsLog WHERE TrackableItemId = @Id";
                    using (SqlCommand logCommand = new SqlCommand(logQuery, connection, transaction))
                    {
                        logCommand.Parameters.AddWithValue("@Id", itemId);
                        logCommand.ExecuteNonQuery();
                    }
                }

                transaction.Commit();
            }
            catch (Exception ex)
            {
                transaction.Rollback();
                throw new Exception("An error occurred while deleting trackable items.", ex);
            }
        }
    }
}
