public class ProcessRunner
{
    public static int RunProcess(string fileName, string arguments, bool showPopup, string workingDirectory = null, string[] additionalEnvVars = null)
    {
        try
        {
            using (Process process = new Process())
            {
                process.StartInfo.FileName = fileName;
                process.StartInfo.Arguments = arguments;
                process.StartInfo.WorkingDirectory = workingDirectory ?? Directory.GetCurrentDirectory();
                process.StartInfo.UseShellExecute = false;
                process.StartInfo.RedirectStandardOutput = true;
                process.StartInfo.RedirectStandardError = true;
                process.StartInfo.CreateNoWindow = !showPopup;

                if (additionalEnvVars != null)
                {
                    foreach (var envVar in additionalEnvVars)
                    {
                        string[] keyValue = envVar.Split(new[] { '=' }, 2);
                        if (keyValue.Length == 2)
                        {
                            process.StartInfo.EnvironmentVariables[keyValue[0]] = keyValue[1];
                        }
                    }
                }

                StringBuilder output = new StringBuilder();
                StringBuilder error = new StringBuilder();

                process.OutputDataReceived += (sender, e) => output.AppendLine(e.Data);
                process.ErrorDataReceived += (sender, e) => error.AppendLine(e.Data);

                process.Start();
                process.BeginOutputReadLine();
                process.BeginErrorReadLine();
                process.WaitForExit();

                Console.WriteLine(output.ToString());
                Console.Error.WriteLine(error.ToString());

                return process.ExitCode;
            }
        }
        catch (Exception ex) when (ex is SecurityException || ex is FileNotFoundException || ex is ArgumentException)
        {
            Console.Error.WriteLine("An error occurred while trying to run the process.");
            return -1;
        }
        catch (Exception)
        {
            Console.Error.WriteLine("An unexpected error occurred.");
            return -1;
        }
    }
}
