using System.Diagnostics;
using System.IO;

public static void CopySafeFiles(string sourceDirectory, string targetDirectory, string[] includeExtensions, string[] excludeExtensions)
{
    if (!Directory.Exists(sourceDirectory))
    {
        throw new DirectoryNotFoundException(sourceDirectory);
    }

    if (!Directory.Exists(targetDirectory))
    {
        Directory.CreateDirectory(targetDirectory);
    }

    string[] files = Directory.GetFiles(sourceDirectory, "*");

    foreach (string file in files)
    {
        string fileName = Path.GetFileName(file);
        string extension = Path.GetExtension(file);

        bool include = false;
        foreach (string ext in includeExtensions)
        {
            if (extension.Equals(ext, StringComparison.OrdinalIgnoreCase))
            {
                include = true;
                break;
            }
        }

        bool exclude = false;
        foreach (string ext in excludeExtensions)
        {
            if (extension.Equals(ext, StringComparison.OrdinalIgnoreCase))
            {
                exclude = true;
                break;
            }
        }

        if (!include && !exclude) continue;

        string targetPath = Path.Combine(targetDirectory, fileName);
        Process.Start("xcopy", $"\"{sourceDirectory}\\{fileName}\" \"{targetPath}\" /Y");
    }

    string[] directories = Directory.GetDirectories(sourceDirectory);

    foreach (string dir in directories)
    {
        string dirName = Path.GetFileName(dir);
        string targetDirPath = Path.Combine(targetDirectory, dirName);

        CopySafeFiles(dir, targetDirPath, includeExtensions, excludeExtensions);
    }
