```csharp using System;
using System.Diagnostics;

public static class CommandExecutor
{
    public static void ExecuteWithInputOutputRedirect(string utilityPath, string arguments, Action<string> outputHandler, Action<string> errorHandler, string input = null)
    {
        using (Process process = new Process())
        {
            process.StartInfo.FileName = utilityPath;
            process.StartInfo.Arguments = arguments;
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.RedirectStandardInput = true;
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.RedirectStandardError = true;

            if (input != null)
            {
                process.StartInfo.CreateNoWindow = true; // Hide the command window
                process.StartInfo.UseShellExecute = true; // Needed for setting input on Windows
                process.Start();
                process.StandardInput.Write(input);
                process.StandardInput.Close();
                process.StartInfo.UseShellExecute = false;
                process.StartInfo.CreateNoWindow = false;
            }

            process.OutputDataReceived += (sender, args) => outputHandler(args.Data);
            process.ErrorDataReceived += (sender, args) => errorHandler(args.Data);

            process.Start();
            process.WaitForExit();

            if (process.ExitCode != 0)
            {
                throw new Exception("Command execution failed with exit code: " + process.ExitCode);
            }
        }
    }
}
