public class RemoteServiceClient
{
    private readonly string _remoteServiceUrl;

    public RemoteServiceClient(string remoteServiceUrl)
    {
        _remoteServiceUrl = remoteServiceUrl;
    }

    public async Task<string> ExecuteCommandAndCallRemoteMethodAsync(string command, string methodName, object[] methodArguments)
    {
        string output = string.Empty;

        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = command,
            UseShellExecute = false,
            RedirectStandardOutput = true,
            CreateNoWindow = true
        };

        using (Process process = new Process())
        {
            process.StartInfo = startInfo;
            process.Start();

            using (StreamReader reader = process.StandardOutput)
            {
                output = await reader.ReadToEndAsync();
            }

            process.WaitForExit();

            if (process.ExitCode != 0)
            {
                throw new Exception($"Command '{command}' failed with exit code {process.ExitCode}");
            }
        }

        using (HttpClient httpClient = new HttpClient())
        {
            for (int retryCount = 0; retryCount < 3; retryCount++)
            {
                try
                {
                    string json = JsonConvert.SerializeObject(new { MethodName = methodName, Arguments = methodArguments });
                    StringContent content = new StringContent(json, System.Text.Encoding.UTF8, "application/json");

                    HttpResponseMessage response = await httpClient.PostAsync(_remoteServiceUrl, content);
                    response.EnsureSuccessStatusCode();

                    string responseBody = await response.Content.ReadAsStringAsync();
                    output += $"\nRemote method '{methodName}' returned: {responseBody}";
                    break;
                }
                catch (Exception ex)
                {
                    if (retryCount < 2)
                    {
                        await Task.Delay(1000);
                        continue;
                    }

                    throw new Exception($"Failed to call remote method '{methodName}' after {retryCount + 1} retries: {ex.Message}");
                }
            }
        }

        return output;
    }
}

public static void Main(string[] args)
{
