    string remoteServiceUrl = "http://remote-service:8080/api";
    string methodName = "RemoteMethod";
    object[] methodArguments = new object[] { 1, 2, 3 };

    using (RemoteServiceClient client = new RemoteServiceClient(remoteServiceUrl))
    {
        string output = client.ExecuteCommandAndCallRemoteMethodAsync(command, methodName, methodArguments).Result;
        Console.WriteLine(output);
    }
}
