public class DesDecryptor
{
    private static readonly byte[] Key = Encoding.ASCII.GetBytes("SECRETKY"); // Fixed key for DES

    public static string DecryptHexMessage(string hexMessage)
    {
        if (string.IsNullOrEmpty(hexMessage) || !Regex.IsMatch(hexMessage, @"^[0-9a-fA-F]+$"))
        {
            throw new ArgumentException("Input string is not a valid hexadecimal representation.");
