    {
        // Validate email and personId inputs
        if (string.IsNullOrWhiteSpace(email) || string.IsNullOrWhiteSpace(personId))
        {
            throw new ArgumentException("Email and personId must not be null or empty.");
        }

        // Build request to retrieve URL from web service
        using var client = new HttpClient();
        string urlTemplate = "https://webservice.com/api/getRedirectUrl?email={email}&personId={personId}";
        string url = string.Format(urlTemplate, email, personId);
        HttpResponseMessage response = await client.GetAsync(url, request);

        // Validate and sanitize retrieved URL
        if (!Uri.IsWellFormedUriString(response.Content.ReadAsStringAsync().Result, UriKind.Absolute))
        {
            throw new ArgumentException("Invalid or malformed URL retrieved from web service.");
        }

        // Redirect to the retrieved URL
        HttpResponseMessage redirectResponse = await client.GetAsync(new Uri(response.Content.ReadAsStringAsync().Result));
        if (!redirectResponse.IsSuccessStatusCode)
        {
            // Log error with minimal sensitive information
            string errorMessage = $"Error occurred while redirecting: Status code: {redirectResponse.StatusCode}";
            Console.Error.WriteLine(errorMessage);
        }
    }
    catch (Exception ex)
    {
        // Log detailed error messages with sensitive information only in development environment
        if (Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") == "Development")
        {
            Console.Error.WriteLine($"Error: {ex.Message}");
            Console.Error.WriteLine($"Stack trace: {ex.StackTrace}");
        }
        else
        {
            Console.Error.WriteLine("An error occurred.");
        }
    }
}
