```csharp using System;
using System.Diagnostics;
using System.IO;

public static bool OpenProjectOrSolution(string projectPath)
{
    if (!File.Exists(projectPath))
    {
        throw new FileNotFoundException("Project or solution file not found.", projectPath);
    }

    string extension = Path.GetExtension(projectPath).ToLowerInvariant();

    if (extension == ".sln") // Solution file
    {
        Process.Start("devenv.exe", $"\"{projectPath}\" /resetuserdata"); // Open solution with Visual Studio and reset user data
    }
    else if (extension == ".csproj" || extension == ".vbproj") // Project file
    {
        Process.Start("devenv.exe", $"\"{projectPath}\" /open"); // Open project with Visual Studio
    }
    else
    {
        throw new ArgumentException("Invalid project or solution file extension.", nameof(projectPath));
    }

    return true;
}
