public class SecureControlPanel
{
    private readonly Button _button;

    public SecureControlPanel(string absoluteFilePath)
    {
        var form = new Form();
        form.Text = "SecureControlPanel";

        _button = new Button
        {
            Text = "_Click to start process",
            Width = 100,
            Height = 30,
            Top = 10,
            Left = 10,
            Click += (sender, e) => StartProcess(absoluteFilePath)
        };

        form.Controls.Add(_button);
        form.Size = new Size(200, 150);
        Application.Run(form);
    }

    private void StartProcess(string absoluteFilePath)
    {
        if (string.IsNullOrEmpty(absoluteFilePath))
        {
            throw new ArgumentNullException(nameof(absoluteFilePath));
        }

        if (!File.Exists(absoluteFilePath))
        {
            throw new FileNotFoundException(absoluteFilePath);
        }

        using (var process = new Process())
        {
            process.StartInfo.FileName = "cmd.exe";
            process.StartInfo.Arguments = $"/c start \"{Path.GetFileName(absoluteFilePath)}\" \"{absoluteFilePath}\"";
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.RedirectStandardOutput = false;
            process.StartInfo.CreateNoWindow = true;

            try
            {
                process.Start();
            }
            catch (Exception ex)
            {
                throw new SynapseError($"Failed to start process: {ex.Message}");
            }
        }
    }
}
