public static string EncryptTripleDES(string inputData, Guid key1, Guid key2)
{
    using (TripleDESCryptoServiceProvider tripleDES = new TripleDESCryptoServiceProvider())
    {
        // Set keys
        byte[] keyByte1 = key1.ToByteArray();
        byte[] keyByte2 = key2.ToByteArray();
        byte[] key = new byte[24]; // Triple DES requires 3 keys, each of size 8 bytes
        Array.Copy(keyByte1, 0, key, 0, 8);
        Array.Copy(keyByte2, 0, key, 8, 8);
        tripleDES.Key = key;

        // Set IV (Initialization Vector)
