                csEncrypt.Write(inputDataBytes, 0, inputDataBytes.Length);
            }
            encryptedData = msEncrypt.ToArray();
        }

        // Base64 encode encrypted data
        string encryptedString = Convert.ToBase64String(encryptedData);
        return encryptedString;
    }
