class Program
{
    static void Main(string[] args)
    {
        if (args.Length < 2)
        {
            Console.WriteLine("Usage: UpdateApp <sourcePath> <destinationPath>");
            return;
        }

        string sourcePath = args[0];
        string destinationPath = args[1];

        try
        {
            ValidateFilePath(sourcePath);
            ValidateFilePath(destinationPath);

            if (File.Exists(destinationPath))
            {
                File.Delete(destinationPath);
            }

            File.Copy(sourcePath, destinationPath);

            if (IsElevationRequired(destinationPath))
            {
                RunWithElevatedPrivileges(destinationPath);
            }
            else
            {
                Process.Start(destinationPath);
            }
        }
        catch (SecurityException ex)
        {
            Console.WriteLine($"Security error: {ex.Message}");
        }
        catch (UnauthorizedAccessException ex)
        {
            Console.WriteLine($"Access denied: {ex.Message}");
        }
        catch (IOException ex)
        {
            Console.WriteLine($"IO error: {ex.Message}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }

    static void ValidateFilePath(string path)
    {
        if (string.IsNullOrWhiteSpace(path))
        {
            throw new ArgumentException("Path cannot be null or empty.");
        }

        if (!Path.IsPathRooted(path))
        {
            throw new ArgumentException("Path must be absolute.");
        }

        if (path.Contains(".."))
        {
            throw new ArgumentException("Path cannot contain relative navigation.");
        }

        string extension = Path.GetExtension(path).ToLower();
        if (extension != ".exe")
        {
            throw new ArgumentException("Only .exe files are allowed.");
        }
    }

    static bool IsElevationRequired(string path)
    {
        try
        {
            using (FileStream fs = File.OpenRead(path))
            {
                return false;
            }
        }
        catch (UnauthorizedAccessException)
        {
            return true;
        }
    }

    static void RunWithElevatedPrivileges(string path)
    {
        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = path,
            UseShellExecute = true,
            Verb = "runas"
        };

        try
        {
            Process.Start(startInfo);
        }
        catch (System.ComponentModel.Win32Exception)
        {
            Console.WriteLine("User declined to elevate privileges.");
        }
    }
