public string UpdateXmlFile(string filePath, string xPathToRemove, string xPathToInsertAfter) {
    if (string.IsNullOrEmpty(filePath) || string.IsNullOrEmpty(xPathToRemove) || string.IsNullOrEmpty(xPathToInsertAfter)) {
        throw new ArgumentException("Invalid arguments.");
