    XPathNodeType nodeTypeToInsertAfter = XPathNodeType.Element;

    XPathNodeIterator removeIterator = navigator.Select(removeExpression, xmlDoc.DocumentElement);

    if (removeIterator.Count < 1) {
        throw new FileNotFoundException("Element not found.");
    }

    XPathNodeIterator insertIterator = navigator.Select(insertExpression, removeIterator.Current.Parent);

    if (insertIterator.Count < 1) {
        throw new ArgumentException("Invalid XPath expression to insert after.");
    }

    XmlNode nodeToRemove = removeIterator.Current.Parent.RemoveChild(removeIterator.Current);
    xmlDoc.DocumentElement.InsertBefore(nodeToRemove, insertIterator.Current.NextSibling);

