```csharp using System.Diagnostics;
using System.Threading;

public static void StartCommandPromptAndCleanup()
{
    ProcessStartInfo startInfo = new ProcessStartInfo
    {
        FileName = "cmd.exe",
        UseShellExecute = false,
        RedirectStandardOutput = true,
        CreateNoWindow = true
    };

    Process process = new Process();
    process.StartInfo = startInfo;
    process.Start();

    CancellationTokenSource cts = new CancellationTokenSource();
    Thread cleanupThread = new Thread(() =>
    {
        if (process.HasExited) return;
        process.Kill();
        cts.Cancel();
    });
    cleanupThread.Start();

    // Parent window unloading event handler
    AppDomain.CurrentDomain.DomainUnloading += (sender, args) =>
    {
        cts.Cancel();
        process.WaitForExit();
    };

    string output = process.StandardOutput.ReadToEnd();
    process.WaitForExit();

    cleanupThread.Join();

    Console.WriteLine("Command prompt output: " + output);
}
```

