            stream.Position = 0;
            using (var reader = new StreamReader(stream))
            {
                return reader.ReadToEnd();
            }
        }
    }

    private static bool IsPathSafe(string filePath)
    {
        var safeBaseDirectory = Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "SafeDirectory"));
        var fullFilePath = Path.GetFullPath(filePath);

        return fullFilePath.StartsWith(safeBaseDirectory, StringComparison.OrdinalIgnoreCase);
    }
}
