public XDocument UpdateConfigurationFile(string filePath, XElement newSearchProviderFragment, string xPathExpression)
{
    if (string.IsNullOrEmpty(filePath) || string.IsNullOrEmpty(xPathExpression))
    {
        throw new ArgumentException("filePath and xPathExpression are required.");
    }

    XDocument configurationDocument = XDocument.Load(filePath);

    // Validate the root element exists
    if (configurationDocument.Root == null)
    {
        throw new ArgumentException("Invalid configuration file.");
    }

    XElement rootElement = configurationDocument.Root;

    // Validate the XPath expression
    XPathDocument xPathDocument = new XPathDocument(configurationDocument.CreateReader());
    XPathNavigator navigator = xPathDocument.CreateNavigator();
    navigator.MoveTo(XPathNodeType.Root, "/");

    if (!navigator.Evaluate(xPathExpression, "Context") as XPathNavigator?.IsEmpty)
    {
        throw new ArgumentException("Invalid xPathExpression. The specified path does not exist in the configuration file.");
    }

    // Insert the new search provider fragment
