using System.Xml.Linq;

public XElement RemoveAndAddConfigNode(XDocument xmlDoc, string key, XElement newNode)
{
    if (xmlDoc == null) throw new ArgumentNullException(nameof(xmlDoc));
    if (string.IsNullOrWhiteSpace(key)) throw new ArgumentException("Key cannot be null or whitespace.", nameof(key));
    if (newNode == null) throw new ArgumentNullException(nameof(newNode));

    XElement configNodeToRemove = xmlDoc.Descendants("Configuration").FirstOrDefault(x => (string)x.Attribute("Key") == key);
    if (configNodeToRemove != null)
    {
        configNodeToRemove.Remove();
    }

    XElement newConfigNode = new XElement("Configuration", newNode);
    newConfigNode.SetAttributeValue("Key", key);
    xmlDoc.Root.Add(newConfigNode);

    return newConfigNode;
}
