public class ActivityService
{
    private readonly DataContext _context;

    public ActivityService(DataContext context)
    {
        _context = context;
    }

    public async Task UpdateActivityImageAsync(int activityId, IFormFile file, ClaimsPrincipal user)
    {
        if (!user.IsInRole("Admin"))
        {
            throw new UnauthorizedAccessException("User is not an admin of the activity's organization.");
        }

        var activity = await _context.Activities
            .Include(a => a.Organization)
            .FirstOrDefaultAsync(a => a.Id == activityId);

        if (activity == null)
        {
            throw new ArgumentException("Activity not found.");
        }

        if (activity.OrganizationId != user.FindFirst(c => c.Type == ClaimTypes.Name).Value)
        {
            throw new UnauthorizedAccessException("User is not authorized to update this activity.");
        }

        if (file == null || file.Length == 0)
        {
            throw new ArgumentNullException(nameof(file), "File cannot be null or empty.");
        }

        string fileName = Path.GetFileName(file.FileName);
        string fileExtension = Path.GetExtension(file.FileName);
        string storagePath = Path.Combine("uploads", activity.Id.ToString(), fileName);

        using (var stream = new FileStream(storagePath, FileMode.Create))
        {
            await file.CopyToAsync(stream);
        }

        activity.ImageUrl = $"/uploads/{activity.Id}/{fileName}";
        await _context.SaveChangesAsync();
    }
}

