import org.apache.thrift.transport.TTransport;
import org.apache.thrift.transport.TTransportException;

public class SecureIoHandlerAdapter implements org.apache.thrift.server.IoHandler {

    private final TProtocol protocol;
    private final TTransport transport;

    public SecureIoHandlerAdapter(TProtocol protocol, TTransport transport) {
        this.protocol = protocol;
        this.transport = transport;
    }

    @Override
    public void handle(TMessage message) throws TException {
        if (message.type == TMessageType.RESPONSE) {
            processResponse(message);
        } else {
            throw new TTransportException("Invalid message type: " + message.type);
        }
    }

    private void processResponse(TMessage message) throws TException {
        TBase response = message.getBody();
        TProtocol sessionProtocol = protocol.getProtocolFactory().getProtocol(transport);
        sessionProtocol.readMessageBegin(response.getClass());

        while (sessionProtocol.readFieldBegin()) {
            TField field = sessionProtocol.readFieldBegin();
            Object fieldValue = sessionProtocol.readFieldValue(field.type);
            // Process the field value here
            sessionProtocol.readFieldEnd();
        }

        sessionProtocol.readMessageEnd();
    }

    @Override
    public void transportDamaged() {
        try {
            transport.close();
        } catch (TTransportException e) {
            // Log error and close the transport
            e.printStackTrace();
        }
    }

    public void setSocketAddress(int port, String ipAddress) throws TException {
        if (transport instanceof TSocket) {
            TSocket socket = (TSocket) transport;
            socket.setTcpNodeAddress(ipAddress, port);
        } else {
            throw new TTransportException("Transport is not a TSocket");
        }
    }
}
