import java.util.ArrayList;
import java.util.Random;
import java.util.function.Supplier;

public class GaussianRandom {

    private static final double SQRT_2PI = 2.5066282746310005;
    private static final double INV_SQRT_2PI = 0.3989422804014327;

    public static double generateGaussianRandom(Random random, double mean, double stdDev, double lowerBound, double upperBound) {
        double z0, z, u1, u2;

        do {
            u1 = random.nextGaussian();
            u2 = random.nextGaussian();
            z = Math.sqrt(-2.0 * Math.log(1.0 - Math.exp(-Math.pow(u1, 2) / 2.0))) * u1;
            z0 = z;
            z += Math.sqrt(-2.0 * Math.log(1.0 - Math.exp(-Math.pow(u2, 2) / 2.0))) * u2;
        } while (z > upperBound || z < lowerBound);

        return mean + stdDev * z / SQRT_2PI;
    }

    public static ArrayList<Double> generateGaussianRandomValues(Random random, int numValues, double mean, double stdDev, double lowerBound, double upperBound) {
        ArrayList<Double> values = new ArrayList<>();

        Supplier<Double> randomSupplier = () -> GaussianRandom.generateGaussianRandom(random, mean, stdDev, lowerBound, upperBound);

        for (int i = 0; i < numValues; i++) {
            values.add(randomSupplier.get());
        }

        return values;
    }
}
