import java.util.Random;

public enum ValidType { INT, FLOAT, BOOL, STRING };

public static <T> T getRandomValue(Class<T> type, ValidType validType, int range) {
    Random random = new Random();
    T value;
    switch (validType) {
        case INT:
            value = (T) ((int) (random.nextInt(range) + 1));
            break;
        case FLOAT:
            value = (T) ((float) random.nextFloat() * range);
            break;
        case BOOL:
            value = (T) (random.nextBoolean());
            break;
        case STRING:
