import org.apache.lucene.search.ScoreDoc;
import org.apache.lucene.search.TopDocs;
import org.hamcrest.MatcherAssert;
import org.hamcrest.Matchers;

public void compareNumericFields(String indexPath, String docId1, String docId2, String fieldName) {
    try (IndexReader reader = IndexReader.open(indexPath)) {
        IndexSearcher searcher = new IndexSearcher(reader);

        Query query1 = new ClassicQueryParser("", new Analyzer(), new MultiField("*:*")).parse(fieldName + ":[" + docId1 + "]");
        TopDocs topDocs1 = searcher.search(query1, 1).scoreDocs;
        Document doc1 = searcher.doc(topDocs1.scoreDocs[0].doc);
        NumericField numericField1 = (NumericField) doc1.getFields().get(fieldName);

        Query query2 = new ClassicQueryParser("", new Analyzer(), new MultiField("*:*")).parse(fieldName + ":[" + docId2 + "]");
        TopDocs topDocs2 = searcher.search(query2, 1).scoreDocs;
        Document doc2 = searcher.doc(topDocs2.scoreDocs[0].doc);
        NumericField numericField2 = (NumericField) doc2.getFields().get(fieldName);

        // Check that the number of values in each field is the same
        MatcherAssert.assertThat(numericField1.size(), Matchers.equalTo(numericField2.size()));

        // Compare the values in each document using the assertThat() method
        MatcherAssert.assertThat(numericField1.get(0), Matchers.equalTo(numericField2.get(0)));
    } catch (Exception e) {
        // Handle exceptions appropriately
    }
}
