import java.util.List;
import java.util.Random;

public void shufflePairs(List<Pair> pairs, double percentage) {
    Random random = new Random();
    int numIterations = (int) Math.ceil(pairs.size() * percentage / 100.0);
    int currentIndex = pairs.size() - 1;

    for (int i = 0; i < numIterations; i++) {
        if (currentIndex == 0) {
            System.out.println("Last pair: " + pairs.get(currentIndex).toString());
            break;
        }

        int randomIndex = random.nextInt(currentIndex + 1);
        Pair tempPair = pairs.get(currentIndex);
        Pair targetPair = pairs.get(randomIndex);

        if (currentIndex > randomIndex) {
            pairs.set(randomIndex, tempPair);
            pairs.set(currentIndex, targetPair);
        }

        System.out.println("Swapped pair at index " + currentIndex + " with pair at index " + randomIndex);
        currentIndex--;
    }
}

class Pair {
    int number;
    boolean booleanValue;

    public Pair(int number, boolean booleanValue) {
        this.number = number;
        this.booleanValue = booleanValue;
    }

    @Override
    public String toString() {
        return "(" + number + ", " + booleanValue + ")";
    }
}
