import java.io.ByteArrayInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.RandomAccessFile;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.SecureRandom;

public static RandomAccessFile generateRandomFile(Path folderPath, String fileName, int fileLength) throws IOException {
    Path filePath = Paths.get(folderPath.toAbsolutePath(), fileName);
    RandomAccessFile fileHandle = null;
    try {
        fileHandle = new RandomAccessFile(filePath.toFile(), "rw");
        fileHandle.setLength(fileLength);

        SecureRandom random = new SecureRandom();
        byte[] randomData;

        for (int remainingLength = fileLength; remainingLength > 0; ) {
            int dataLength = Math.min(remainingLength, 1024); // Limit the size of the data to be written at once
            randomData = new byte[dataLength];
            random.nextBytes(randomData);

            FileOutputStream outputStream = new FileOutputStream(filePath.toFile());
            outputStream.write(randomData, 0, randomData.length);
            outputStream.close();

            remainingLength -= randomData.length;
        }
    } finally {
        if (fileHandle != null) {
            fileHandle.close();
        }
    }

    return new RandomAccessFile(filePath.toFile(), "r");
}
