```java
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.Mac;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.SecureRandom;
import java.util.Arrays;

public class AesEncryption {
    private static final int AES_BLOCK_SIZE = 16;

    public static void main(String[] args) throws Exception {
        byte[] password = "password".getBytes();
        byte[] salt = "salt".getBytes();
        int iterations = 1000;

        SecretKey key = generateKey(password, salt, iterations);
        byte[] encryptedData = encryptData(key, "plaintext".getBytes(), salt);
        byte[] decryptedData = decryptData(key, encryptedData);

        System.out.println("Encrypted data: " + Arrays.toString(encryptedData));
        System.out.println("Decrypted data: " + new String(decryptedData));
    }

    private static SecretKey generateKey(byte[] password, byte[] salt, int iterations) throws Exception {
        KeyGenerator keyGenerator = KeyGenerator.getInstance("AES");
        keyGenerator.init(128);

        Mac hmac = Mac.getInstance("HmacSHA1");
        hmac.init(new SecretKeySpec(password, "RAW"));
        hmac.update(salt);

        byte[] keyBytes = new byte[16];
        hmac.doFinal(keyBytes, 0, keyBytes.length);

        SecretKey key = new SecretKeySpec(keyBytes, "AES");
        return key;
    }

    private static byte[] encryptData(SecretKey key, byte[] data, byte[] salt) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CBC/NoPadding");
        IvParameterSpec iv = generateIv(salt);
        cipher.init(Cipher.ENCRYPT_MODE, key, iv);

        byte[] encryptedData = cipher.doFinal(data);
        return encryptedData;
    }

    private static byte[] decryptData(SecretKey key, byte[] encryptedData) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CBC/NoPadding");
        IvParameterSpec iv = generateIv(encryptedData, 0, AES_BLOCK_SIZE);
        cipher.init(Cipher.DECRYPT_MODE, key, iv);

        byte[] decryptedData = cipher.doFinal(encryptedData);
        return decryptedData;
    }

    private static IvParameterSpec generateIv(byte[] data, int offset, int length) {
        if (data == null || data.length < offset + length) {
            throw new IllegalArgumentException("Invalid data");
        }

        byte[] iv = new byte[length];
        System.arraycopy(data, offset, iv, 0, length);
        return new IvParameterSpec(iv);
    }

    private static IvParameterSpec generateIv(byte[] salt) {
        SecureRandom random = new SecureRandom();
        byte[] iv = new byte[AES_BLOCK_SIZE];
        random.nextBytes(iv);

        if (Arrays.equals(salt, iv)) {
            generateIv(salt); // Recursively call to generate a new IV
        }

        return new IvParameterSpec(iv);
    }
}
