private static Bitmap sCurrentThemeBitmap;

public static void cacheTheme(Bitmap themeBitmap) {
    if (themeBitmap != null && sCurrentThemeBitmap != null && sCurrentThemeBitmap.isRecycled()) {
        sCurrentThemeBitmap.recycle();
        sCurrentThemeBitmap = null;
    }
    sCurrentThemeBitmap = themeBitmap;

    File themeCacheDir = new File(THEME_CACHE_DIR);
    if (!themeCacheDir.exists()) {
        if (!themeCacheDir.mkdirs()) {
            Log.e("ThemeCache", "Failed to create theme cache directory");
            return;
        }
    }

    File themeFile = new File(themeCacheDir, "theme.png");
    try (FileOutputStream fos = new FileOutputStream(themeFile)) {
        themeBitmap.compress(Bitmap.CompressFormat.PNG, 100, fos);
    } catch (IOException e) {
        Log.e("ThemeCache", "Failed to save theme to cache", e);
    }
}

public static Bitmap getThemeFromCache() {
    if (sCurrentThemeBitmap != null && !sCurrentThemeBitmap.isRecycled()) {
        return sCurrentThemeBitmap;
    }

    File themeCacheDir = new File(THEME_CACHE_DIR);
    File themeFile = new File(themeCacheDir, "theme.png");
    if (!themeFile.exists()) {
        return null;
    }

    try (FileInputStream fis = new FileInputStream(themeFile)) {
        Bitmap themeBitmap = BitmapFactory.decodeStream(fis);
        sCurrentThemeBitmap = themeBitmap;
        return themeBitmap;
    } catch (IOException e) {
        Log.e("ThemeCache", "Failed to load theme from cache", e);
        return null;
    }
}
