import java.io.IOException;
import java.io.InputStream;
import java.net.URL;

public InputStream getResourceAsStream(String resourcePath) {
    String resourceRoot = this.getClass().getResource("/").getPath(); // Get the root path of the class file
    URL url;

    // Check if the resource is local
    if (resourcePath.startsWith("/")) {
        url = new URL(resourceRoot + resourcePath);
    } else {
        try {
            url = new URL(resourcePath);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Invalid URL: " + resourcePath, e);
        }
    }

    try {
        if (url.getProtocol().equals("file")) { // Check if the resource is a local file
            if (!isValidLocalPath(url.getPath())) {
                throw new IllegalArgumentException("Invalid local path: " + url.getPath());
            }
            return new FileInputStream(url.getFile());
        } else { // The resource is remote, download it
            try (InputStream inputStream = downloadResource(url)) {
                return inputStream;
            }
        }
    } catch (IOException e) {
        throw new SynapseError("Error loading resource: " + resourcePath, e);
    }
}

private boolean isValidLocalPath(String path) {
    String localHostnames[] = {"", ".", "localhost", "127.0.0.1"};
    for (String localHostname : localHostnames) {
        if (path.startsWith(localHostname)) {
            return false;
        }
    }
    return true;
}

private InputStream downloadResource(URL url) throws IOException {
    try (InputStream inputStream = url.openConnection().getInputStream()) {
        if (inputStream == null) {
            throw new SynapseError("Error downloading resource: " + url.toString());
        }
        return inputStream;
    }
}
