import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

class GraphVertex {
    int id;
    volatile boolean visited;

    GraphVertex(int id) {
        this.id = id;
        this.visited = false;
    }
}

class Graph {
    final int numVertices;
    GraphVertex[] vertices;

    Graph(int numVertices) {
        this.numVertices = numVertices;
        this.vertices = new GraphVertex[numVertices];
        for (int i = 0; i < numVertices; i++) {
            this.vertices[i] = new GraphVertex(i);
        }
    }

    void traverseGraph(int startVertex, AtomicInteger verticesVisited, AtomicInteger edgesTraversed, AtomicInteger threadsCompleted) {
        GraphVertex currentVertex = vertices[startVertex];
        currentVertex.visited = true;
        verticesVisited.increment();

        for (int neighbor = 0; neighbor < numVertices; neighbor++) {
            if (vertices[neighbor].id != startVertex && !vertices[neighbor].visited) {
                new Thread(() -> {
                    traverseGraph(neighbor, verticesVisited, edgesTraversed, threadsCompleted);
                }).start();

                edgesTraversed.increment();
            }
        }

        threadsCompleted.increment();
    }

    void run() throws InterruptedException {
        AtomicInteger verticesVisited = new AtomicInteger(0);
        AtomicInteger edgesTraversed = new AtomicInteger(0);
        AtomicInteger threadsCompleted = new AtomicInteger(0);

        ExecutorService executor = Executors.newFixedThreadPool(numVertices);
        executor.submit(() -> traverseGraph(0, verticesVisited, edgesTraversed, threadsCompleted));

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

        System.out.println("Number of vertices: " + numVertices);
        System.out.println("Number of edges: " + edgesTraversed.get());
        System.out.println("Number of completed threads: " + threadsCompleted.get());
    }
}

public class ConcurrentGraphTraversal {
    public static void main(String[] args) throws InterruptedException {
        Graph graph = new Graph(5);
        graph.run();
    }
}
