import java.util.List;
import java.util.function.Function;

public static HashMap<Object, Double> normalizeWeightsProbabilistically(List<Object> items, Function<Object, Double> normalizer) {
    HashMap<Object, Double> normalizedWeights = new HashMap<>();
    for (Object item : items) {
        double normalizedWeight = normalizer.apply(item);
        double randomNumber = Math.random();
        double cumulativeProbability = 0;
        double currentProbability = 0;
        Object currentItem = null;
        for (Map.Entry<Object, Double> entry : normalizedWeights.entrySet()) {
            currentProbability += entry.getValue();
            cumulativeProbability += entry.getValue();
            if (randomNumber < cumulativeProbability) {
                normalizedWeights.put(item, normalizedWeight);
                break;
            }
            currentItem = entry.getKey();
        }
        if (currentItem == null) {
            normalizedWeights.put(item, normalizedWeight);
        }
    }
    return normalizedWeights;
}
