import org.xml.sax.Attributes;
import org.xml.sax.SAXException;
import org.xml.sax.helpers.DefaultHandler;

public class SaxParserWithErrorReporting extends DefaultHandler {

    private boolean errorOccurred = false;

    @Override
    public void startDocument() throws SAXException {
        System.out.println("Start document");
    }

    @Override
    public void startElement(String uri, String localName, String qName, Attributes attributes) throws SAXException {
        System.out.println("Start element: " + localName);
        for (int i = 0; i < attributes.getLength(); i++) {
            String attributeName = attributes.getLocalName(i);
            String attributeValue = attributes.getValue(i);
            System.out.println("Attribute: " + attributeName + "=" + attributeValue);
        }
    }

    @Override
    public void characters(char[] ch, int start, int length) throws SAXException {
        if (errorOccurred) {
            throw new SAXException("Error reporting: Unable to parse characters after error.");
        }
        System.out.print("Data: ");
        System.out.write(ch, start, length);
    }

    @Override
    public void endElement(String uri, String localName, String qName) throws SAXException {
        System.out.println("End element: " + localName);
    }

    @Override
    public void warning(SAXParseException exception) throws SAXException {
        System.err.println("Warning: " + exception.getMessage());
    }

    @Override
    public void error(SAXParseException exception) throws SAXException {
        errorOccurred = true;
        System.err.println("Error: " + exception.getMessage());
        throw exception;
    }

    @Override
    public void fatalError(SAXParseException exception) throws SAXException {
        errorOccurred = true;
        System.err.println("Fatal error: " + exception.getMessage());
        throw exception;
    }

    public static void main(String[] args) {
        try {
            File xmlFile = new File("input.xml");
            SAXParserFactory factory = SAXParserFactory.newInstance();
            SAXParser saxParser = factory.newSAXParser();
            SaxParserWithErrorReporting handler = new SaxParserWithErrorReporting();
            saxParser.parse(new FileInputSource(xmlFile), handler);
        } catch (Exception e) {
            System.err.println("Error parsing XML: " + e.getMessage());
        }
    }
}
