import java.util.DisjointSet;
import java.util.Timer;
import java.util.TimerTask;

public class DisjointPairs {
    public static int countDisjointPairs(int[] arr) {
        int n = arr.length;
        DisjointSet<Integer> set = new DisjointSet<>();
        for (int i = 0; i < n; i++) {
            set.add(arr[i]);
            set.union(i, i + 1);
        }

        int count = 0;
        long startTime;
        for (int i = 0; i < n; i++) {
            int root = set.findSet(arr[i]);
            for (int j = i + 1; j < n; j++) {
                startTime = System.nanoTime();
                int rootJ = set.findSet(arr[j]);
                if (root != rootJ) {
                    count++;
                    System.out.printf("Pair (%d, %d) is disjoint. Time taken: %d ns\n", arr[i], arr[j], System.nanoTime() - startTime);
                }
                set.union(root, rootJ);
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int[] arr = {1, 3, 5, 7, 9};
        int pairs = countDisjointPairs(arr);
        System.out.println("Number of disjoint pairs: " + pairs);
    }
}
