import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.math.BigInteger;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.spec.KeySpec;
import java.util.Base64;

public static String generateSHA1Hash(String input) {
    if (input == null || input.isEmpty()) {
        throw new IllegalArgumentException("Input cannot be empty or null.");
    }

    try {
        SecretKeySpec signingKey = new SecretKeySpec("jKSdfLksdjf12345_key".getBytes(), "HmacSHA1");
        Mac sha1Hmac = Mac.getInstance("HmacSHA1");
        sha1Hmac.init(signingKey);
        byte[] rawHmac = sha1Hmac.doFinal(input.getBytes());

        String hashAsHex = bytesToHex(rawHmac);
        return hashAsHex;
    } catch (NoSuchAlgorithmException | InvalidKeyException e) {
        throw new RuntimeException("Error while generating SHA1 hash.", e);
    }
}

private static String bytesToHex(byte[] bytes) {
    BigInteger bi = new BigInteger(1, bytes);
    String hex = bi.toString(16);
    int len = hex.length();
    if (len < 40) {
        while (len < 40) {
            hex = "0" + hex;
            len++;
        }
    }
    return hex;
}
