import org.keycloak.admin.client.Keycloak;
import org.keycloak.admin.client.resource.RealmResource;
import org.keycloak.admin.client.resource.auth.AuthResource;
import org.keycloak.representations.idm.AuthServerConfigurationRepresentation;
import org.keycloak.representations.idm.RealmRepresentation;
import org.keycloak.representations.idm.security.OAuth2AuthorizationGrantsRepresentation;
import org.keycloak.representations.idm.security.OAuth2FlowsRepresentation;
import org.keycloak.representations.idm.security.OAuth2ProtocolMapRepresentation;
import org.keycloak.representations.idm.security.OpenIDConnectRepresentation;
import org.openapitools.openapi3.models.OpenAPI;
import org.openapitools.openapi3.models.security.OAuthFlow;
import org.openapitools.openapi3.models.security.OAuthFlows;
import org.openapitools.openapi3.models.security.SecurityRequirement;
import org.openapitools.openapi3.models.security.SecurityScheme;

public void configureOpenAPISecurity(OpenAPI openAPI, String keycloakRealmPath) {
    Keycloak keycloak = KeycloakBuilder.builder().serverUrl("http://localhost:8080/auth/admin").realm(keycloakRealmPath).build();
    RealmResource realm = keycloak.realms().findByPath(keycloakRealmPath).toRepresentation();

    OpenIDConnectRepresentation openIDConnect = realm.getOpenIDConnectMapper().toRepresentation(realm.getOpenIDConnectFlow());
    String openIDConnectProvider = openIDConnect.getProvider();

    AuthServerConfigurationRepresentation oauth2Server = realm.getAuth().findFirst(AuthServerConfigurationRepresentation.class);
    OAuth2ProtocolMapRepresentation oauth2ProtocolMap = oauth2Server.getProtocolMaps().stream()
            .filter(map -> map.getProtocol().equals("openid-connect"))
            .findFirst().orElseThrow(() -> new RuntimeException("OpenID Connect protocol map not found"))
            .toRepresentation();
    String oauth2Provider = oauth2ProtocolMap.getProvider();

    SecurityRequirement securityRequirement = new SecurityRequirement();
    securityRequirement.addMap("openid", new String[]{"openid", "oauth2"});

    SecurityScheme openIDConnectScheme = new SecurityScheme();
    openIDConnectScheme.setType("openid-connect");
    openIDConnectScheme.setName("openid");
    openIDConnectScheme.setOpenIDConnectUrl(openIDConnectProvider);

    SecurityScheme oauth2Scheme = new SecurityScheme();
    oauth2Scheme.setType("oauth2");
    oauth2Scheme.setName("oauth2");
    oauth2Scheme.setFlow(new OAuthFlow().addAuthorizationCodeFlow(
            new OAuthFlows.AuthorizationCodeFlow().addAuthorizationCodeBearerFlow(
                    new OAuth2AuthorizationGrantsRepresentation().setType("authorization_code").setName("authorization_code")).getFlow()));

    openAPI.getComponents().getSecuritySchemes().put("openid", openIDConnectScheme);
    openAPI.getComponents().getSecuritySchemes().put("oauth2", oauth2Scheme);
    openAPI.getPaths().values().stream().forEach(path -> path.getGetOperations().stream().forEach(operation -> {
        operation.getSecurity().add(securityRequirement);
    }));
}
