import java.util.Objects;

public class GeoPointComparator {

    private static final double DISTANCE_TOLERANCE = 0.001;

    public static void compareGeoPointSets(List<GeoPointDocument> set1, List<GeoPointDocument> set2) {
        Objects.requireNonNull(set1, "The first set of geo point data cannot be null.");
        Objects.requireNonNull(set2, "The second set of geo point data cannot be null.");

        if (set1.size() != set2.size()) {
            throw new IllegalArgumentException("The number of geo point documents in both sets must be equal.");
        }

        for (int i = 0; i < set1.size(); i++) {
            GeoPointDocument point1 = set1.get(i);
            GeoPointDocument point2 = set2.get(i);

            if (point1.getLatitude() != point2.getLatitude()) {
                throw new AssertionError("The latitude values in both sets do not match at index: " + i);
            }

            if (point1.getLongitude() != point2.getLongitude()) {
                throw new AssertionError("The longitude values in both sets do not match at index: " + i);
            }

            if (!Arrays.equals(point1.getAddress(), point2.getAddress())) {
                throw new AssertionError("The address values in both sets do not match at index: " + i);
            }

            if (!areGeoPointsNearEachOther(point1, point2, DISTANCE_TOLERANCE)) {
                throw new AssertionError("The geo points at index: " + i + " are not within the specified distance tolerance.");
            }
        }
    }

    private static boolean areGeoPointsNearEachOther(GeoPointDocument point1, GeoPointDocument point2, double tolerance) {
        double distance = PointDistanceCalculator.getDistance(point1.getLatitude(), point1.getLongitude(),
                                                              point2.getLatitude(), point2.getLongitude());
        return distance <= tolerance;
    }

