import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.math.BigDecimal;
import java.math.Random;

public class RandomJSONEvents {

    public static void main(String[] args) {
        int numEvents = 10;
        Random random = new SecureRandom(); // Use a cryptographically secure random number generator
        Gson gson = new Gson();

        JsonArray jsonEvents = new JsonArray();

        for (int i = 0; i < numEvents; i++) {
            JsonObject event = new JsonObject();
            event.addProperty("messageNumber", i + 1);
            event.addProperty("gaussianNumber", getGaussianNumber(random));
            jsonEvents.add(event);
