        String jsonString = gson.toJson(jsonEvents);
        System.out.println(jsonString);
    }

    private static BigDecimal getGaussianNumber(Random random) {
        double mean = 50.0;
        double stdDev = 10.0;
        double z0 = random.nextGaussian();
        double x = mean + stdDev * z0;
        return BigDecimal.valueOf(x);
    }
}
