        return delegationToken;
    }

    public boolean verifyDelegationToken(String tokenIdentifier) {
        DelegationToken delegationToken = delegationTokenStore.findDelegationTokenByIdentifier(tokenIdentifier);
        if (delegationToken == null) {
            throw new OAuth2Exception("Invalid token identifier");
        }
        if (delegationToken.isExpired()) {
            throw new OAuth2Exception("Token has expired");
        }
        return true;
    }

    public boolean renewDelegationToken(String tokenIdentifier) {
