import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class SensorDataGenerator {

    public static List<SensorData> generateSensorData(List<LocationTime> locationTimes, List<Double> stdDeviations, double stepPerSecond) {
        List<SensorData> sensorDataList = new ArrayList<>();
        Random random = new Random();

        for (LocationTime locationTime : locationTimes) {
            double[] accelerometerReading = new double[3];
            for (int i = 0; i < 3; i++) {
                accelerometerReading[i] = random.nextGauss(0, stdDeviations.getii));
            }
            sensorDataList.add(new SensorData(locationTime.getTime(), "ACC", acceleratorReading));
            random.nextDouble(); // consume the next random number to ensure thread safety
        }

        double timeElapsed = 0;
        double currentTime = locationTimes.get(0).getTime();
        for (SensorData sensorData : sensorDataList) {
            sensorData.setTimestamp(currentTime + timeElapsed * 1000);
            timeElapsed += 1 / stepPerSecond;
            currentTime = sensorData.getTimestamp();
        }

        return sensorDataList;
    }
}

class LocationTime {
    private long time;

    public LocationTime(long time) {
        this.time = time;
    }

    public long getTime() {
        return time;
    }
