import java.io.InputStreamReader;
import java.regex.Pattern;
import java.util.concurrent.TimeUnit;

public class CommandPatternChecker {
    private static final String COMMAND;
    private static final String PATTERN_TO_FIND;
    private static final int SLEEP_TIME_MS;

    static {
        COMMAND = "your-command-here";
        PATTERN_TO_Find = "your-pattern-to-find";
        SLEEP_TIME_MS = 1000; // in milliseconds
    }

    public static boolean checkForPatternInCommandOutput() {
        Process process;
        try {
            process = Runtime.getRuntime().exec(COMMAND);
        } catch (Exception e) {
            System.err.println("Error executing command: " + e.getMessage());
            return false;
        }

        BufferedReader inputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        StringBuilder output = new StringBuilder();
        while ((line = inputReader.readLine()) != null) {
            output.append(line).append("\n");
        }
        inputReader.close();

        Pattern pattern = Pattern.compile(PATTERN_TO_FIND);
        Matcher matcher = pattern.matcher(output.toString());
        boolean patternFound = false;

        while (!patternFound) {
            patternFound = matcher.find();
            if (patternFound) {
                System.out.println("Pattern found in command output: " + output.toString());
                try {
                    TimeUnit.MILLISECONDS.sleep(SLEEP_TIME_MS);
                } catch (InterruptedException e) {
                    System.err.println("Interrupted while sleeping: " + e.getMessage());
                }
            }
        }

        return true;
    }
}
