public static URI downloadFileFromUrl(String urlString, String localFilePath, int timeoutMillis) {
    try {
        URL url = new URL(Objects.requireNonNull(urlString));
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.setConnectTimeout(timeoutMillis);
        connection.setRequestProperty("Accept", "application/octet-stream");

        int responseCode = connection.getResponseCode();
        if (responseCode >= HttpURLConnection.HTTP_OK && responseCode <= HttpURLConnection.HTTP_OK + 9) {
            InputStream inputStream = connection.getInputStream();
            try (FileOutputStream outputStream = new FileOutputStream(localFilePath)) {
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = inputStream.read(buffer)) != -1) {
                    outputStream.write(buffer, 0, bytesRead);
                }
            }
            return new File(localFilePath).toURI();
        } else {
            connection.disconnect();
            throw new RuntimeException("Failed to download file: HTTP error code " + responseCode);
        }
    } catch (IOException | NullPointerException e) {
        throw new RuntimeException("Failed to download file: " + e.getMessage(), e);
    }
}
