import java.io.*;
import java.util.*;

public class DataFilter {
    private static final String DATA_TYPE = "DEEPTILE";

    public static List<File> filterFiles(String directoryPath, String[] fileExtensions) throws IOException {
        List<File> filesToProcess = new ArrayList<>();
        File directory = new File(directoryPath);
        File[] files = directory.listFiles();

        if (files == null) {
            throw new FileNotFoundException("Directory not found: " + directoryPath);
        }

        for (File file : files) {
            if (file.isFile() && Arrays.asList(fileExtensions).contains(getExtension(file))) {
                filesToProcess.add(file);
            }
        }

        HashSet<Object> dataSet = new HashSet<>();
        List<File> outputFiles = new ArrayList<>();

        for (File file : filesToProcess) {
            try (FileInputStream inputStream = new FileInputStream(file);
                 ObjectInputStream objectInputStream = new ObjectInputStream(inputStream)) {

                Object data = objectInputStream.readObject();
                if (data != null && data.getClass().getName().equals(DATA_TYPE)) {
                    dataSet.add(data);
                    outputFiles.add(file);
                }
            } catch (ClassNotFoundException e) {
                // Ignore ClassNotFoundException, the file may contain unexpected data
            } catch (IOException e) {
                // Handle other I/O exceptions appropriately
            }
        }

        return outputFiles;
    }

    private static String getExtension(File file) {
        String fileName = file.getName();
        return fileName.substring(fileName.lastIndexOf(".") + 1);
    }
}
