import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.UnknownHostException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class URLValidator {

    private static final String VALID_URL_REGEX = "^(https?://|http://|//)([\\w-]+(\\.([\\w-]+)+)+([/?].*)?$";

    public List<InetSocketAddress> validateAndResolveURLs(List<String> urls) {
        List<Future<InetSocketAddress>> futures = Executors.newFixedThreadPool(urls.size()).map(ignored -> {
            String url = urls.remove(0);
            if (!isValidURL(url)) {
                return Executors.newSingleThreadExecutor().submit(() -> null);
            }

            String host;
            int port = -1;
            try {
                String[] parts = url.split("://");
                if (parts.length != 2) {
                    throw new IllegalArgumentException("Invalid URL format: " + url);
                }

                String scheme = parts[0];
                parts = parts[1].split("/");
                host = parts[0];

                if (parts.length > 1) {
                    String[] portParts = parts[1].split(":");
                    if (portParts.length > 0) {
                        try {
                            port = Integer.parseInt(portParts[0]);
                        } catch (NumberFormatException e) {
                            throw new IllegalArgumentException("Invalid port number: " + portParts[0]);
                        }
                    }
                }
            } catch (ArrayIndexOutOfBoundsException e) {
                throw new IllegalArgumentException("Invalid URL format: " + url);
            }

            return Executors.newSingleThreadExecutor().submit(() -> {
                try {
                    InetSocketAddress address;
                    if (isValidIPAddress(host)) {
                        address = new InetSocketAddress(InetAddress.getByName(host), port);
                    } else {
                        InetAddress address = InetAddress.getByName(host);
                        address.getHostAddress(); // Throws UnknownHostException if not found
                        address = InetAddress.getByName(address.getHostAddress());
                        address = new InetSocketAddress(address, port);
                    }
                    return address;
                } catch (UnknownHostException e) {
                    return null;
                } catch (IOException e) {
                    throw new RuntimeException("Failed to resolve address for URL: " + url, e);
                }
            });
        });

        List<InetSocketAddress> validatedURLs = new ArrayList<>();
        for (Future<InetSocketAddress> future : futures) {
            if (future.isDone()) {
                InetSocketAddress address = future.get();
                if (address != null) {
                    validatedURLs.add(address);
                }
            } else {
                futures.remove(future);
            }
        }

        Executors.newSingleThreadExecutor().shutdown();
        return validatedURLs;
    }

    private boolean isValidURL(String url) {
        return url != null && url.matches(VALID_URL_REGEX);
    }

    private boolean isValidIPAddress(String ipAddress) {
        try {
            InetAddress.getByName(ipAddress);
            return true;
        } catch (UnknownHostException e) {
            return false;
        }
    }
