import java.io.File;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public static String getFileSHA1Hash(File file) {
    try {
        MessageDigest md = MessageDigest.getInstance("SHA-1");
        byte[] fileData = new byte[(int) file.length()];
        FileInputStream inputStream = new FileInputStream(file);
        int bytesRead = 0;
        while (bytesRead < file.length()) {
            int numBytes = inputStream.read(fileData, bytesRead, file.length() - bytesRead);
            if (numBytes <= 0) {
                throw new IOException("Error reading file: " + file.getName());
            }
            bytesRead += numBytes;
        }
        inputStream.close();
        md.update(fileData);
        byte[] hash = md.digest();
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    } catch (NoSuchAlgorithmException | IOException e) {
        throw new RuntimeException("Error calculating SHA-1 hash: " + e.getMessage(), e);
    }
}
