public class SecureSocketConnector {
    public static NioSocketConnector createSecureSocketConnection(URI uri) {
        String host = uri.getHost();
        int port = uri.getPort();
        if (port <= 0) {
            port = ConfigUtil.getIntProperty("default.port", 80);
        }
