import java.io.File;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.SocketAddress;
import java.util.Properties;

public int bindSocketToPort(String propertiesFile) {
    int port = -1;
    Properties props = new Properties();

    try {
        File inputFile = new File(propertiesFile);
        if (inputFile.exists() && inputFile.isFile()) {
            props.load(new FileInputStream(inputFile));
            String portStr = props.getProperty("port");
            if (portStr != null) {
                port = Integer.parseInt(portStr);
            }
        }
    } catch (IOException e) {
        System.err.println("Error loading properties file: " + e.getMessage());
        return -1;
    }

    int socketDescriptor = -1;
    try {
        ServerSocket serverSocket = new ServerSocket();
        SocketAddress localSocketAddress = new InetSocketAddress(port);

        if (socketDescriptor < 0) {
            socketDescriptor = serverSocket.bind(localSocketAddress, 1);
            if (socketDescriptor < 0) {
                throw new RuntimeException("Failed to bind socket to port: " + port);
            }
        }

        serverSocket.close();
    } catch (IOException e) {
        if (socketDescriptor >= 0) {
            closeSocket(socketDescriptor);
        }
        throw new RuntimeException("Failed to bind socket to port: " + port, e);
    }

    return socketDescriptor;
}

private void closeSocket(int socketDescriptor) {
    try {
        if (socketDescriptor >= 0) {
            ServerSocket serverSocket = new ServerSocket();
            Socket socket = serverSocket.accept();
            socket.close();
            serverSocket.close();
            socketDescriptor = -1;
        }
    } catch (IOException e) {
        // Ignore
    }
}
