import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImageRotator {

    public static void main(String[] args) {
        if (args.length != 2) {
            System.out.println("Usage: java ImageRotator <imageFilePath> <angleOfRotation>");
            return;
        }

        String imageFilePath = args[0];
        int angleOfRotation = Integer.parseInt(args[1]);

        File inputFile = new File(imageFilePath);
        if (!inputFile.exists()) {
            System.out.println("Error: File not found: " + imageFilePath);
            return;
        }

        String outputFileName = "rotated_" + imageFilePath;
        ProcessBuilder pb = new ProcessBuilder("convert", imageFilePath, "-rotate", Integer.toString(angleOfRotation), outputFileName);
        Process process = null;

        try {
            process = pb.start();
            int exitValue = process.waitFor().exitValue();
            if (exitValue != 0) {
                System.out.println("Error: Image rotation failed with exit code: " + exitValue);
                return;
            }

            Path outputPath = Paths.get(outputFileName);
            byte[] bytes = Files.readAllBytes(outputPath);
            Files.delete(outputPath); // delete the temporary file

            for (byte b : bytes) {
                System.out.write(b);
            }
        } catch (IOException | InterruptedException e) {
            System.out.println("Error: " + e.getMessage());
        } finally {
            if (process != null) {
                process.destroy();
            }
        }
    }
}
