import java.nio.file.Paths;

public class DictionaryDownloader {

    private static final String TEMP_DIR = System.getProperty("java.io.tmpdir");

    public static void downloadAndReplaceDictionary(String url, String targetFile) throws IOException {
        // Validate URL and download file
        URL dictionaryUrl = new URL(url);
        HttpURLConnection connection = (HttpURLConnection) dictionaryUrl.openConnection();
        connection.setRequestMethod("GET");
        connection.setRequestProperty("User-Agent", "Mozilla/5.0");

        if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
            throw new IOException("Failed : HTTP error code : " + connection.getResponseCode());
        }

        Path tempFile = Files.createTempFile(TEMP_DIR, "dict");
        try (InputStream inputStream = connection.getInputStream()) {
            Files.copy(inputStream, tempFile);
        }

        // Replace existing file with downloaded contents
        Path existingFile = Paths.get(targetFile);
        if (Files.exists(existingFile)) {
            Files.delete(existingFile);
        }

        Files.copy(tempFile, Paths.get(targetFile));
        System.out.println("Dictionary replaced with the downloaded one.");

        // Delete temporary file
        Files.delete(tempFile);
    }
}
