import org.apache.commons.httpclient.HttpClient;
import org.apache.commons.httpclient.methods.PostMethod;
import org.apache.commons.httpclient.methods.RequestEntity;
import org.apache.commons.httpclient.params.HttpConnectionManagerParams;
import org.apache.commons.httpclient.params.HttpMethodParams;
import org.apache.commons.io.IOUtils;
import org.apache.commons.lang3.StringUtils;

public class SecurePostRequest {

    private static final String USER_AGENT = "SecurePostRequest/1.0";

    public static Response sendPostRequest(String endpoint, String requestBody, String token, int maxRate, long delay, int limit) throws Exception {
        HttpClient httpClient = new HttpClient();
        HttpConnectionManagerParams.setConnectionTimeout(httpClient.getParams(), 5000);
        HttpConnectionManagerParams.setSoTimeout(httpClient.getParams(), 5000);

        PostMethod postMethod = new PostMethod(endpoint);
        postMethod.setRequestHeader("Accept", "application/json");
        postMethod.setRequestHeader("User-Agent", USER_AGENT);
        postMethod.setRequestHeader("Authorization", "Bearer " + token);

        if (StringUtils.isNotBlank(requestBody) && "gzip".equalsIgnoreCase(getContentTypeFromRequestHeader(postMethod.getRequestHeaders()))) {
            requestBody = new String(IOUtils.toByteArray(new GZipInputStream(new ByteArrayInputStream(requestBody.getBytes()))), "UTF-8");
            postMethod.setRequestEntity(new ByteArrayRequestEntity(requestBody.getBytes()));
        } else {
            postMethod.setRequestEntity(new StringRequestEntity(requestBody, "application/json", "UTF-8"));
        }

        if (maxRate > 0) {
            RateLimiter rateLimiter = new RateLimiter(maxRate, delay);
            if (!rateLimiter.tryAcquire()) {
                throw new Exception("Rate limit exceeded");
            }
        }

        httpClient.executeMethod(postMethod);

        if (postMethod.getStatusCode() != 200) {
            throw new Exception("Request failed with status code: " + postMethod.getStatusCode());
        }

        return new Response(postMethod.getResponseBodyAsStream(), postMethod.getResponseHeaders());
    }

    private static String getContentTypeFromRequestHeader(Header[] headers) {
        for (Header header : headers) {
            if (header.getName().equalsIgnoreCase("Content-Type")) {
                return header.getValue();
            }
        }
        return null;
    }

    public static class Response {
        private final InputStream inputStream;
        private final Header[] headers;

        public Response(InputStream inputStream, Header[] headers) {
            this.inputStream = inputStream;
            this.headers = headers;
        }

        public InputStream getInputStream() {
            return inputStream;
        }

        public Header[] getHeaders() {
            return headers;
        }
    }
}
