import java.io.*;

public class CommandExecutor {

    public static int executeCommandAndReadErrorStream(String command) throws IOException {
        Process process = Runtime.getRuntime().exec(command);
        int exitValue = process.waitFor();

        InputStream errorStream = process.errorStream();
        byte[] errorBytes = new byte[4096]; // 4KB buffer
        int bytesRead;
        int totalBytesRead = 0;

        while ((bytesRead = errorStream.read(errorBytes)) != -1) {
            totalBytesRead += bytesRead;
        }

        errorStream.close();

        if (totalBytesRead > 4096) {
            throw new RuntimeException("Error stream size exceeded 4KB limit.");
        }

        return exitValue;
    }
}
