import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.net.Socket;
import java.util.concurrent.locks.ReentrantLock;

public class RemoteMethodCall {
    private static final String SERVER_ADDRESS = "localhost"; // Replace with the server address
    private static final int SERVER_PORT = 8080; // Replace with the server port

    public static Object callRemoteMethod(String methodName, Object[] parameters) {
        Object result = null;
        try (Socket socket = new Socket(SERVER_ADDRESS, SERVER_PORT)) {
            ReentrantLock lock = new ReentrantLock();

            try (ObjectOutputStream outputStream = new ObjectOutputStream(socket.getOutputStream());
                 ObjectInputStream inputStream = new ObjectInputStream(socket.getInputStream())) {

                lock.lock();
                try {
                    outputStream.writeObject(new Request(methodName, parameters));
                    result = inputStream.readObject();
                } catch (ClassNotFoundException e) {
                    throw new RuntimeException("Unknown class in the response", e);
                } finally {
                    lock.unlock();
                }
            }
        } catch (IOException e) {
            throw new RuntimeException("Failed to connect to the server", e);
        }

        return result;
    }

    static class Request implements Serializable {
        private static final long serialVersionUID = 1L;
        String methodName;
        Object[] parameters;

        public Request(String methodName, Object[] parameters) {
            this.methodName = methodName;
            this.parameters = parameters;
        }
    }
}
