import java.io.*;
import java.util.Objects;

public class ObjectSerializer {

    private static final ObjectStreamFactory objectStreamFactory = new DefaultStreamFactory();

    public static byte[] serialize(Object obj) throws IOException {
        ObjectOutputStream outputStream = null;
        try {
            outputStream = new ObjectOutputStream(new ByteArrayOutputStream());
            outputStream.writeObject(obj);
            return outputStream.toByteArray();
        } finally {
            if (outputStream != null) {
                try {
                    outputStream.close();
                } catch (IOException e) {
                    // Handle exception
                }
            }
        }
    }

    public static Object deserialize(byte[] byteArray) throws IOException, ClassNotFoundException {
        ObjectInputStream inputStream = null;
        try {
            inputStream = new ObjectInputStream(new ByteArrayInputStream(byteArray));
            return inputStream.readObject();
        } finally {
            if (inputStream != null) {
                try {
                    inputStream.close();
                } catch (IOException e) {
                    // Handle exception
                }
            }
        }
    }

    public static <T> T deserializeAndVerify(byte[] byteArray, Class<T> clazz) throws IOException, ClassNotFoundException {
        Object obj = deserialize(byteArray);
        if (clazz.isInstance(obj)) {
            return clazz.cast(obj);
        } else {
            throw new ClassCastException("Deserialized object is not of the expected type.");
        }
    }

    public static void main(String[] args) throws IOException, ClassNotFoundException {
        MyClass original = new MyClass("Original");
        byte[] byteArray = serialize(original);
        MyClass deserialized = deserializeAndVerify(byteArray, MyClass.class);
        Objects.equals(original, deserialized);
    }
}

class MyClass implements Serializable {
    private String name;

