import org.apache.commons.compress.compressors.lzma.LZMACompressor;
import org.apache.commons.compress.compressors.lzma.LZMACompressorOutputStream;
import org.apache.commons.codec.digest.Md5Crypt;

import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.MessageDigest;

public static byte[] compressAndGetMd5Hash(String filePath, int compressionLevel) throws IOException {
    Path file = Paths.get(filePath);
    byte[] inputBytes = Files.readAllBytes(file);

    try (FileOutputStream outputStream = new FileOutputStream(filePath + ".lzo")) {
        LZMACompressor compressor = new LZMACompressor(compressionLevel);
        LZMACompressorOutputStream output = new LZMACompressorOutputStream(outputStream, compressor);
        output.write(inputBytes, 0, inputBytes.length);
        output.finish();

        byte[] compressedBytes = outputStream.getChannel().map(FileChannel.MapMode.READ_ONLY, 0, outputStream.size()).array();

        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(compressedBytes);
        byte[] md5Hash = md.digest();

        // Delete the compressed file
        Files.delete(Paths.get(filePath + ".lzo"));

        return md5Hash;
    }
}
