import java.io.BufferedInputStream;
import java.io.FileInputStream;
import java.io.IOException;
import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public static BigInteger calculateMD5Checksum(String filePath, FileReadType readType) throws FileNotFoundException, IOException, NoSuchAlgorithmException {
    FileInputStream fileInputStream;
    BufferedInputStream bufferedInputStream;
    byte[] fileContent;
    MessageDigest md;

    switch (readType) {
        case FULL:
            fileInputStream = new FileInputStream(filePath);
            break;
        case CHUNKED:
            fileInputStream = new FileInputStream(filePath);
            bufferedInputStream = new BufferedInputStream(fileInputStream);
            int bufferSize = 1024;
            byte[] buffer = new byte[bufferSize];
            int bytesRead;
            fileContent = new byte[((int) new File(filePath).length() / bufferSize) * bufferSize];
            int index = 0;
            while ((bytesRead = bufferedInputStream.read(buffer)) != -1) {
                System.arraycopy(buffer, 0, fileContent, index, bytesRead);
                index += bytesRead;
            }
            bufferedInputStream.close();
            fileInputStream.close();
            fileContent = new byte[fileContent.length];
            System.arraycopy(fileContent, 0, fileContent, 0, fileContent.length);
            break;
        default:
            throw new IllegalArgumentException("Invalid read type.");
    }

    md = MessageDigest.getInstance("MD5");
    md.update(fileContent);
    byte[] digest = md.digest();
    BigInteger checksum = new BigInteger(1, digest);

    fileInputStream.close();

    return checksum;
}

enum FileReadType {
    FULL,
    CHUNKED
}
