        } catch (InstantiationException | IllegalAccessException e) {
            throw new IOException("Error instantiating or accessing class: " + e.getMessage());
        } catch (NoSuchMethodException e) {
            throw new IOException("Method not found: " + methodName + " in class: " + className);
        } catch (InvocationTargetException e) {
            throw new IOException("Error invoking method: " + e.getCause().getMessage());
        }

        // Write the result back to the client
        PrintWriter output = new PrintWriter(new BufferedWriter(new OutputStreamWriter(socket.getOutputStream())), true);
        output.println(result.toString());
        output.flush();

        // Close the resources
        input.close();
        output.close();
        socket.close();
    } catch (IOException | ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
        // Log the error and close the socket
        System.err.println("Error handling client: " + e.getMessage());
        try {
            socket.close();
        } catch (IOException ex) {
            // Ignore any error closing the socket
        }
    }
}
