import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.lang.reflect.InvocationTargetException;
import java.util.List;
import java.util.concurrent.TimeUnit;

public boolean executeProcess(String command, List<String> args) {
    boolean success = false;

    try {
        String[] cmdArray = new String[args.size() + 1];
        System.arraycopy(args.toArray(new String[0]), 0, cmdArray, 0, args.size());
        cmdArray[args.size()] = command;

        Process process = Runtime.getRuntime().exec(cmdArray);
        if (process.exitValue() != 0) {
            logger.error("Process '{}' failed to start with exit code: {}", command, process.exitValue());
            return false;
        }

        logger.info("Started process '{}' with command: {}", command, String.join(" ", cmdArray));

        new Thread(() -> {
            try {
                BufferedReader input = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String line;
                while ((line = input.readLine()) != null) {
                    logger.debug("Process [OUTPUT]: '{}'", line);
                }
            } catch (IOException e) {
                logger.error("Error reading process output: {}", e.getMessage());
            }
        }).start();

        new Thread(() -> {
            try {
                BufferedReader error = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                String line;
                while ((line = error.readLine()) != null) {
                    logger.debug("Process [ERROR]: '{}'", line);
                }
            } catch (IOException e) {
                logger.error("Error reading process error: {}", e.getMessage());
            }
        }).start();

        process.waitFor(5, TimeUnit.SECONDS);
        if (!process.isAlive()) {
            logger.info("Process '{}' terminated", command);
            success = true;
        } else {
            logger.error("Process '{}' did not terminate within the allotted time", command);
            process.destroy();
        }
    } catch (IOException | NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
        logger.error("Error starting process '{}': {}", command, e.getMessage());
    }

    return success;
}
