public Map<String, byte[]> mergeMapsFromStream(Map<String, String> map, InputStream inputStream) {
    Map<String, byte[]> binaryMap = new HashMap<>();
    try {
        // Deserialize binary data stream into a map of string keys to byte values
        ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = inputStream.read(buffer, 0, buffer.length)) != -1) {
            byteStream.write(buffer, 0, bytesRead);
        }
        byteStream.flush();
        byte[] binaryData = byteStream.toByteArray();
        InputStream binaryInputStream = new ByteArrayInputStream(binaryData);
        String key;
        int length;
        byte[] value = new byte[1024];
        Map<String, byte[]> tempMap = new HashMap<>();
        while ((key = readStringFromStream(binaryInputStream)) != null) {
            length = readIntFromStream(binaryInputStream);
            if (length > value.length) {
                value = new byte[length];
            }
            System.arraycopy(readBytesFromStream(binaryInputStream, value.length), 0, value, 0, length);
            tempMap.put(key, value);
        }
        binaryMap = tempMap;
        binaryInputStream.close();
    } catch (IOException e) {
        e.printStackTrace();
    }

    // Merge the two maps
    for (Map.Entry<String, String> entry : map.entrySet()) {
        byte[] value = entry.getValue().getBytes();
        binaryMap.put(entry.getKey(), value);
    }

    return binaryMap;
}

private String readStringFromStream(InputStream inputStream) throws IOException {
    byte[] bytes = new byte[1024];
    int index = 0;
    int c;
    while ((c = inputStream.read()) != -1) {
        bytes[index++] = (byte) c;
        if (c == '\0') {
            return new String(bytes, 0, index - 1);
        }
    }
    throw new IOException("Unexpected end of stream");
}

private int readIntFromStream(InputStream inputStream) throws IOException {
    byte[] bytes = new byte[4];
    int index = 0;
    int value = 0;
    while (index < 4) {
        bytes[index++] = (byte) inputStream.read();
        value |= (bytes[index - 1] & 0xff) << (8 * (3 - index));
    }
    return value;
}

private byte[] readBytesFromStream(InputStream inputStream, int length) throws IOException {
    byte[] bytes = new byte[length];
    inputStream.read(bytes);
    return bytes;
}
