import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import java.security.SecureRandom;

public static SecretKey generateDESKey(String seed) {
    if (seed == null || seed.isEmpty()) {
        throw new IllegalArgumentException("Seed cannot be null or empty.");
    }

    byte[] seedBytes = seed.getBytes();
    SecretKey key;

    try {
        KeyGenerator keyGen = KeyGenerator.getInstance("DES");
        keyGen.init(new SecureRandom());
        key = keyGen.generateKey();

        // Overwrite the generated key with the seed
        byte[] keyBytes = key.getEncoded();
        System.arraycopy(seedBytes, 0, keyBytes, 0, Math.min(seedBytes.length, keyBytes.length));

    } catch (Exception e) {
        throw new RuntimeException("Failed to generate DES key.", e);
    }

    return key;
}
```

This method checks if the seed is null or empty before generating the key, and if it is, it throws an IllegalArgumentException. It then generates a DES key using a KeyGenerator, initializes it with a SecureRandom, and overwrites the generated key with the seed using System.arraycopy(). This ensures that the seed is used to initialize the key and avoids potential vulnerabilities.

