public static WalkMap createWalkMap(String filePath) {
    Path file = Paths.get(filePath);
    if (!Files.exists(file)) {
         System.err.println("File not found: " + filePath);
         return null;
     }

     String fileName = file.getFileName().toString();
     String extension = "";
