import javax.net.ssl.HttpsURLConnection;
import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;

public class SecureHttpsClient {

    private static final String APPLICATION_JSON = "application/json";

    public static HttpURLConnection establishSecureConnection(String hostname, int port) throws IOException {
        try {
            SSLContext sslContext = SSLContext.getInstance("TLSv1.2");
            sslContext.init(null, new TrustAllX509TrustManager(), null);

            URL url = new URL("https", hostname, port);
            HttpsURLConnection httpsConnection = (HttpsURLConnection) url.openConnection();
            httpsConnection.setSSLSocketFactory(sslContext.getSocketFactory());

            httpsConnection.setRequestMethod("POST");
            httpsConnection.setRequestProperty("Content-Type", APPLICATION_JSON);
            httpsConnection.setDoOutput(true);

            ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
            OutputStream os = httpsConnection.getOutputStream();
            os.write(outputStream.toByteArray());
            os.flush();

            int responseCode = httpsConnection.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                throw new IOException("Unexpected response code: " + responseCode);
            }

            return httpsConnection;

        } catch (NoSuchAlgorithmException | KeyManagementException | GeneralSecurityException e) {
            throw new RuntimeException("Failed to establish secure connection", e);
        }
    }

    private static class TrustAllX509TrustManager implements X509TrustManager {
        @Override
