public static byte[] sha1Hash(String moduleName, boolean createSymlinks, boolean createHeaderMap, Map<String, String> paths) {
    StringBuilder configNameBuilder = new StringBuilder();
    if (createHeaderMap) {
        configNameBuilder.append("header_map_");
    }
    configNameBuilder.append(moduleName);

    Path configPath;
    try {
        configPath = Paths.get(paths.get(configNameBuilder.toString()));
