    try {
        sha1 = MessageDigest.getInstance("SHA-1");
    } catch (NoSuchAlgorithmException e) {
        throw new RuntimeException("SHA-1 algorithm not supported", e);
    }

    String linkedPath = paths.getOrDefault(configNameBuilder.toString(), configPath.toString());

    if (!createSymlinks && !Files.isRegularFile(Paths.get(linkedPath))) {
        throw new IllegalArgumentException("Linked path for given module name does not exist: " + moduleName);
    }

    try {
        Path filePath = Paths.get(linkedPath);
        byte[] fileContent = Files.readAllBytes(filePath);

        String headerMapKey = createHeaderMap ? configNameBuilder.toString() : "";
