import com.google.gson.Gson;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class UserDataSender {
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private static final OkHttpClient client = new OkHttpClient();

    public static void sendUserDataToServer(String serverUrl, Map<String, String> userData) throws IOException {
        Gson gson = new Gson();
        String jsonData = gson.toJson(userData);

        RequestBody body = RequestBody.create(JSON, jsonData);
        Request request = new Request.Builder()
                .url(serverUrl)
                .post(body)
                .build();

        try (Response response = client.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                throw new IOException("Unexpected code " + response);
            }
        }
    }

    public static void main(String[] args) {
        Map<String, String> userData = new HashMap<>();
        userData.put("key1", "value1");
        userData.put("key2", "value2");

        try {
            String serverUrl = "https://example.com/api/userData";
            sendUserDataToServer(serverUrl, userData);
            System.out.println("User data sent to server.");
        } catch (IOException e) {
            System.err.println("Error sending user data to server: " + e.getMessage());
        }
    }
}
```

