public String encryptBlowfish(String input) {
    if (input == null || input.isEmpty()) {
        throw new IllegalArgumentException("Input cannot be empty or null.");
    }

    String algorithm = "Blowfish";
    int keyLength = 8 * 6; // 64-bit key
