import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.Optional;
import java.util.concurrent.TimeUnit;

public int executeCommand(String[] commands, InputStream input, OutputStream output, Optional<Long> timeout) {
    ProcessBuilder processBuilder = new ProcessBuilder();
    Process process;
    try {
        processBuilder.command(commands);
        process = processBuilder.start();

        if (input != null) {
            InputStream processInput = process.getInputStream();
            BufferedInputStream bufferedInput = new BufferedInputStream(processInput);
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = bufferedInput.read(buffer, 0, buffer.length)) > 0) {
                input.write(buffer, 0, bytesRead);
            }
            bufferedInput.close();
        }

        if (output != null) {
            OutputStream processOutput = process.getOutputStream();
            BufferedOutputStream bufferedOutput = new BufferedOutputStream(processOutput);
            String commandInput = String.join(" ", commands);
            bufferedOutput.write(commandInput.getBytes());
            bufferedOutput.flush();
            bufferedOutput.close();
        }

        boolean exitValue = false;
        if (timeout.isPresent()) {
            exitValue = process.waitFor(timeout.get(), TimeUnit.MILLISECONDS);
        } else {
            exitValue = process.waitFor();
        }

        if (!exitValue) {
            process.destroy();
            throw new RuntimeException("Command execution timed out");
        }

        return process.exitValue();
    } catch (IOException | InterruptedException e) {
        process.destroy();
        throw new RuntimeException("An error occurred while executing the command", e);
    }
}
