public class NFA {
    private int windowLength;
    private int[][] transitions;
    private int initialState;
    private int[] acceptingStates;

    public NFA(int windowLength) {
        this.windowLength = windowLength;
        this.transitions = new int[256][windowLength];
        this.initialState = 0;
        this.acceptingStates = new int[2];
        this.acceptingStates[0] = windowLength - 1;
        this.acceptingStates[1] = windowLength;
    }

    public void setTransition(int input, int from, int to) {
        transitions[input][from] = to;
    }

    private void writeObject(ObjectOutputStream out) throws IOException {
        out.writeInt(windowLength);
        out.writeInt(initialState);
        out.writeInt(acceptingStates.length);
        for (int i = 0; i < acceptingStates.length; i++) {
            out.writeInt(acceptingStates[i]);
        }
        for (int i = 0; i < 256; i++) {
            for (int j = 0; j < windowLength; j++) {
                out.writeInt(transitions[i][j]);
            }
        }
    }

    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
        windowLength = in.readInt();
        initialState = in.readInt();
        int numAcceptingStates = in.readInt();
        acceptingStates = new int[numAcceptingStates];
        for (int i = 0; i < numAcceptingStates; i++) {
            acceptingStates[i] = in.readInt();
        }
        transitions = new int[256][windowLength];
        for (int i = 0; i < 256; i++) {
            for (int j = 0; j < windowLength; j++) {
                transitions[i][j] = in.readInt();
            }
        }
    }

