public class KeyboardEventSimulator {

    private static final String XDOTOOL_EXECUTABLE = "xdg-open"; // Replace with the path to xdotool executable

    public static void simulateKeyboardEvents(int[] keys) throws Exception {
        if (keys == null || keys.length <= 0) {
            throw new IllegalArgumentException("Invalid key array");
        }

        ProcessBuilder pb = new ProcessBuilder(XDOTOOL_EXECUTABLE, "--key-file");
        pb.redirectErrorStream(true);

        Process process = pb.start();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
