                if (key < 0 || key > 255) {
                    throw new IllegalArgumentException("Invalid key code: " + key);
                }

                String command = String.format("key %d type key_down%nkey %d type key_up%n", key, key);
                process.getOutputStream().write(command.getBytes());
                process.getOutputStream().flush();

                String line;
                while ((line = reader.readLine()) != null) {
                    if (line.contains("error")) {
                        throw new RuntimeException("Error occurred while simulating keyboard events: " + line);
                    }
                }
            }
        } finally {
            process.destroy();
        }
    }

    public static void main(String[] args) {
        try {
