public class DeviceTreeCompiler {

    private static final String DT_COMPILER = "dtc";

    public static void compileOverlay(String objectFilePath, String overlayFilePath) throws CompilationException {
        Path objectFile = Paths.get(objectFilePath);
        Path overlayFile = Paths.get(overlayFilePath);

        if (!Files.exists(objectFile) || !Files.isRegularFile(objectFile)) {
            throw new CompilationException("Object file does not exist or is not a regular file: " + objectFilePath);
        }

        if (!Files.exists(overlayFile) || !Files.isRegularFile(overlayFile)) {
            throw new CompilationException("Overlay file does not exist or is not a regular file: " + overlayFilePath);
        }

        ProcessBuilder processBuilder = new ProcessBuilder(DT_COMPILER, objectFilePath.toString(), overlayFilePath.toString());
        Map<String, String> environment = new HashMap<>();
        processBuilder.inheritIO();
        processBuilder.environment().putAll(environment);

        try {
            Process process = processBuilder.start();
            int exitValue = process.waitFor().exitValue();

            if (exitValue != 0) {
                throw new CompilationException("Compilation failed with exit code: " + exitValue);
            }
        } catch (InterruptedException e) {
            throw new CompilationException("Compilation was interrupted", e);
        } catch (IOException e) {
            throw new CompilationException("Error starting compilation process", e);
        }
    }

    public static class CompilationException extends IOException {
        public CompilationException(String message) {
            super(message);
        }

        public CompilationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
