        char[] ignoredControls = {'\t', '\n', '\r'};

        for (char c : validLetters) {
            assertTrue(Character.isJavaIdentifierStart(c));
            assertTrue(Character.isJavaIdentifierPart(c));
            assertTrue(Character.isJavaLetter(c));
        }

        for (char c : validDigits) {
            assertTrue(Character.isDigit(c));
            assertFalse(Character.isJavaLetter(c));
        }

