            assertTrue(Character.isJavaIdentifierStart(c));
            assertTrue(Character.isJavaIdentifierPart(c));
            assertTrue(Character.isJavaLetterOrDigit(c));
            assertTrue(Character.isJavaLetter(c) || Character.isDigit(c));
        }

