            assertTrue(Character.isJavaIdentifierPart(c));
            assertFalse(Character.isJavaLetter(c));
        }

        for (char c : ignoredControls) {
            assertFalse(Character.isJavaIdentifierStart(c));
            assertFalse(Character.isJavaIdentifierPart(c));
            assertFalse(Character.isJavaLetter(c));
        }

