import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.Base64;

public String encryptMessage(String message, String encodingScheme, boolean toUppercase) {
    if (message == null || message.isEmpty()) {
        throw new IllegalArgumentException("Message cannot be empty or null.");
    }

    if (!isValidEncodingScheme(encodingScheme)) {
        throw new IllegalArgumentException("Invalid encoding scheme: " + encodingScheme);
    }

    message = toUppercase ? message.toUpperCase() : message;

    try {
        SecretKeySpec secretKey = new SecretKeySpec("secretKey".getBytes(), "HmacMD5");
        Mac mac = Mac.getInstance("HmacMD5");
        mac.init(secretKey);

        byte[] rawHmac = mac.doFinal(message.getBytes());
        String encryptedMessage = Base64.getEncoder().encodeToString(rawHmac);

        return encryptedMessage;
    } catch (NoSuchAlgorithmException | InvalidKeyException e) {
        throw new RuntimeException("Error encrypting message: " + e.getMessage(), e);
    }
}

private boolean isValidEncodingScheme(String encodingScheme) {
    return "MD5".equalsIgnoreCase(encodingScheme);
}
