import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.stream.Collectors;

public class QueryGenerator {

    private static final String TOOL_PATH = "/path/to/external/tool";

    public String generateQueries(String templatePath, List<String> queryParams) {
        StringBuilder outputBuilder = new StringBuilder();

        try {
            ProcessBuilder processBuilder = new ProcessBuilder(TOOL_PATH, templatePath);
            processBuilder.redirectErrorStream(true);

            Process process = processBuilder.start();

            // Send query parameters to the tool as command line arguments
            for (String param : queryParams) {
                process.getOutputStream().write(param.getBytes(StandardCharsets.UTF_8));
                process.getOutputStream().write(System.lineSeparator().getBytes(StandardCharsets.UTF_8));
            }

            process.getOutputStream().flush();
            process.getOutputStream().close();

            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    outputBuilder.append(line).append(System.lineSeparator());
                }
            }

            process.waitFor();

            if (!process.exitValueEquals(0)) {
                throw new RuntimeException("External tool returned non-zero exit value: " + process.exitValue());
            }

        } catch (Exception e) {
            throw new RuntimeException("An error occurred while executing the external tool: " + e.getMessage(), e);
        }

        return outputBuilder.toString();
    }
}
