import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5Filter implements FilterInterface {

    private int frequency;
    private byte[] inputData;

    public MD5Filter(int frequency) {
        this.frequency = frequency;
    }

    public byte[] filter(byte[] input) {
        inputData = input;
        byte[] md5Hash = calculateMD5(input);
        int count = getMD5HashCount(md5Hash);

        if (count <= frequency) {
            return md5Hash;
        } else {
            throw new FilterException("Input data frequency exceeds limit");
        }
    }

    private byte[] calculateMD5(byte[] input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            md.update(input);
            byte[] hash = md.digest();
            return hash;
        } catch (NoSuchAlgorithmException e) {
            throw new FilterException("MD5 algorithm not supported");
        }
    }

    private int getMD5HashCount(byte[] md5Hash) {
        byte[] hashAsInts = new byte[16];
        System.arraycopy(md5Hash, 0, hashAsInts, 0, 16);

        BigInteger total = new BigInteger(1).pow(32);
        BigInteger hashAsBigInteger = new BigInteger(1).byteArrayToBigInteger(hashAsInts);

        return hashAsBigInteger.intValue();
    }

    static class FilterException extends Exception {
        public FilterException(String message) {
            super(message);
        }
    }
}

interface FilterInterface {
    byte[] filter(byte[] input);
}
