import java.io.File;
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;

public int uploadFile(String serverUrl, String filePath, String fileName) {
    int responseCode;
    int maxRetries = 3;
    for (int i = 0; i < maxRetries; i++) {
        File fileToUpload = new File(filePath);
        if (!fileToUpload.exists()) {
            System.err.println("File not found: " + filePath);
            return HttpURLConnection.HTTP_NOT_FOUND;
        }

        URL url = new URL(serverUrl + "/upload");
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("POST");
        connection.setRequestProperty("Content-Type", "application/octet-stream");
        connection.setDoOutput(true);

        FileInputStream inputStream = new FileInputStream(fileToUpload);
        byte[] buffer = new byte[1024];
        int bytesRead;
        long totalBytesRead = 0;
        while ((bytesRead = inputStream.read(buffer, 0, buffer.length)) != -1) {
            connection.getOutputStream().write(buffer, 0, bytesRead);
            totalBytesRead += bytesRead;
        }
        inputStream.close();

        responseCode = connection.getResponseCode();
        if (HttpURLConnection.HTTP_OK == responseCode) {
            System.out.println("File uploaded successfully.");
            return responseCode;
        } else {
            System.err.println("File upload failed with status code: " + responseCode);
            connection.disconnect();
            try {
                Thread.sleep(1000 * (i + 1));
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }

    System.err.println("Max retries reached. File upload failed.");
    return HttpURLConnection.HTTP_INTERNAL_ERROR;
}
