import org.apache.http.HttpHost;
import org.apache.http.auth.AuthScope;
import org.apache.http.auth.BasicCredentialsProvider;
import org.apache.http.client.CredentialsProvider;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.client.registry.Registry;
import org.apache.http.client.registry.RegistryBuilder;
import org.apache.http.conn.socket.ConnectionSocketFactory;
import org.apache.http.conn.socket.PlainConnectionSocketFactory;
import org.apache.http.conn.socket.SSLConnectionSocketFactory;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

public class SecureHttpClientExample {

    public static String makeGetRequest(String url, String username, String password, String proxyHost, int proxyPort) throws Exception {
        // Create a registry for socket factories
        Registry registry = RegistryBuilder.create().register("http", PlainConnectionSocketFactory.getSocketFactory())
                .register("https", SSLConnectionSocketFactory.getSocketFactory()).build();

        // Create a custom RequestConfig with proxy settings
        RequestConfig requestConfig = RequestConfig.custom()
                .setProxy(new HttpHost(proxyHost, proxyPort))
                .build();

        // Create a credentials provider with username and password
        CredentialsProvider credentialsProvider = new BasicCredentialsProvider();
        credentialsProvider.setCredentials(AuthScope.ANY, new UsernamePasswordCredentials(username, password));

        // Create an HttpClientBuilder and set the registry and credentials provider
        CloseableHttpClient httpClient = HttpClients.custom()
                .setRegistry(registry)
                .setDefaultRequestConfig(requestConfig)
                .setDefaultCredentialsProvider(credentialsProvider)
                .build();

        // Create a GET request
        HttpGet httpGet = new HttpGet(url);

        // Execute the GET request and retrieve the response entity
        CloseableHttpResponse response = httpClient.execute(httpGet);

        // Convert the response entity to a string
        String responseString = EntityUtils.toString(response.getEntity());

        // Close the response and the client
        EntityUtils.consume(response.getEntity());
        httpClient.close();

        return responseString;
    }
}
