import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

public static Process executeCommand(String command) throws IOException {
    if (command == null || command.isEmpty()) {
        throw new IllegalArgumentException("Command cannot be null or empty.");
    }

    String osName = System.getProperty("os.name").toLowerCase();
    boolean isWindows = osName.startsWith("windows");

    String[] cmdArray;
    if (isWindows && command.endsWith(".bat") || command.endsWith(".cmd")) {
        cmdArray = new String[]{"cmd.exe", "/c", command};
    } else {
        cmdArray = new String[]{null, command};
    }

    Process process = Runtime.getRuntime().exec(cmdArray);

    InputStream inputStream = process.getErrorStream();
    InputStreamReader inputStreamReader = new InputStreamReader(inputStream, StandardCharsets.UTF_8);
    BufferedReader bufferedReader = new BufferedReader(inputStreamReader);

    String errorLine;
    StringBuilder errorOutput = new StringBuilder();
    while ((errorLine = bufferedReader.readLine()) != null) {
        errorOutput.append(errorLine).append("\n");
    }

    inputStream.close();
    bufferedReader.close();

    if (!errorOutput.isEmpty()) {
        throw new IOException("Error executing command:\n" + errorOutput.toString());
    }

    InputStream inputStream = process.getInputStream();
    InputStreamReader inputStreamReader = new InputStreamReader(inputStream, StandardCharsets.UTF_8);
    BufferedReader bufferedReader = new BufferedReader(inputStreamReader);

    String outputLine;
    StringBuilder outputOutput = new StringBuilder();
    while ((outputLine = bufferedReader.readLine()) != null) {
        outputOutput.append(outputLine).append("\n");
    }

    inputStream.close();
    bufferedReader.close();

    process.waitFor();

    return process;
}
