```java
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public static String generateRandomString(double seed) {
    byte[] keyBytes = new byte[16]; // 128-bit key
    byte[] seedBytes = new byte[8]; // 64-bit seed
    byte[] input = new byte[8];

    // Convert seed to byte array
    long seedLong = Double.doubleToLongBits(seed);
    for (int i = 0; i < 8; i++) {
        input[i] = (byte) ((seedLong >> (8 * i)) & 0xFF);
    }

    // Initialize HMAC-SHA256 key
    SecretKeySpec secretKey = new SecretKeySpec("JAVA_SECRET_KEY".getBytes(), "HmacSHA256");
    Mac sha25Hmac;
    try {
        sha25Hmac = Mac.getInstance("HmacSHA256");
        sha25Hmac.init(secretKey);
    } catch (NoSuchAlgorithmException | InvalidKeyException e) {
        throw new RuntimeException("Error initializing HMAC-SHA256", e);
    }

    // Generate hash value
    byte[] hash = new byte[32];
    sha25Hmac.update(input);
    sha25Hmac.doFinal(hash);

    // Format hash value as 32-digit hexadecimal number
    StringBuilder hexString = new StringBuilder(64);
    for (byte b : hash) {
        hexString.append(String.format("%02x", b));
    }

    // Return hash value
    return hexString.toString();
}
