import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.net.InetAddress;

public static long generateNodeId() {
    try {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] hostAddressBytes = InetAddress.getLocalHost().getAddress();
        byte[] input = new byte[16 + hostAddressBytes.length]; // 16 bytes for SHA-256 prefix
        System.arraycopy(hostAddressBytes, 0, input, 16, hostAddressBytes.length);
        md.update(input);
        byte[] hash = md.digest();

        // Ignore the upper 8 bits of the hash
        BigInteger hashBigInt = new BigInteger(1, hash);
        hashBigInt = hashBigInt.shiftRight(8);

        // Set the upper 8 bits to 0
        hashBigInt = hashBigInt.or(BigInteger.valueOf(0xFF00_0000_0000L));

        return hashBigInt.longValue();
    } catch (NoSuchAlgorithmException | UnknownHostException e) {
        throw new RuntimeException("Failed to generate node ID", e);
    }
}
