```java
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.math.BigInteger;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.spec.KeySpec;
import java.util.Arrays;

public byte[] generateMask(int maskLength, byte[] seed) {
    final String ALGORITHM = "HmacSHA256"; // Use a secure digest algorithm

    try {
        SecretKeySpec secretKey = new SecretKeySpec(seed, ALGORITHM);
        Mac mac = Mac.getInstance(ALGORITHM);
        mac.init(secretKey);

        byte[] output = new byte[maskLength];
        byte[] block = new byte[1024]; // Reasonable block size

        int processedBytes = 0;
        int totalBytesToProcess = seed.length;

        while (processedBytes < totalBytesToProcess) {
            int dataLength = Math.min(block.length, totalBytesToProcess - processedBytes);
            Arrays.fill(block, 0, dataLength, (byte) 0x3b); // Set a constant byte for MGF1
            System.arraycopy(seed, processedBytes, block, 0, dataLength);

            mac.update(block);
            mac.doFinal(output, 0, output.length);

            processedBytes += dataLength;
            totalBytesToProcess -= dataLength;
        }

        return Arrays.copyOfRange(output, 0, maskLength);

    } catch (NoSuchAlgorithmException | InvalidKeyException e) {
        throw new RuntimeException("Error during mask generation", e);
    }
}

// Helper method to convert an integer to a BigInteger
private BigInteger util_conv_big(int i) {
    return BigInteger.valueOf(i);
}
