```javascript
const fs = require('fs');
const path = require('path');
const stylus = require('stylus');

function generateCSSFile(inputPath, outputPath) {
  return new Promise((resolve, reject) => {
    // Validate input path
    if (!path.isAbsolute(inputPath)) {
      return reject(new Error('Invalid input path.'));
    }

    // Validate output path
    const outputDir = path.dirname(outputPath);
    if (!fs.existsSync(outputDir)) {
      return fs.promises.mkdir(outputDir, { recursive: true })
        .then(() => generateCSSFile(inputPath, outputPath))
        .catch((err) => reject(err));
    }

    // Read Stylus files
    const files = [];
    function readFileRecursively(dir) {
      return fs.promises.readdir(dir)
        .then((files) => Promise.all(files.map((file) => {
          const filePath = path.join(dir, file);
          if (fs.statSync(filePath).isDirectory()) {
            return readFileRecursively(filePath);
          }
          if (path.extname(filePath) === '.styl') {
            files.push(filePath);
          }
          return Promise.resolve();
        })))
        .then(() => files);
    }

    readFileRecursively(path.dirname(inputPath))
      .then((files) => {
        // Concatenate and process Stylus files
        const input = fs.readFileSync(inputPath, 'utf-8');
        const stylusInput = new stylus.Source(input, { filename: inputPath });
        const result = {};

        files.forEach((file) => {
          const stylusFile = new stylus.Source(fs.readFileSync(file, 'utf-8'), { filename: file });
          stylus.render(stylusFile, (err, css) => {
            if (err) {
              return reject(err);
            }
            result = stylus.render(input, {
              source: stylusInput,
              globals: { css },
            });
          });
        });

        // Save CSS file
        const cssContent = result.css.toString();
        fs.promises.writeFile(outputPath, cssContent)
          .then(() => resolve())
          .catch((err) => reject(err));
      })
      .catch((err) => reject(err));
  });
}

// Usage example
generateCSSFile('path/to/input.styl', 'path/to/output.css')
  .then(() => console.log('CSS file generated successfully.'))
  .catch((err) => console.error('Error generating CSS file:', err.message));
