```javascript
const fs = require('fs-extra');
const less = require('less');
const path = require('path');

async function compileLessFiles(dirPath) {
  try {
    const files = await fs.readdir(dirPath);

    const compiledFiles = {};

    for (const file of files) {
      const filePath = path.join(dirPath, file);
      const stats = await fs.stat(filePath);

      if (stats.isDirectory()) continue;

      if (path.extname(filePath) === '.less') {
        const output = await new Promise((resolve, reject) => {
          less.renderFile(filePath, (err, css) => {
            if (err) return reject(err);
            resolve(css.toString());
          });
        });

        compiledFiles[filePath] = output;
      }

      if (stats.isFile()) {
        const nextFile = await compileLessFiles(filePath);
        Object.assign(compiledFiles, nextFile);
      }
    }

    return compiledFiles;
  } catch (error) {
    console.error('Error during Less file compilation:', error);
    throw error;
  }
}

module.exports = compileLessFiles;
```

