const fs = require('fs');
const path = require('path');

function checkFileExistsInDirectoryTree(dirPath, fileNames) {
  return new Promise((resolve, reject) => {
    fs.stat(dirPath, (err, stat) => {
      if (err) {
        if (err.code === 'ENOENT') {
          // Directory does not exist, return false
          resolve(false);
        } else {
          // Other error, reject the promise
          reject(err);
        }
      } else {
        if (stat.isDirectory()) {
          // Directory, traverse it recursively
          fs.readdir(dirPath, (err, files) => {
            if (err) {
              reject(err);
            } else {
              let filesToCheck = fileNames.map(fileName => path.join(dirPath, fileName));
              let promises = filesToCheck.map(filePath =>
                new Promise((resolve, reject) => {
                  fs.stat(filePath, (err, stat) => {
                    if (err) {
                      resolve(false);
                    } else if (stat.isFile()) {
                      resolve(true);
                    } else {
                      resolve(checkFileExistsInDirectoryTree(filePath, fileNames));
                    }
                  });
                })
              );
              Promise.all(promises).then(results => {
                let allFilesFound = results.every(result => result);
                if (allFilesFound) {
                  // All files found, resolve the promise with true
                  resolve(true);
                } else {
                  // Some files not found, resolve the promise with false
                  resolve(false);
                }
              }).catch(err => reject(err));
            }
          });
        } else {
          // File or other non-directory, check if it's one of the files to look for
          let fileFound = fileNames.some(fileName => path.basename(dirPath) === fileName);
          if (fileFound) {
            // File found, resolve the promise with true
            resolve(true);
          } else {
            // Directory or not the file to look for, traverse it recursively
            fs.readdir(dirPath, (err, files) => {
              if (err) {
                reject(err);
              } else {
                let promises = files.map(file =>
