```javascript
function depthFirstSearch(grid, startX, startY, maxNodes) {
  const visited = new Set();
  let nodesPlanted = 0;

  function dfs(x, y) {
    if (
      x < 0 ||
      x >= grid.length ||
      y < 0 ||
      y >= grid[0].length ||
      visited.has(x + "," + y) ||
      grid[x][y].state === "visited"
    ) {
      return;
    }

    visited.add(x + "," + y);
    grid[x][y].state = "visited";
    nodesPlanted++;

    if (nodesPlanted === maxNodes) return;

    dfs(x + 1, y);
    dfs(x - 1, y);
    dfs(x, y + 1);
    dfs(x, y - 1);

    const randomX = Math.floor(Math.random() * grid.length);
    const randomY = Math.floor(Math.random() * grid[0].length);

    if (grid[randomX][randomY].state !== "visited") {
      grid[randomX][randomY].value = Math.floor(Math.random() * 100);
      grid[randomX][randomY].state = "visited";
      nodesPlanted++;
    }

    if (nodesPlanted === maxNodes) return;
  }

  dfs(startX, startY);
}
