async function testRequireJs() {
  QUnit.test('Test require.js() module loader with caching and error handling', async function (assert) {
    const firstModule = 'test-module-1';
    const secondModule = 'test-module-2';

    // Set up the require.js configuration
    const config = {
      baseUrl: '.',
      paths: {
        'test-module-1': 'test-module-1',
        'test-module-2': 'test-module-2'
      },
      shim: {
        'test-module-1': { exports: 'TestModule1' }
      }
    };

    // Initialize require.js with the configuration
    await new Promise((resolve) => {
      require.config(config);
      require(['test-module-1'], resolve);
    });

    // Test module loading and caching
    assert.equal(require(firstModule).TestModule1.message, 'Hello from TestModule1');
    assert.equal(require(firstModule).TestModule1.message, 'Hello from TestModule1');

    // Test error handling
    await assert.throwsAsync(() => {
      require('non-existent-module');
    }, (err) => {
      assert.ok(err, 'Error should be thrown');
      assert.equal(err.name, 'Error');
      assert.equal(err.message, 'Module "non-existent-module" not found');
    });

    // Test module loading with dependencies
    await new Promise((resolve) => {
      require(['test-module-1', 'test-module-2'], function (TestModule1, TestModule2) {
        assert.ok(TestModule1.TestModule1, 'TestModule1 should be defined');
        assert.ok(TestModule2.TestModule2, 'TestModule2 should be defined');
        resolve();
      });
    });

    // Test module dependencies resolution
    assert.equal(require(secondModule).TestModule2.message, 'Hello from TestModule2');
  });
}
