  return new Promise((resolve, reject) => {
    const gitCloneCmd = 'git clone';
    const gitCloneArgs = [repositoryUrl, destinationDirectory];

    child_process.exec(gitCloneCmd, gitCloneArgs, (error, stdout, stderr) => {
