async function generateAndSendMessage(inputMessage) {
  if (!inputMessage) {
    throw new Error("Input message cannot be empty");
  }

  const idGenerator = new Crypto.Subtle.Random();
  const idLength = 16; // You can adjust the length of the identifier as needed
  let id = new Uint8Array(idLength);
  id = new TextEncoder().encode(id.map(() => idGenerator.generateByte()).fill(null));

  const encryptionKey = await crypto.subtle.generateKey(
    "AES-GCM",
    id,
    { name: "AES-GCM/NoPadding" },
    false,
    ["encrypt", "decrypt"]
  );

  const encryptedMessage = await crypto.subtle.encrypt(
    encryptionKey,
    new TextEncoder().encode(inputMessage),
    new ArrayBuffer(crypto.getLengthOrSize(encryptionKey, "encrypt")),
  );

  const messageToSend = new Uint8Array(
    new ArrayBuffer(idLength + encryptedMessage.byteLength)
  );
  messageToSend.set(id);
  messageToSend.set(new Uint8Array(encryptedMessage), idLength);

  const socket = new WebSocket("wss://example.com/endpoint"); // Replace with your actual endpoint
  socket.binaryType = "arraybuffer";

  socket.onopen = () => {
    socket.send(messageToSend.buffer);
  };

  socket.onmessage = (event) => {
    const decryptedMessage = crypto.subtle.decrypt(
      encryptionKey,
      event.data,
      null,
      false,
      ["arraybuffer"]
    );
    const decryptedMessageText = new TextDecoder().decode(decryptedMessage);
    console.log("Received message: ", decryptedMessageText);
  };

  socket.onerror = (error) => {
    console.error("Error sending message: ", error);
  };

  socket.onclose = () => {
    console.log("Connection closed");
  };
}
