```javascript
function grep(arr, filterFunction) {
  if (typeof filterFunction !== 'function') {
    try {
      filterFunction = new Function('elem, index', 'return ' + filterFunction);
    } catch (error) {
      throw new Error('Invalid filter function');
    }
  }

  const result = [];
  for (let i = 0; i < arr.length; i++) {
    const element = arr[i];
    const passesTest = filterFunction(element, i);

    if (typeof passesTest === 'boolean' && passesTest) {
      result.push(element);
    } else if (Array.isArray(passesTest)) {
      result.push(...passesTest.filter(elem => elem === element));
    }
  }

  return result;
}
