```javascript
const fs = require('fs-extra');
const path = require('path');

function validateAndCreate(dirPath, options) {
  const { files, directories, createEmptyFiles } = options;

  if (!fs.existsSync(dirPath)) {
    throw new Error(`Directory '${dirPath}' does not exist.`);
  }

  if (!fs.lstatSync(dirPath).isDirectory()) {
    throw new Error(`'${dirPath}' is not a valid directory.`);
  }

  for (const file of files) {
    const filePath = path.join(dirPath, file);
    if (!fs.existsSync(filePath)) {
      fs.mkdirpSync(path.dirname(filePath)).then(() => {
        fs.writeFileSync(filePath, '');
        if (createEmptyFiles) {
          console.log(`Created empty file '${file}' in '${dirPath}'.`);
        }
      }).catch((err) => {
        throw new Error(`Failed to create file '${file}' in '${dirPath}'.`, err);
      });
    }
  }

  for (const dir of directories) {
    const dirPathToCreate = path.join(dirPath, dir);
    if (!fs.existsSync(dirPathToCreate)) {
      fs.mkdirpSync(dirPathToCreate).then(() => {
        console.log(`Created directory '${dir}' in '${dirPath}'.`);
      }).catch((err) => {
        throw new Error(`Failed to create directory '${dir}' in '${dirPath}'.`, err);
      });
    } else if (fs.lstatSync(dirPathToCreate).isFile()) {
      throw new Error(`'${dirPathToCreate}' exists as a file, not a directory.`);
    }
  }
}

module.exports = { validateAndCreate };
