function generateUuid() {
  const randomBytes = async () => new Uint8Array(16);
  let buffer;

  try {
    buffer = await crypto.subtle.generateKey(
      { name: "HMAC", hash: "SHA-1" },
      true, // extractable: false
      ["arrayBuffer"]
    );
    const dataView = new DataView(buffer);

    // Time low and high (4 bytes each)
    const timeLow = dataView.getUint32(0);
    const timeHigh = dataView.getUint32(4);

    // Version (1 byte)
    const version = dataView.getUint8(8);

    // Clock sequence (2 bytes)
    let clockSequence = dataView.getUint16(9);
    if (clockSequence === 0) {
      clockSequence = 0x1000; // Increment if zero
    }

    // Node identifier (6 bytes)
    const node = new Uint8Array(6);
    window.crypto.getRandomValues(node);

    // Combine parts
    const uuid = [
      timeLow.toString(16).padStart(8, "0"),
      timeHigh.toString(16).padStart(8, "0"),
      version.toString(16).padStart(4, "0"),
      (clockSequence & 0x3fff | 0x8000).toString(16).padStart(8, "0"),
      node.slice(0, 2).map(byte => byte.toString(16).padStart(2, "0")).join(""),
      node.slice(2, 4).map(byte => byte.toString(16).padStart(2, "0")).join(""),
      node.slice(4, 6).map(byte => byte.toString(16).padStart(2, "0")).join("")
    ].join("-");

    // Free the key
    crypto.subtle.destroyKey(buffer);

    return uuid;
  } catch (error) {
    console.error("Error generating UUID:", error);
    throw error;
  }
}
