const _ = require('lodash');
const async = require('async');
const Logger = require('winston');

const server = new Restify.Server();

const logger = new Logger({
  level: 'info',
  transports: [
    new Logger.Console(),
    new Logger.File({ filename: 'api.log', level: 'info' })
  ]
});

server.use(Restify.plugins.queryParser());
server.use(Restify.plugins.bodyParser());

server.get('/ping', (req, res, next) => {
  try {
    async.series([
      () => new Promise((resolve, reject) => {
        logger.info(`Received GET request for /ping with query params: ${JSON.stringify(req.params)}`);
        resolve();
      }),
      () => new Promise((resolve, reject) => {
        setTimeout(() => {
          res.send({ message: 'Ping received' }, 200);
          logger.info(`Sent response for GET request to /ping with status code 200`);
          resolve();
        }, 1000);
      })
    ], (err) => {
      if (err) {
        next(err);
      } else {
        next();
      }
    });
  } catch (error) {
    logger.error(`Error handling GET request for /ping: ${error.message}`);
    res.send(500, { error: 'Internal server error' });
  }
});

server.on('uncaughtException', (req, res, route, err) => {
  logger.error(`Uncaught exception in request handler for ${route.path}: ${err.message}`);
  res.send(500, { error: 'Internal server error' });
});

server.listen(3000, () => {
  logger.info('Server listening on port 3000');
});
