function decodeWBXMLToActiveSyncData(wbxmlDocument) {
  // Create a new WBXML parser using the WBXML.js library
  const parser = new WBXML.Parser();

  // Parse the WBXML document string
  const document = parser.parse(wbxmlDocument);

  // Validate the document type and check for errors
  if (document.type !== "ActiveSync") {
    throw new Error("Invalid WBXML document. Expected ActiveSync type.");
  }

  if (document.error) {
    throw new Error("WBXML parsing error: " + document.error.message);
  }

