          if (ext === '.coffee') {
            try {
              const code = CoffeeScript.compile(data);
              require('eval')('(' + code + ')');
            } catch (error) {
              console.error(`Error compiling and running CoffeeScript file: ${filePath}: ${error.message}`);
            }
          } else {
            require(filePath);
          }
        });
      }
    });
  });

  register();
}

