const fs = require('fs');
const path = require('path');
const exec = require('child_process').exec;

const packageName = process.argv[2];
const debianOutputPath = './debian-package/';
const rpmOutputPath = './rpm-package/';

function isValidPackageName(name) {
  // Regular expression to validate Debian package names:
  // https://www.debian.org/doc/debian-policy/ch-control.html#sec-package-names
  const debianPattern = /^[a-zA-Z0-9_-]+$/;
  return debianPattern.test(name);
}

if (!isValidPackageName(packageName)) {
  console.error('Invalid package name');
  process.exit(1);
}

// Create Debian package
function createDebianPackage() {
  const debianCommand = 'dpkg-deb --build .';
  const debianCwd = process.cwd();
  const debianArgs = ['--output', debianOutputPath, '.'];

  exec(debianCommand, { cwd: debianCwd, args: debianArgs }, (error, stdout, stderr) => {
    if (error) {
      console.error(`Error creating Debian package: ${error}`);
      process.exit(1);
    }
    console.log('Debian package created successfully');
  });
}

// Create Red Hat package (if rpmbuild is available)
function createRpmPackage() {
  const rpmCommand = 'rpmbuild --define "_topdir %{_topdir}" --define "_sourcedir %{_sourcedir}" --define "_builddir %{_builddir}" --define "_buildroot %{_buildroot}" --define "_srcrpmdir %{_srcrpmdir}" --define "_specdir %{_specdir}" --define "_rpmfile %{NAME}-%{VERSION}.%{ARCH}.rpm' +
    ' --define "_srcrpm %{NAME}-%{VERSION}.%{ARCH}.src.rpm' +
    ' %{NAME}/%{NAME}.spec';

  fs.access('rpmbuild', fs.constants.F_OK, (error) => {
    if (error) {
      console.error('rpmbuild not found, skipping RPM package creation');
      return;
    }

    const rpmCwd = path.join(__dirname, 'rpm-package');
    const rpmArgs = [];

    exec(rpmCommand, { cwd: rpmCwd, args: rpmArgs }, (error, stdout, stderr) => {
      if (error) {
        console.error(`Error creating RPM package: ${error}`);
        process.exit(1);
      }
      console.log('RPM package created successfully');
    });
  });
}

// Create package directories
function createPackageDirectories() {
  if (!fs.existsSync(debianOutputPath)) {
    fs.mkdirSync(debianOutputPath);
  }

  if (!fs.existsSync(rpmOutputPath)) {
    fs.mkdirSync(rpmOutputPath);
  }
}

// Build packages
createPackageDirectories();
createDebianPackage();
createRpmPackage();
```

