import PropTypes from 'prop-types';

const SkillsGrid = ({ skillsData }) => {
  const [skills, setSkills] = useState([]);

  useEffect(() => {
    setSkills(skillsData);
  }, [skillsData]);

  return (
    <div>
      <h2>Skills</h2>
      <div className="skills-grid">
