const fs = require('fs');
const path = require('path');

function loadModule(modulePath) {
  // Validate the modulePath to ensure it's a safe local file or a known remote URL
  const isLocal = /^(\.\/)?[^\/]+([\/]|$)/.test(modulePath);

  if (isLocal) {
    const absPath = path.resolve(modulePath);

    if (fs.existsSync(absPath) && path.extname(absPath).toLowerCase() === '.js') {
      const module = require(absPath);
      window[module.default ? module.default.name : module.name] = module;
      return;
    }
  }

  // For remote modules, use a whitelist of allowed module names
  const allowedModules = ['lodash', 'react', 'react-dom'];
  const moduleName = path.basename(modulePath, path.extname(modulePath));

  if (allowedModules.includes(moduleName)) {
    const moduleUrl = `https://cdn.jsdelivr.net/npm/${moduleName}/dist/${moduleName}.min.js`;

    fetch(moduleUrl)
      .then((response) => response.text())
      .then((source) => {
        const script = document.createElement('script');
        script.src = URL.createObjectURL(new Blob([source]));
        document.head.appendChild(script);

        // Wait for the module to be loaded before assigning it to the global variable
        script.onload = () => {
          window[moduleName] = this[moduleName];
        };
