function generateSessionId(secretKey, sessionIdLength) {
  if (typeof secretKey !== 'string' || secretKey.length <= 0) {
    throw new Error('Invalid secret key');
  }
  if (typeof sessionIdLength !== 'number' || sessionIdLength <= 0) {
    throw new Error('Invalid session ID length');
  }

  const randomBytes = new Uint8Array(crypto.getRandomValues(new Uint8Array(32)));
  const sessionId = btoa(
    secretKey
      .slice(0, 16) // Use the first 16 bytes of the secret key
      .padEnd(32, '\x00') // Pad the secret key to 32 bytes
      .concat(new Uint8Array(randomBytes))
      .reduce((data, byte) => data + String.fromCharCode(byte), '')
  );

  return sessionId.substring(0, sessionIdLength);
}
