const iframe = document.createElement('iframe'); // Create an iframe
iframe.style.display = 'none'; // Hide the iframe
document.body.appendChild(iframe); // Add the iframe to the document

const origin = window.location.origin; // Get the trusted origin

function loadWorlds() {
  iframe.src = `${origin}/worlds`; // Request the list of worlds from the server

  iframe.addEventListener('message', (event) => {
    if (event.origin !== origin) {
      return; // Only accept messages from the trusted origin
    }

    const worlds = event.data; // Get the list of worlds from the message
    displayWorlds(worlds); // Display the worlds in the web page
  });
}

function displayWorlds(worlds) {
  const select = document.createElement('select'); // Create a select element
  const form = document.createElement('form'); // Create a form element

  for (const world of worlds) {
    const option = document.createElement('option'); // Create an option element
    option.value = world.id; // Set the option value to the world id
    option.textContent = world.name; // Set the option text to the world name
    select.appendChild(option); // Add the option to the select element
  }

  form.appendChild(select); // Add the select element to the form
  document.body.appendChild(form); // Add the form to the document

  form.addEventListener('submit', (event) => {
    event.preventDefault(); // Prevent the form from submitting normally

    const selectedWorldId = select.value; // Get the selected world id

    iframe.src = `${origin}/world?id=${selectedWorldId}`; // Request the selected world from the server

    form.remove(); // Remove the form from the document
  });

  loadWorlds(); // Load the list of worlds initially
}
