function generateNestedArray(dimensions, lowerBounds = [0]) {
  if (!Array.isArray(dimensions)) {
    throw new Error("Invalid dimensions. Expected an array.");
  }

  const checkBounds = (bounds) => {
    if (!Array.isArray(bounds) || bounds.length !== dimensions.length) {
      throw new Error("Invalid bounds. Expected an array of the same length as dimensions.");
    }
    for (let i = 0; i < bounds.length; i++) {
      if (typeof bounds[i] !== "number") {
        throw new Error("Invalid bound. Expected a number.");
      }
      if (bounds[i] < lowerBounds[i]) {
        throw new Error("Invalid bound. Bound must be greater than or equal to lower bound.");
      }
    }
  };

  checkBounds(lowerBounds);

  const nestedArray = new Array(dimensions[0]);
  for (let i = 0; i < dimensions[0]; i++) {
    if (dimensions.length > 1) {
      nestedArray[i] = generateNestedArray(dimensions.slice(1), lowerBounds.slice(1));
    } else {
      nestedArray[i] = new Array(dimensions[1]).fill(0);
    }
  }

  return nestedArray;
}

function evaluateNestedArray(nestedArray, callback) {
  if (!Array.isArray(nestedArray)) {
    throw new Error("Invalid nested array.");
  }

  for (let i = 0; i < nestedArray.length; i++) {
    if (typeof nestedArray[i] !== "number" && !(Array.isArray(nestedArray[i]))) {
      throw new Error("Invalid nested array element.");
    }

    if (Array.isArray(nestedArray[i])) {
      evaluateNestedArray(nestedArray[i], callback);
    } else {
      callback(nestedArray[i]);
    }
  }
}

