function changeBackgroundColor(elementId, backgroundIndex) {
  const element = document.getElementById(elementId);
  if (!element) {
    throw new Error(`Element with ID '${elementId}' not found.`);
  }

  const validBackgroundIndices = ['0', '1', '2', '3', '4', '5']; // Define all valid background indices
  if (!validBackgroundIndices.includes(String(backgroundIndex))) {
    throw new Error('Invalid background index.');
  }

  const backgroundColors = ['#FFFFFF', '#FFCCFF', '#FFC0CB', '#FFB6C1', '#FFA07A', '#FF69B4']; // Define all valid background colors
  const currentBackgroundColorIndex = getBackgroundColorIndex(element);

  if (currentBackgroundColorIndex === String(backgroundIndex)) {
    element.style.backgroundColor = ''; // Set background color to blank
  } else {
    element.style.backgroundColor = backgroundColors[backgroundIndex]; // Set background color to new value
  }
}

function getBackgroundColorIndex(element) {
  const backgroundColorProperty = element.currentStyle || window.getComputedStyle(element, null).getPropertyValue('background-color');
  const backgroundColorRegex = /^#([A-Fa-f0-9]{2})([A-Fa-f0-9]{2})([A-Fa-f0-9]{2})$/; // Regular expression to strictly validate the format of the background color

  if (!backgroundColorRegex.test(backgroundColorProperty)) {
    throw new Error('Invalid background color format.');
