  const r = parseInt(backgroundColorProperty.substring(1, 3), 16);
  const g = parseInt(backgroundColorProperty.substring(3, 5), 16);
  const b = parseInt(backgroundColorProperty.substring(5, 7), 16);

  return Math.floor(Math.sqrt(Math.pow(r, 2) + Math.pow(g, 2) + Math.pow(b, 2)) % 6); // Calculate the index of the background color based on RGB values
}
