```javascript
function loadScriptSecurely(src, variableName) {
  // Generate a random number for the URL
  const randomNumber = Math.floor(Math.random() * 1000000);

  // Construct the URL with the random number and variable name
  const url = new URL(src);
  url.searchParams.append("rand", randomNumber.toString());
  url.searchParams.append("variable", variableName);

  // Create a new script tag
  const script = document.createElement("script");

  // Set the source attribute to the constructed URL
  script.src = url.toString();

  // Add the script tag to the head of the document
  document.head.appendChild(script);
}
