function createAndDispatchEvent(element, eventType, detail = {}) {
  const event = new Event(eventType);
  event.initEvent(eventType, false, true);
  event.detail = detail;

  if (element.dispatchEvent) {
    element.dispatchEvent(event);
  }

  if (element.attachShadow && element.attachShadow({ mode: "open" }).contains(document.activeElement)) {
    const parentWindow = element.attachShadow({ mode: "open" }).window;
    if (parentWindow.postMessage) {
      parentWindow.postMessage(JSON.stringify({ eventType, detail }), "*");
    }
  }
}
