async function reloadCommand(client, oldCommandName) {
  try {
    // Validate the input
    if (!client || !oldCommandName) {
      throw new Error("Invalid input: client or oldCommandName is missing");
    }

    // Get the old command
    const oldCommand = client.commands.get(oldCommandName);

    if (!oldCommand) {
      throw new Error(`Command "${oldCommandName}" not found`);
    }

    // Delete the old command
    client.commands.delete(oldCommandName);

    // Require the command module again
    const newCommandModule = require(oldCommand.path);
    const newCommand = new (newCommandModule.default)();

    // Update the command's aliases
    if (newCommand.aliases) {
      for (const alias of newCommand.aliases) {
        client.commands.set(alias, newCommand);
      }
    }

    // Set the new command with its aliases
    client.commands.set(oldCommandName, newCommand);

    log.info(`Command "${oldCommandName}" reloaded`);
  } catch (error) {
    console.error(`Error reloading command "${oldCommandName}":`, error.message);
  }
}
