#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <unistd.h>
#define MAX_DEPTH 100
#define MAX_DEPENDENCIES 50

typedef struct Node {
    char name[256];
    int depth;
    struct Node *next;
} Node;

void print_dependencies(Node *root, int depth) {
    Node *current = root;
    if (depth > MAX_DEPTH) {
        printf("Depth limit of %d reached. Skipping remaining dependencies.\n", MAX_DEPTH);
        return;
    }

    while (current != NULL) {
        if (depth > current->depth) {
            for (int i = 0; i < depth - current->depth; i++) {
                printf("  ");
            }
        }
        printf("%s\n", current->name);

        if (--MAX_DEPENDENCIES <= 0) {
            printf("Maximum number of dependencies (%d) reached. Skipping remaining dependencies.\n", MAX_DEPENDENCIES);
            return;
        }

        current = current->next;
    }
}

void add_dependency(Node **root, char *dependency) {
    Node *new_node = (Node *) malloc(sizeof(Node));
    strcpy(new_node->name, dependency);
    new_node->depth = depth + 1;
    new_node->next = *root;
    *root = new_node;
}

void traverse_tree(Node *root, int depth) {
    Node *current = root;
    while (current != NULL) {
        if (current->next != NULL) {
            traverse_tree(current->next, depth + 1);
        }
        add_dependency(&root, current->name);
        current = current->next;
    }
}

int main() {
    Node *root = NULL;
    char dependencies[MAX_DEPENDENCIES][256];
    int num_dependencies = 0;

    traverse_tree(root, 0);

    printf("Dependencies:\n");
    for (int i = 0; i < num_dependencies && num_dependencies < MAX_DEPENDENCIES; i++) {
        printf("%s\n", dependencies[i]);
    }
    if (num_dependencies >= MAX_DEPENDENCIES) {
        printf("Maximum number of dependencies (%d) reached. Skipping remaining dependencies.\n", MAX_DEPENDENCIES);
    }

    return 0;
}
