const fs = require('fs');
const path = require('path');
const { AVCodecs, AVFormatContext, AVFrame, AVPixelFormat } = require('ffmpeg-python');

const version = '1.0.0';

const readFrames = async (filePath, nbFrames) => {
  const format = await AVFormatContext.open(filePath);
  const videoStream = format.streams.find(s => s.codecpar.codec_type === AV_CODEC_TYPE_VIDEO);

  const frames = [];
  let frame;

  for (let i = 0; i < nbFrames && (frame = await videoStream.readFrame()) !== null; i++) {
    frames.push(frame.toBuffer());
  }

  await format.close();
  return frames;
};

const writeFrames = async (filePath, frames) => {
  const format = new AVFormatContext();
  format.outputFile = filePath;
  format.format = 'avi';

  const videoStream = format.addStream('mpeg2video', { width: 640, height: 480 });

  for (const frame of frames) {
    const frameBuffer = Buffer.from(frame);
    const avFrame = new AVFrame();
    avFrame.data = [frameBuffer];
    avFrame.format = AVPixelFormat.MJPG;

    await videoStream.writeFrame(avFrame);
  }

  await format.write();
  await format.close();
};

const convertFormat = async (inputFile, outputFile, targetFormat) => {
  const inputFormat = await AVFormatContext.open(inputFile);
  const outputFormat = new AVFormatContext();
  outputFormat.outputFile = outputFile;
  outputFormat.format = targetFormat;

  const videoStreamInput = inputFormat.streams.find(s => s.codecpar.codec_type === AV_CODEC_TYPE_VIDEO);
  const videoStreamOutput = outputFormat.addStream('libx264', { bitrate: 5000000 });

  await AVCodec.sendFrame(videoStreamInput, await videoStreamInput.readFrame());
  await AVCodec.sendFrame(videoStreamOutput, null);

  await AVPacket.sendPacket(outputFormat, AVPacket.newPacket());

  await inputFormat.close();
  await outputFormat.write();
  await outputFormat.close();
};

module.exports = { version, readFrames, writeFrames, convertFormat };
