function decodeAndProcessZlibData(base64Data, callback) {
  if (!base64Data || typeof base64Data !== 'string' || !callback) {
    throw new Error('Invalid input');
  }

  const buffer = Buffer.from(base64ToBuffer(base64Data), 'base64');
  let decodedData;

