  } catch (error) {
    throw new Error('Invalid compressed data');
  }

  const hexCodesAndOffsets = [];
  let currentOffset = 0;

  for (let i = 0; i < decodedData.length; i += 2) {
    const hexCode = decodedData.slice(i, i + 2).toString('hex');
    hexCodesAndOffsets.push({
      codeFragment: hexCode,
      offset: currentOffset,
    });
    currentOffset += hexCode.length / 2;
