function makeDraggable(object, minX, maxX, leftButton, rightButton) {
  // Set initial styles
  if (!object.style.position) {
    object.style.position = "absolute";
  }
  if (!object.style.left) {
    object.style.left = "0px";
  }
  if (!object.style.right) {
    object.style.right = "0px";
  }

  let isDragging = false;
  let startX = 0;
  let startLeft = parseFloat(object.style.left);
  let startRight = parseFloat(object.style.right);

  function onDragStart(event) {
    if (event.button === 0) { // left button
      isDragging = true;
      startX = event.clientX;
    } else if (event.button === 2) { // right button
      isDragging = true;
      startX = event.clientX;
      startRight = parseFloat(object.style.right);
    }
  }

  function onDrag(event) {
    if (!isDragging) {
      return;
    }

    let newLeft = startLeft + (event.clientX - startX);
    let newRight = startRight + (event.clientX - startX);

    // Prevent dragging outside the acceptable range
    if (newLeft < minX) {
      newLeft = minX;
    }
    if (newLeft > maxX) {
      newLeft = maxX;
    }
    if (newRight < minX) {
      newRight = minX;
    }
    if (newRight > maxX) {
      newRight = maxX;
    }

    object.style.left = newLeft + "px";
    if (rightButton) {
      rightButton.style.right = newRight + "px";
    }
  }

  function onDragEnd() {
    isDragging = false;
  }

  // Set event listeners
  object.addEventListener("mousedown", onDragStart);
  leftButton.addEventListener("mousedown", onDragStart);
  document.addEventListener("mouseup", onDragEnd);
  document.addEventListener("mousemove", onDrag);

  // Clean up on destroy
  return function() {
    object.removeEventListener("mousedown", onDragStart);
    leftButton.removeEventListener("mousedown", onDragStart);
    document.removeEventListener("mouseup", onDragEnd);
    document.removeEventListener("mousemove", onDrag);
  };
}
