import { useReactComponentTreeHook } from 'react-inspect-element';
import EventPluginRegistry from 'react-dom/events';
import { warning } from 'react-warning';

const validateReactComponent = (component) => {
  const treeHook = useReactComponentTreeHook(component);
  const root = treeHook.getRoot();

  useEffect(() => {
    const handleEvent = (event) => {
      const eventName = event.type;
      const eventTarget = event.target;

      if (eventName === 'click' && eventTarget.nodeName === 'BUTTON') {
        const propertyName = event.propertyName;

        if (propertyName && !root.props[propertyName]) {
          warning(
            `The React component <${component.type.name}> has an unrecognized property '${propertyName}'`,
            `Unrecognized property '${propertyName}' in component <${component.type.name}>`
          );
        }
      }
    };

    EventPluginRegistry.registerEventType('myCustomEvent', handleEvent);

    return () => {
      EventPluginRegistry.unregisterEventType('myCustomEvent');
    };
  }, []);

  useEffect(() => {
    const eventHandlers = [];

    const handleEvent = (event) => {
      const eventName = event.type;
      const eventTarget = event.target;

      if (eventName === 'click' && eventTarget.nodeName === 'BUTTON') {
        const propertyName = event.propertyName;

        if (propertyName && !root.props[propertyName]) {
