              `Unrecognized property '${propertyName}' in component <${component.type.name}>`
            )
          );
        }
      }
    };

    const listener = () => {
      eventHandlers.forEach((handler) => handler());
    };

    document.addEventListener('myCustomEvent', listener);

    return () => {
