#include <stdlib.h> // for malloc and free

typedef struct BufferNode {
    char *data;
    size_t length;
    struct BufferNode *next;
} BufferNode;

BufferNode *concatenate_buffers(BufferNode *head) {
    BufferNode *current = head;
    size_t total_length = 0;

    // Iterate through the list of buffers to calculate the total length
    while (current != NULL) {
        total_length += current->length;
        current = current->next;
    }

    // Allocate a new buffer with the total length of all the buffers in the list
    char *concatenated_buffer = malloc(total_length);
    if (concatenated_buffer == NULL) {
