const MAX_POLLING_INTERVAL = 10; // in milliseconds
let messageListeners = new Map();
let pollingInterval = null;

function createMessageHandler(id) {
  return new Promise((resolve) => {
    messageListeners.set(id, resolve);
  });

  function handleMessage(event) {
    if (event.data.id === id) {
      messageListeners.get(id)(event.data.message);
      messageListeners.delete(id);
    }
  }

  window.addEventListener('message', handleMessage, false);

  return {
    send: function(message) {
      if (navigator.serviceWorker) {
        navigator.serviceWorker.controller.postMessage({ id, message });
      } else if (self.postMessage) {
        self.postMessage({ id, message }, '*'); // Use a trusted origin for production
      } else {
        pollForMessage();
        this.sendMessage = function(msg) {
          window.parent.postMessage({ id, message }, '*'); // Use a trusted origin for production
        };
      }
    },
    close: function() {
      window.removeEventListener('message', handleMessage, false);
      if (pollingInterval) {
        clearInterval(pollingInterval);
      }
    },
  };
}

function pollForMessage() {
  if (pollingInterval) return;
  pollingInterval = setInterval(() => {
    const messages = document.documentElement.getAttribute('data-messages');
    if (messages) {
      const parsedMessages = JSON.parse(messages);
      if (parsedMessages.length > 0) {
        const message = parsedMessages.shift();
        if (message.id === id) {
          messageListeners.get(id)(message.message);
          messageListeners.delete(id);
        }
        document.documentElement.setAttribute('data-messages', JSON.stringify(parsedMessages));
      }
      if (parsedMessages.length === 0) {
        clearInterval(pollingInterval);
      }
    }
  }, MAX_POLLING_INTERVAL);
}
