import propTypes from 'prop-types';

type ValidationFunction = (prop: any) => void;

const PROP_TYPE_CACHE: Record<string, Record<string, propTypes.ValidationMap>> = {};

function createPropTypeChecker(validationFunction: ValidationFunction, componentName: string): Function {
