const child_process = require('child_process');

function executeCommandWithFileCheck(command, inputFiles, watch) {
  if (!Array.isArray(inputFiles) || inputFiles.length <= 0) {
    // If no inputFiles are provided, execute the command directly
    executeCommand(command);
    return;
  }

  inputFiles.forEach((filePath) => {
    if (!fs.existsSync(filePath)) {
      // If any inputFile is missing, do not execute the command
      console.error(`Input file '${filePath}' does not exist.`);
      return;
    }
  });

  if (watch) {
    // If --watch option is passed, use fs.watch() to monitor inputFiles for changes
    inputFiles.forEach((filePath) => {
      fs.watchFile(filePath, (eventType, filename) => {
        if (eventType === 'change') {
          // If any inputFile is modified, execute the command again
          executeCommand(command);
        }
      });
    });
  }

  // Execute the command
  child_process.exec(command, (error, stdout, stderr) => {
    if (error) {
      console.error(`Error executing command '${command}': ${error}`);
      return;
    }

    console.log(`Command '${command}' executed successfully:\n${stdout}`);
    if (stderr) {
      console.error(`Command '${command}' stderr:\n${stderr}`);
    }
  });
}

function executeCommand(command) {
