function listenForIframeEvent(iframe) {
  if (!iframe || !iframe.contentWindow || !iframe.src || !iframe.dataset) {
    return;
  }

  const allowedSrcPattern = /^(https?:\/\/)[^\/]+\.([a-z]+)$/;
  const autoplayAttribute = "data-autoplay";

  if (!allowedSrcPattern.test(iframe.src)) {
    console.error(`Invalid iframe src: ${iframe.src}`);
    return;
