```javascript import React, { useState } from 'react';

const ListItem = ({ entities, location, url, onClick, select, description }) => {
  const [isSelected, setIsSelected] = useState(select);

  const renderMapMarker = () => (
    <i className="material-icons">location_on</i>
  );

  const renderLocation = () => <p>{location}</p>;

  const renderDescription = () => <p>{description}</p>;

  const renderCardBlock = () => (
    <div className="card">
      <div className="card-content">
        <p>{description}</p>
      </div>
    </div>
  );

  const handleClick = () => {
    setIsSelected(!isSelected);
    onClick && onClick();
  };

  return (
    <li onClick={handleClick}>
      <button className="list-item-button">
        {entities && !url && !location ? renderCardBlock() : (
          <>
            {location && renderMapMarker()}
            {location && renderLocation()}
          </>
        )}
      </button>
      {entities && !url && !location && renderDescription()}
      {isSelected && <hr className="divider" />}
    </li>
  );
};

export default ListItem;
