use Doctrine\DBAL\Connection;

function truncateTableAndResetId(Connection $connection, string $tableName): int
{
    $tableSchema = $connection->createSchemaManager()->listTableDetails($tableName);
    $idColumnName = $tableSchema[0]['columns'][array_keys($tableSchema[0]['columns'])[array_search('int', array_map('strval', array_column($tableSchema[0]['columns'], 'type')))]]['name'];

    try {
        $connection->beginTransaction();

        // Truncate the table
        $connection->exec("TRUNCATE TABLE {$tableName}");

        // Reset the auto-incrementing ID column
        $connection->exec("ALTER TABLE {$tableName} MODIFY {$idColumnName} INT AUTO_INCREMENT START WITH 1");

        // Disable foreign key checks
        $connection->exec("SET FOREIGN_KEY_CHECKS = 0");

        $connection->commit();

        return 0;
    } catch (\Exception $e) {
        $connection->rollback();

        return $e->getCode();
    }
}
