function getContentTypeHash(array $objects): string {
    $contentTypeHashes = [];

    foreach ($objects as $object) {
        if (!is_array($object) || !array_key_exists("_id", $object) || !array_key_exists("minifier", $object) || !array_key_exists("minifyOptions", $object)) {
            throw new Exception("Invalid object format.");
        }

        $serializedObject = serialize($object);
        $md5Hash = md5($serializedObject);

        if (strlen($md5Hash) > 32) {
            throw new Exception("MD5 hash is too long.");
        }

        $contentTypeHashes[] = $md5Hash;
    }

    $contentType = "application/x-php-serialized";
    $packedContentTypeHashes = pack("H*", implode("-", $contentTypeHashes));

    $headerSize = strlen($contentType) + strlen($packedContentTypeHashes);
    $header = pack("N", $headerSize) . $contentType . $packedContentTypeHashes;

    return bin2hex($header);
}
