import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.function.Predicate;

public class MethodFilter {
    private static final Set<String> WHITELISTED_METHODS = Collection.unmodifiableSet(Set.of(
            "getSimpleName",
            "getName",
            "isInterface",
            "isInstance",
            "isAnnotationPresent"
    ));

    public static List<Method> filterMethods(Class<?>[] classesAndInterfaces, String methodNameFilter,
                                            Class<?>[] annotationTypes, boolean includeAbstract) {
        List<Method> methods = new ArrayList<>();
        for (Class<?> clazz : classesAndInterfaces) {
            Method[] declaredMethods = clazz.getDeclaredMethods();
            for (Method method : declaredMethods) {
                if (isValidMethod(method, methodNameFilter, annotationTypes, includeAbstract)) {
                    methods.add(method);
                }
            }
            if (clazz.isInterface()) {
                Method[] interfaceMethods = clazz.getMethods();
                for (Method method : interfaceMethods) {
                    if (isValidMethod(method, methodNameFilter, annotationTypes, includeAbstract)) {
                        methods.add(method);
                    }
                }
            }
        }
        return methods;
    }

    private static boolean isValidMethod(Method method, String methodNameFilter, Class<?>[] annotationTypes,
                                        boolean includeAbstract) {
        String methodName = method.getName();
        if (methodNameFilter != null && !methodName.equalsIgnoreCase(methodNameFilter)) {
            return false;
        }
        if (annotationTypes != null && method.isAnnotationPresent(where(annotationTypes))) {
            return false;
        }
        if (includeAbstract && method.isAbstract()) {
            return true;
        }
        if (!includeAbstract && !method.isAccessible()) {
            method.setAccessible(true);
        }
        if (!WHITELISTED_METHODS.contains(method.getName())) {
            method.setAccessible(false);
            return false;
        }
        return true;
    }

    private static <T> Predicate<Class<?>> where(T[] values) {
        return clazz -> Arrays.asList(values).contains(clazz);
    }
}
