#include <iostream>
#include <string>
#include <cstring>
#include <openssl/sha.h>

std::string calculate_hash(const std::string& namespace_uuid, const std::string& name) {
  if (namespace_uuid.size() != 36 || name.size() > 64) {
    throw std::invalid_argument("Invalid input: namespace_uuid must be 36 characters long and name must be less than 65 characters long.");
  }

  unsigned char hash[SHA_DIGEST_LENGTH];
  SHA1((const unsigned char*)namespace_uuid.c_str(), namespace_uuid.size(), hash);
  SHA1((const unsigned char*)name.c_str(), name.size(), hash + SHA_DIGEST_LENGTH);

