function validateSignature($token, $timestamp, $nonce, $signature) {
    // Validate input parameters
    if (empty($token) || empty($timestamp) || empty($nonce) || empty($signature)) {
        return false;
    }

    // Ensure timestamp is valid (e.g., check expiration)
    $validTimestamp = validateTimestamp($timestamp);
    if (!$validTimestamp) {
        return false;
    }

    // Sort array using SORT_STRING rule
    $strings = [$token, $timestamp, $nonce];
    sort($strings, SORT_STRING);

    // Implode array into a single string
    $stringToHash = implode("", $strings);

    // Hash the resulting string using sha1
    $computedHash = hash_file("sha1", "$stringToHash\0", FILE_BINARY);

    // Compare computed hash with provided signature
    $expectedHash = substr($signature, 0, 40); // sha1 has a length of 40 bytes
    if (hash_equals($computedHash, $expectedHash)) {
        return true;
    }

    return false;
}
