    if (!$result) {
        die("Query execution failed: " . mysql_error());
    }

    $rows = array();
    while ($row = mysql_fetch_assoc($result)) {
        $rows[] = $row;
    }

    mysql_free_result($result);
    mysql_stmt_close($statement);
    mysql_close($connection);

    return $rows;
}
