    // Calculate text dimensions
    $textWidth = imageftwidth($font, strlen($text));
    $textHeight = imageftheight($font);

    // Calculate text position
    $x += ($textWidth + $padding) / 2;
    $y += ($textHeight + $padding);

    // Calculate image padding
    $paddingTop = ($height - ($textHeight + $padding)) / 2;
    $paddingLeft = ($width - ($textWidth + $padding)) / 2;

    // Clear image background
    imagefill($image, 0, 0, ImageColorAllocate($image, 255, 255, 255));

    // Add text to image
    imagefttext($image, $fontSize, $direction, $x, $y, $color, $font);

    // Free font resources
    imageftdestroy($font);

    // Add padding to image
    imagecopyresampled($image, $image, 0, 0, $paddingLeft, $paddingTop, $width + ($paddingLeft * 2), $height + ($paddingTop * 2), IMAGE_SRC, IMAGE_SCALE_DEFAULT);

