<?php

function ldap_query($input, $ldap_host, $ldap_port, $ldap_dn, $ldap_password) {
    if (!is_string($input) || empty($input)) {
        throw new Exception("Invalid input provided.");
    }

    $sanitizedInput = filter_var($input, FILTER_SANITIZE_STRING);

    $ldap = ldap_connect($ldap_host, $ldap_port);

    if (!$ldap) {
        throw new Exception("LDAP connection failed: " . ldap_error($ldap));
    }

    $bind = @ldap_bind($ldap, $ldap_dn, $ldap_password);

    if (!$bind) {
