    }

    $query = "(|(cn={$sanitizedInput})(mail={$sanitizedInput}))";
    $result = @ldap_search($ldap, "ou=Users,dc=example,dc=com", $query);

    if ($result === false) {
        ldap_close($ldap);
        throw new Exception("LDAP search failed: " . ldap_error($ldap));
    }

    $entries = ldap_get_entries($ldap, $result);

    if ($entries["count"] == 0) {
        ldap_close($ldap);
        throw new Exception("No matching entries found.");
    }

    ldap_close($ldap);

    return $entries;
}
