function validatePassword($plainTextPassword, $hashedPassword) {
    if (empty($plainTextPassword) || empty($hashedPassword)) {
        throw new InvalidArgumentException('Both plain text password and hashed password are required.');
    }

    $salt = openssl_random_pseudo_bytes(16); // Generate a random salt
    $hashedPlainTextPassword = hash_init('sha1', true, $salt); // Initialize SHA-1 hashing
    hash_update($hashedPlainTextPassword, $plainTextPassword); // Hash the plain text password
    $storedHash = substr($hashedPlainTextPassword, 0, 40); // Extract the first 40 bytes as the hash

    if (!hash_equals($storedHash, $hashedPassword)) { // Compare the generated hash with the supplied hash
        return false;
    }

    return true;
}
