import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;

public class SecureObject {
    private List<String> internalWhereClauses = new ArrayList<>();

    public void addWhereClause(String where, Object value) {
        if (value == null) {
            internalWhereClauses.add(where);
        } else {
            try {
                MessageDigest md = MessageDigest.getInstance("SHA-256"); // Use SHA-256 instead of SHA-1
                byte[] messageDigest = md.digest(value.toString().getBytes());
                String hashedName = String.format("%s", new Object[]{new String(MessageDigest.encode(messageDigest))});
                internalWhereClauses.add(String.format("%s==%s", where, hashedName));
            } catch (Exception e) {
                throw new RuntimeException("Error during hash generation", e);
            }
        }
    }

    // Add a method to return the internal array as a SQL query string
    public String getSQLQuery() {
        StringBuilder query = new StringBuilder();
        query.append("WHERE ");
        for (int i = 0; i < internalWhereClauses.size(); i++) {
            query.append(internalWhereClauses.get(i));
            if (i < internalWhereClauses.size() - 1) {
                query.append(" AND ");
            }
        }
        return query.toString();
    }
}
