<?php

function getDiskUsageInfo(): array {
    $dfPath = 'df';
    $availablePaths = explode(':', getenv('PATH'));

    if (!in_array($dfPath, $availablePaths)) {
        throw new RuntimeException('df command not found in the system PATH.');
    }

    $output = shell_exec("{$dfPath} --output=source,pcent --no-unit --quiet");
    $lines = explode("\n", $output);

    $diskUsageInfo = [];
    foreach ($lines as $line) {
        list($source, $usage) = explode(' ', $line);
        $diskUsageInfo[] = [
            'source' => $source,
            'usage_percent' => $usage,
        ];
    }

    return $diskUsageInfo;
}

