function getUserByUsernameAndPassword($pdo, $username, $password) {
    $stmt = $pdo->prepare("SELECT id, username, password, last_login, action_list, supplier_id FROM users WHERE username = :username");
    $stmt->bindParam(':username', $username);
    $stmt->execute();

    if ($stmt->rowCount() > 0) {
