function similarity_strings($str1, $str2) {
  $command = "python -c 'import sys, difflib; print(float(difflib.SequenceMatcher(None, sys.argv[1], sys.argv[2]).ratio()))'";
  $descriptorsSpec = array(
    0 => array("pipe", "r"), // stdin
    1 => array("pipe", "w"), // stdout
    2 => array("w", "/dev/null") // stderr
  );
  $process = proc_open($command, $descriptorsSpec, $pipes);

  if (is_resource($process)) {
    fwrite($pipes[0], "$str1\n$str2\n");
    fclose($pipes[0]);

    $output = stream_get_contents($pipes[1]);
    fclose($pipes[1]);

    proc_close($process);

    return (float) $output;
  }

  return -1; // Indicate error
}
```

