function validateUserInput($challenge, $userInput) {
    $remoteUrl = "https://your-remote-server.com/validate?challenge=" . urlencode($challenge);
    $remoteResponse = file_get_contents($remoteUrl);

    if ($remoteResponse === false) {
        throw new Exception("Failed to reach remote server.");
    }

    $remoteData = json_decode($remoteResponse, true);

    if ($remoteData === null) {
        throw new Exception("Invalid response format from remote server.");
    }

    if ($remoteData['status'] !== 'success') {
        throw new Exception("Remote server validation failed.");
    }

    $expectedAnswer = $remoteData['answer'];
    $calculatedAnswer = hash_hmac("sha256", $userInput, $challenge);

    if ($expectedAnswer !== $calculatedAnswer) {
        throw new Exception("User input is invalid.");
    }

    return "User input is valid.";
}
