function createTableAndQuery($db, $tableName, $columns, $primaryKey) {
    // Create table
    $query = "CREATE TABLE IF NOT EXISTS {$tableName} (";
    $firstColumn = true;
    foreach ($columns as $column) {
        if (!$firstColumn) {
            $query .= ", ";
        }
        $query .= "{$column['name']} {$column['type']}";
        if (in_array($column['name'], $primaryKey)) {
            $query .= " PRIMARY KEY";
        }
        $firstColumn = false;
    }
    $query .= ")";

    try {
        $db->exec($query);
    } catch (PDOException $e) {
        // Handle error
        return [];
    }

    // Query database
    $query = "SELECT * FROM {$tableName}";
    if (count($primaryKey) > 0) {
        $condition = "WHERE ";
        $firstCondition = true;
        foreach ($primaryKey as $key) {
            if (!$firstCondition) {
                $condition .= " AND ";
            }
            $condition .= "{$key} = ?";
            $firstCondition = false;
        }
        $query .= $condition;
    }

    $stmt = $db->prepare($query);
    $data = [];

    try {
        $stmt->execute($data);
        $result = $stmt->get_result();

        $rows = [];
        while ($row = $result->fetch_assoc()) {
            $rows[] = $row;
        }

        return $rows;
    } catch (PDOException $e) {
        // Handle error
        return [];
    } finally {
        $stmt->close();
    }
}
