function pingbackRemoteUrl($remoteUrl) {
    if (empty($remoteUrl)) {
        return "Error: Invalid remote URL.";
    }

    $parsedUrl = parse_url($remoteUrl);
    if (!isset($parsedUrl['host']) || !filter_var($parsedUrl['host'], FILTER_VALIDATE_IP)) {
        return "Error: Invalid remote host.";
    }

    $pingUrl = $remoteUrl . '/pingback.xml';
    if (strpos($remoteUrl, '/pingback.xml') !== false) {
        $pingUrl = $remoteUrl;
    }

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $pingUrl);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HEADER, false);
    curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
    curl_setopt($ch, CURLOPT_MAXREDIRS, 3);
    curl_setopt($ch, CURLOPT_ENCODING, 'gzip, deflate');
    curl_setopt($ch, CURLOPT_USERAGENT, 'MyPingbot/1.0');
    curl_setopt($ch, CURLOPT_TIMEOUT, 5);
    curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 5);

    $response = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);

    curl_close($ch);

    if ($httpCode != 200) {
        return "Error: Remote server returned HTTP code " . $httpCode;
    }

    $xml = simplexml_load_string($response);
    if ($xml === false) {
        return "Error: Remote response was not valid XML.";
    }

    $pingback = $xml->pingback;
    if (empty($pingback)) {
        return "Error: Remote server does not support pingbacks.";
    }

    $pingedUrls = getSessionVariable('pingedUrls') ?: [];
    if (in_array($remoteUrl, $pingedUrls)) {
        return "Error: Remote URL has already been pinged.";
    }

    addSessionVariable('pingedUrls', array_merge($pingedUrls, [$remoteUrl]));

    return "Success: Pingback to remote URL '$remoteUrl' completed.";
}

function getSessionVariable($name) {
    return isset($_SESSION[$name]) ? $_SESSION[$name] : false;
}

function addSessionVariable($name, $value) {
    $_SESSION[$name] = $value;
}
