async function loadScriptsAndMappingApi(publisherId, options) {
  try {
    const cdn1 = "https://cdn.example1.com/script.js";
    const cdn2 = "https://cdn.example2.com/script.js";
    const mappingApiCdn = "https://cdn.mappingapi.com/api.js";

    // Create and insert script tag for first CDN file
    const scriptTag1 = document.createElement("script");
    scriptTag1.src = cdn1;
    scriptTag1.type = "text/javascript";
    document.head.appendChild(scriptTag1);

    // Load first CDN file using fetch
    const response1 = await fetch(cdn1);
    if (!response1.ok) {
      throw new Error(`Error loading script from ${cdn1}`);
    }

    // Create and insert script tag for second CDN file
    const scriptTag2 = document.createElement("script");
    scriptTag2.src = cdn2;
    scriptTag2.type = "text/javascript";
    document.head.appendChild(scriptTag2);

    // Load second CDN file using fetch
    const response2 = await fetch(cdn2);
    if (!response2.ok) {
      throw new Error(`Error loading script from ${cdn2}`);
    }

    // Create and insert script tag for mapping API
    const mappingApiScriptTag = document.createElement("script");
    mappingApiScriptTag.src = mappingApiCdn;
    mappingApiScriptTag.type = "text/javascript";
    document.head.appendChild(mappingApiScriptTag);

    // Load mapping API using fetch
    const mappingApiResponse = await fetch(mappingApiCdn);
    if (!mappingApiResponse.ok) {
      throw new Error(`Error loading mapping API from ${mappingApiCdn}`);
