function install_octi_plugin($user_input) {
    // Validate user input
    if (empty($user_input) || !is_string($user_input)) {
        wp_die('Invalid user input.');
    }

    // Generate OTP
    $secret = wp_generate_password(32);
    $otp = generate_otp($secret);

    // Check if WooCommerce and OCTI plugins are installed
    if (!in_array('woocommerce/woocommerce.php', apply_filters('active_plugins', get_option('active_plugins')))) {
        wp_die('WooCommerce plugin not installed.');
    }
    if (!in_array('octi/octi.php', apply_filters('active_plugins', get_option('active_plugins')))) {
        wp_die('OCTI plugin not installed.');
    }

    // Validate MFA device registration
    $device_id = get_user_meta($current_user->ID, 'octi_device_id', true);
    if ($device_id === '') {
        wp_die('MFA device not registered.');
    }

    // Generate and save OTP for user
    update_user_meta($current_user->ID, 'octi_otp', $otp);
    update_user_meta($current_user->ID, 'octi_otp_secret', $secret);

    // Construct secure URL for OTP verification
    $verification_url = add_query_arg(
        array(
            'action' => 'octi_verify_otp',
            'user_id' => $current_user->ID,
            'otp' => $otp,
        ),
        admin_url('admin-ajax.php')
    );

    // Redirect user to OTP URL
    wp_redirect($verification_url);
    exit;
}

function generate_otp($secret) {
    $token = '';
    $factor_count = 10;
    $window = 30;

    for ($i = 0; $i < $factor_count; $i++) {
        $token .= substr(base_convert(crc32(time() . $secret . $i), 16, 10), -6);
    }

    $factor = array_slice($token, 0, $window);
    shuffle($factor);
    $otp = implode('', $factor);

    return $otp;
}
