function sortAndWriteLeaseRecordsToFile($leaseRecords, $sortField, $outputFile) {
    if (!is_array($leaseRecords) || empty($leaseRecords)) {
        throw new InvalidArgumentException("Invalid leaseRecords input.");
    }

    if (!is_string($sortField) || !in_array($sortField, array_keys(current($leaseRecords)))) {
        throw new InvalidArgumentException("Invalid sortField input.");
    }

    usort($leaseRecords, function ($a, $b) use ($sortField) {
        return strcmp($a[$sortField], $b[$sortField]);
    });

    $fileHandler = fopen($outputFile, "w");

    if (!$fileHandler) {
        throw new RuntimeException("Failed to open output file for writing.");
    }

    foreach ($leaseRecords as $record) {
        $data = json_encode($record, JSON_PRETTY_PRINT);
        fwrite($fileHandler, $data . PHP_EOL);
    }

    fclose($fileHandler);

    // Use a standard boolean getter method to ensure a primitive boolean value is returned
    $serviceEnabled = filter_get_args(func_get_args())[3];

    if ($serviceEnabled) {
        restartService();
    }
}
