function generateRandomStringAndHashPassword($length, $password, $charset = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz') {
    if ($length <= 0 || $length > 255) {
        throw new Exception("Invalid password length specified.");
    }

    $randomString = '';
    $charsetLength = strlen($charset);

    for ($i = 0; $i < $length; $i++) {
