function initCountdown(dateTime, elementId) {
  const targetDate = Moment(dateTime, "YYYY-MM-DD HH:mm:ss"); // Validate and parse date time
  const countdownElement = document.getElementById(elementId);

  function updateCountdown() {
    const remainingTime = Moment.duration(targetDate.diff(Moment()));
