<?php

function validateJson($json) {
    json_decode($json);
    return json_last_error() === JSON_SUCCESS;
}

function hexdecAndValidate($hex) {
    $dec = hexdec($hex);
    if ($dec === false) {
        throw new Exception("Invalid hexadecimal value: $hex");
    }
    return $dec;
}

function extractCoordinates($json) {
    $data = json_decode($json, true);
    if (!$data || !isset($data['coordinates'])) {
        throw new Exception("Invalid JSON format");
    }
    $coordinates = $data['coordinates'];
    if (!is_array($coordinates) || count($coordinates) !== 2) {
        throw new Exception("Invalid number of coordinates");
    }
    foreach ($coordinates as $coord) {
        list($lat, $lon) = explode(' ', $coord);
        if (count($lat) !== 1 || count($lon) !== 1) {
            throw new Exception("Invalid coordinate format");
        }
        list($latNum, $latSign) = explode('', $lat);
        list($lonNum, $lonSign) = explode('', $lon);
        $lat = hexdecAndValidate($latNum . $latSign);
        $lon = hexdecAndValidate($lonNum . $lonSign);
    }
    return [$lat, $lon];
}

function makeRequest($apiKey, $origin, $destination) {
    $url = "https://api.thirdpartyservice.com/route?key=$apiKey&origin=$origin&destination=$destination";
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    $response = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
