<?php

function processFormSubmission($api_url, $session, $comment, $redirect_url) {
    // Validate and sanitize user input
    $comment = filter_var($comment, FILTER_SANITIZE_STRING);

    // Create a new comment using the API
    $data = [
        'comment' => $comment
    ];
    $options = [
        'http' => [
            'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
            'method'  => 'POST',
            'content' => http_build_query($data),
        ],
    ];
    $context  = stream_context_create($options);
    $result = file_get_contents($api_url, false, $context);

    if ($result === false) {
        // Set error message in session and redirect to error page
        $session['error'] = 'Error communicating with API';
        header('Location: error.php');
        exit;
    }

    $api_response = json_decode($result, true);

    if (isset($api_response['error'])) {
        // Set error message in session and redirect to error page
        $session['error'] = $api_response['error'];
        header('Location: error.php');
        exit;
    }

    // Store comment ID and success message in session
    $session['comment_id'] = $api_response['id'];
    $session['message'] = 'Comment created successfully';

    // Redirect to specified URL
    header('Location: ' . $redirect_url);
}
