function secureHash($input) {
  if (empty($input)) {
    throw new InvalidArgumentException('Input string cannot be empty.');
  }

  $output = '';
  $context = hash_init(hash_algos() ['sha256'], HASH_HMAC, key_bytes: 32); // Use a secure key for HMAC
  $data = str_pad($input, 64, "\x00"); // Pad input to a fixed length for hash function

  // Process input in chunks to avoid memory issues
  for ($i = 0; $i < strlen($data); $i += 64) {
    hash_update($context, substr($data, $i, 64));
  }

  $output = bin2hex(hash_final($context, false)); // Get raw binary hash data and convert it to hexadecimal string

  return $output;
}
```

