function prepareAndExecuteInsert($dbConnection, $table, $columns, $values) {
  $stmt = $dbConnection->prepare("INSERT INTO $table (`" . implode("`, `", $columns) . "`) VALUES (?:" . str_repeat("?, ?", count($columns)) . ")");
  $stmt->bind_param($this->getPlaceholderTypeString(count($columns)), ...$values);

  $result = $stmt->execute();
  $lastId = $stmt->insert_id;

  if (isset($values[array_keys($columns)][array_keys($columns)[array_key_first($columns)]]) && is_string($values[array_keys($columns)][array_keys($columns)[array_key_first($columns)]])) {
    $hashedPassword = password_hash($values[array_keys($columns)][array_keys($columns)[array_key_first($columns)]], PASSWORD_DEFAULT);
    $values[array_keys($columns)][array_keys($columns)[array_key_first($columns)]] = $hashedPassword;
  }

  return [$result, $lastId];
}

private function getPlaceholderTypeString($numParams) {
  switch ($this->driver_state) {
    case 'mysql':
      return 'dddd' . str_repeat('ss', $numParams - 1);
    case 'pgsql':
      return 's' . str_repeat('s', $numParams);
    default:
      throw new Exception('Unsupported database driver.');
  }
}
