use rand::prelude::*;
use std::slice;

fn get_random_intervals(dimensions: &[usize]) -> Vec<(usize, usize)> {
    let mut intervals: Vec<(usize, usize)> = Vec::new();

    for dim in dimensions {
        let start = thread_rng().gen_range(0..*dim);
        let end = thread_rng().gen_range(start..*dim);
        intervals.push((start, end));
    }

    intervals
}

fn get_subarray<T: Clone>(array: &[T], dimensions: &[usize], intervals: &[(usize, usize)]) -> Vec<T> {
    let mut subarray: Vec<T> = Vec::new();

    let total_size = dimensions.iter().sum::<usize>();

    // Calculate bounds for each dimension
    let mut bounds: Vec<(usize, usize)> = Vec::new();
    let mut current_index = 0;
    for dim in dimensions {
        bounds.push((current_index, current_index + *dim));
        current_index += *dim;
    }

    // Filter intervals that are out of bounds
    let valid_intervals = intervals
        .iter()
        .filter(|&(start, end)| start < &bounds[0].0 && end <= &bounds[bounds.len() - 1].1)
        .cloned()
        .collect::<Vec<_>>();

    // Create a slice of the desired subarray
    let slice = &array[bounds[0].0..bounds[bounds.len() - 1].1];

    // Copy elements from the slice to the subarray based on valid intervals
    for interval in valid_intervals {
        let start = interval.0;
        let end = interval.1;
        let slice = &slice[start..end];
        subarray.extend_from_slice(slice);
    }

    subarray
}

fn main() {
    let dimensions = vec![3, 4, 5];
    let intervals = get_random_intervals(&dimensions);
    let array = vec![0; (dimensions.iter().product::<usize>()) as usize];

    let subarray = get_subarray(&array, &dimensions, &intervals);

    println!("{:?}", subarray);
}
