import random

def random_sample(population, num_samples=1, replacement=False):
    if num_samples < 0:
        raise ValueError("Number of samples cannot be negative.")
    if not population:
        return []

    max_samples = int(len(population) * (1 + 3 * (2.3 ** 2)))  # 3 standard deviations from population size
    if num_samples > max_samples:
        raise ValueError("Number of samples exceeds the maximum allowed value.")

    random.shuffle(population)

    samples = []
    for _ in range(num_samples):
        if not replacement:
            if not population:
                break
            sample = population.pop(0)
        else:
            sample = random.choice(population)
        samples.append(sample)

    return samples
