void generate_packet(packet_t *packet) {
    int protocol, src_port, dst_port;
    struct sockaddr_in src_addr, dst_addr;

    src_addr.sin_family = AF_INET;
    src_addr.sin_port = htons(rand() % MAX_PORTS + 1024);
