import feedparser
import random
import time

class FeedChecker:
    def __init__(self):
        self.url_attempts = {}

    def check_feed(self, url):
        if url in self.url_attempts and self.url_attempts[url] >= 3:
            print(f"Error: Failed to parse feed from {url} after 3 attempts.")
            return

        try:
            feed = feedparser.parse(url)
            if feed.status == 200:
                self.url_attempts[url] = 0
                print(f"URL: {url}")
                print(f"Title: {feed.title}")
                print(f"Description: {feed.description}")
                print(f"Published: {feed.published}")
                print(f"Entries: {len(feed.entries)}")
                return
        except Exception as e:
            self.url_attempts[url] = self.url_attempts.get(url, 0) + 1
            print(f"Error parsing feed from {url}: {str(e)}")
            time.sleep(random.randint(1, 10))
            return self.check_feed(url)

if __name__ == "__main__":
    urls = ["http://example.com/feed1.xml", "http://example.com/feed2.xml", "http://example.com/invalid_feed.xml"]
    checker = FeedChecker()
    for url in urls:
        checker.check_feed(url)
