def create_postgres_db_and_user(connection_config, db_name, user=None):
    if check_db_or_user_exists(connection_config, db_name, user):
        raise ValueError("db or user already exists")

    with psycopg2.connect(**connection_config) as conn:
        with conn.cursor() as cur:
            try:
