                )
                conn.commit()
            except psycopg2.ProgrammingError as e:
                conn.rollback()
                raise ValueError(e)

def check_db_or_user_exists(connection_config, db_name, user=None):
    with psycopg2.connect(**connection_config) as conn:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            if user:
                cur.execute("SELECT COUNT(*) FROM pg_roles WHERE rolname = %s;", (user,))
                existing_user = cur.fetchone()["count"]
                if existing_user > 0:
                    return True
            cur.execute("SELECT COUNT(*) FROM pg_database WHERE datname = %s;", (db_name,))
            existing_db = cur.fetchone()["count"]
            if existing_db > 0:
                return True
    return False
