import importlib.abc
import importlib.util

def set_dynamic_loading_flags(modules):
    original_flags = {}
    for module_name in modules:
        if module_name in sys.modules:
            original_flags[module_name] = sys.modules[module_name].__spec__ and sys.modules[module_name].__spec__.loader

    for module_name in modules:
        if module_name not in sys.modules:
            spec = importlib.util.find_spec(module_name)
            if not spec or not spec.origin:
                continue
            loader = importlib.abc.Loader() if spec.origin is None else spec.origin
            if loader is not None:
                sys.modules[module_name] = importlib.util.module_from_spec(spec)
                sys.modules[module_name].__spec__ = spec
                sys.modules[module_name]._loader = loader
                sys.modules[module_name].__dict__['__loader__'] = loader

def import_modules(modules):
    for module_name in modules:
        __import__(module_name)

def restore_dynamic_loading_flags():
    for module_name, original_loader in original_flags.items():
        if module_name in sys.modules:
            sys.modules[module_name]._loader = original_loader
            del sys.modules[module_name].__dict__['__loader__']

def main():
