import random

def rearrange_list(input_list, fazas_state):
    subset_size = int(len(input_list) * 0.5) if fazas_state else int(len(input_list) * 0.3)
    subset = random.sample(input_list, subset_size)

    if fazas_state:
        # Remove elements from the subset
        for _ in range(random.randint(1, len(subset))):
            index = random.randint(0, len(subset) - 1)
            subset.pop(index)
    else:
        # Add elements to the subset
        elements_to_add = random.sample(range(1, 51), random.randint(1, len(input_list) // 2))
        subset += list(elements_to_add)

    # Add or remove elements from the input list based on the subset
    if fazas_state:
        for element in subset:
            input_list.remove(element)
    else:
        for element in elements_to_add:
            input_list.append(element)

    return input_list
