import gzip
import re
import os
import sys

def check_valid_directory(directory):
    if not os.path.isdir(directory):
        raise ValueError(f"Invalid directory: {directory}")

def convert_gff3_to_gtf(input_file, output_file, dialect):
    if not input_file.endswith(".gff.gz") and not input_file.endswith(".gff"):
        raise ValueError("Input file must be a gzipped or plain GFF3 file.")

    gff3_lines = []
    if input_file.endswith(".gff.gz"):
        with gzip.open(input_file, "rt") as f:
            gff3_lines = f.readlines()
    else:
        with open(input_file, "r") as f:
            gff3_lines = f.readlines()

    gtf_lines = []

    for line in gff3_lines:
        fields = line.strip().split("\t")
        if len(fields) < 9:
            continue

        chrom, start, end, strand, gene_id, gene_name, gene_type, exon_start, exon_end = fields

        if dialect == "ensembl":
            source = "gff-3"
            feature = "exon"
            strand = "-" if strand == "." else "+"
            gtf_line = f"{source}\t{chrom}\t{int(start)-1}\t{int(start)-1}\t.\t{feature}\t.\t.\t{gene_id}\t.\t.\t{strand}"
            gtf_lines.append(gtf_line)

            if int(start) != int(exon_start) or int(end) != int(exon_end):
                gtf_line = f"{source}\t{chrom}\t{int(exon_start)-1}\t{int(exon_end)-1}\t.\t{feature}\t.\t.\t{gene_id}\t.\t.\t{strand}"
                gtf_lines.append(gtf_line)

        elif dialect == "hg19":
            source = "gff-3"
            feature = "exon"
            chrom = re.sub(r"^chr|:", "", chrom)
            strand = "-" if strand == "." else "+"
            gtf_line = f"{source}\t{chrom}\t{int(start)}\t{int(end)}\t.\t{feature}\t.\t.\t{gene_id}\t.\t.\t{strand}"
            gtf_lines.append(gtf_line)

            if int(start) != int(exon_start) or int(end) != int(exon_end):
                gtf_line = f"{source}\t{chrom}\t{int(exon_start)}\t{int(exon_end)}\t.\t{feature}\t.\t.\t{gene_id}\t.\t.\t{strand}"
                gtf_lines.append(gtf_line)

        else:
            raise ValueError("Invalid dialect.")

    with open(output_file, "w") as f:
        f.writelines(gtf_lines)

def validate_input_output_files(input_file, output_file):
    if not os.path.isfile(input_file):
        raise FileNotFoundError(f"Input file '{input_file}' does not exist.")

    if os.path.exists(output_file) and os.path.isfile(output_file):
        raise FileExistsError(f"Output file '{output_file}' already exists.")

def main():
    if len(sys.argv) != 5:
        print("Usage: python gff3_to_gtf.py <input_file> <output_file> <dialect>")
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2]
    dialect = sys.argv[4]

