#include <iostream>
#include <string>
#include <memory> // for unique_ptr
#include <openssl/sha.h>

class Hash {
public:
    Hash(const std::string& input, const std::string& algorithm = "sha256")
        : input_(input), algorithm_(algorithm) {
        if (algorithm_ != "sha256" && algorithm_ != "sha3-224" &&
            algorithm_ != "sha3-256" && algorithm_ != "sha3-384" &&
            algorithm_ != "sha3-512") {
            throw std::invalid_argument("Invalid hash algorithm: " + algorithm_);
        }

        // Initialize hash context
        hash_ = std::unique_ptr<unsigned char, decltype(&EVP_SHA1_free)>(
            EVP_SHA(algorithm_.c_str(), 0, nullptr), &EVP_SHA1_free);

        // Initialize hash value
        SHA_Init(hash_.get());
        SHA_Update(hash_.get(), input_.size(), input_.data());
    }

    std::string get_hash() const {
        unsigned char hash[SHA_DIGEST_LENGTH];
        SHA_Final(hash, hash_.get());

        std::string result;
        for (size_t i = 0; i < SHA_DIGEST_LENGTH; ++i) {
            result += std::hex(static_cast<int>(hash[i]) < 0 ?
                              std::to_string(-static_cast<unsigned int>(hash[i])) :
                              std::to_string(static_cast<int>(hash[i])));
        }
        return result;
    }

    std::unique_ptr<Hash> clone() const {
        // Create a new Hash object with the same input and algorithm
        return std::make_unique<Hash>(input_, algorithm_);
    }

private:
    std::string input_;
    std::string algorithm_;
    std::unique_ptr<unsigned char, decltype(&EVP_SHA1_free)> hash_;
};
```

