#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>

#define MAX_RETRIES 5
#define INITIAL_SLEEP 1
#define MAX_SLEEP 5
#define SLEEP_FACTOR 1

int terminate_process(pid_t pid) {
    int status;
    int ret = -1;
    int sleep_time = INITIAL_SLEEP;

    if (kill(pid, SIGTERM) == 0) {
        printf("Process %d terminated successfully.\n", (int)pid);
        ret = 0;
    } else if (errno != ESRCH) {
        perror("Error terminating process");
        goto error;
    }

    for (int i = 0; i < MAX_RETRIES; i++) {
        if (waitpid(pid, &status, WNOHANG) > 0) {
            if (WIFEXITED(status)) {
                printf("Process %d terminated with exit code %d.\n", (int)pid, WEXITSTATUS(status));
                ret = WEXITSTATUS(status);
                break;
            } else if (WIFSIGNALED(status)) {
                printf("Process %d terminated by signal %d.\n", (int)pid, WTERMSIG(status));
                ret = WTERMSIG(status);
                break;
            }
        }

        if (ret >= 0) {
            break;
        }

        usleep(sleep_time * 1000000);
        sleep_time *= (1 + SLEEP_FACTOR);

        if (sleep_time > MAX_SLEEP * 1000000) {
            printf("Failed to terminate process %d after %d seconds.\n", (int)pid, MAX_SLEEP + 1);
            ret = -1;
            break;
        }
    }

    if (ret < 0) {
        printf("Failed to terminate process %d.\n", (int)pid);
        goto error;
    }

    return ret;

error:
    return ret;
}
