import shelve
import json

def init_shelve(filename):
    try:
        return shelve.open(filename)
    except FileExistsError:
        shelve.open(filename, flag='n', writeback=True)
        return shelve.open(filename)

def create_filter(filter_name, data_type, data):
    if not isinstance(data_type, str) or data_type not in ["int", "float", "str"]:
        raise TypeError("Invalid data type. Expected string: 'int', 'float' or 'str'")

    filter = {"name": filter_name, "data_type": data_type, "data": data}
    shelve_obj = init_shelve("filters.db")
    shelve_obj["filters"] = shelve_obj.get("filters", []) + [filter]
    shelve_obj.close()

def get_filter(filter_name):
    shelve_obj = init_shelve("filters.db")
    filters = shelve_obj.get("filters", [])
    filter = next((filter for filter in filters if filter["name"] == filter_name), None)
    shelve_obj.close()
    return filter

def delete_filter(filter_name):
    shelve_obj = init_shelve("filters.db")
    filters = shelve_obj.get("filters", [])
    index = next((index for index, filter in enumerate(filters) if filter["name"] == filter_name), -1)
    if index >= 0:
        del filters[index]
        shelve_obj["filters"] = filters
        shelve_obj.close()
        shelve_obj = init_shelve("filters.db")
        filters = shelve_obj.get("filters", [])
    return None if index < 0 else filter

def validate_data(filter, data):
    if filter is None:
        raise ValueError("Filter not found")
    if filter["data_type"] == "int":
        return isinstance(data, int)
    elif filter["data_type"] == "float":
        return isinstance(data, float)
    elif filter["data_type"] == "str":
        return isinstance(data, str)
    else:
        raise TypeError("Invalid data type. Expected int, float or str")

def record_data(filter_name, data):
    filter = get_filter(filter_name)
    if filter is None:
        create_filter(filter_name, "str", data)
        filter = get_filter(filter_name)
    validate_data(filter, data)
    shelve_obj = init_shelve("filters.db")
    filters = shelve_obj.get("filters", [])
    index = next((index for index, filter in enumerate(filters) if filter["name"] == filter_name), -1)
    filters[index]["data"] = data
    shelve_obj["filters"] = filters
    shelve_obj.close()

def playback_data(filter_name):
    filter = get_filter(filter_name)
    if filter is None:
        raise ValueError("Filter not found")
    shelve_obj = init_shelve("filters.db")
    filters = shelve_obj.get("filters", [])
    index = next((index for index, filter in enumerate(filters) if filter["name"] == filter_name), -1)
    data = filters[index]["data"]
    shelve_obj.close()
    return json.loads(json.dumps(data))
