def read_mesh_from_shelf(shelf_file):
    try:
        shelf = shelve.open(shelf_file)
        mesh_data = shelf['mesh_data']
        shelf.close()
        return mesh_data
    except FileNotFoundError:
        print(f"Error: Shelf file '{shelf_file}' not found.")
        return None

