import os
import re

def get_env_var(name, default=None):
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise RuntimeError(f"Environment variable '{name}' not set")

    value = value.lower()
    if not re.match(r'^(true|false)$', value):
        raise RuntimeError(f"Unrecognized value '{value}' for environment variable '{name}'")

    return value == "true"

