CREATE FUNCTION create_and_lock_table(p_lock_name VARCHAR)
RETURNS INT
BEGIN
  DECLARE table_name VARCHAR(255);
  DECLARE index_name VARCHAR(255);
  DECLARE unique_name VARCHAR(255);
  DECLARE i INT DEFAULT 0;

  -- Create table with auto-incrementing primary key
  SET @sql = CONCAT('CREATE TABLE IF NOT EXISTS test_table (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) UNIQUE, UNIQUE KEY (name) )');
  PREPARE stmt FROM @sql;
  EXECUTE stmt;
  DEALLOCATE PREPARE stmt;

