  PREPARE stmt FROM @sql;
  EXECUTE stmt;
  DEALLOCATE PREPARE stmt;

  -- Acquire write lock on the table using given lock name
  SET @sql = CONCAT('LOCK TABLES test_table WRITE, test_table_index USING ', p_lock_name);
  PREPARE stmt FROM @sql;
  EXECUTE stmt;
  DEALLOCATE PREPARE stmt;

  -- Insert third row with non-unique name
  SET @sql = CONCAT('INSERT INTO test_table (name) VALUES ("Name1")');
  DECLARE continue_loop CONTINUE HANDLER FOR SQLSTATE '40001' DO
