```python
import sqlite3

def get_row_counts(table_names):
    """
    Returns a dictionary with table names as keys and corresponding number of rows as values.
    Raises an error if any table has zero rows or if tables have different schemas.

    @param table_names: list of table names
    @return: dictionary with table names as keys and number of rows as values
    """

    # Initialize database connection
    conn = sqlite3.connect("database.db")

    try:
        # Create a cursor object
        cursor = conn.cursor()

        # Store initial schema information
        initial_schema = {}
        for table_name in table_names:
            cursor.execute(f"PRAGMA table_info({table_name});")
            schema_info = cursor.fetchall()
            initial_schema[table_name] = schema_info

        row_counts = {}

        # Retrieve row counts for each table
        for table_name in table_names:
            cursor.execute(f"SELECT COUNT(*) FROM {table_name};")
            row_count = cursor.fetchone()[0]
            row_counts[table_name] = row_count

        # Check if any table has zero rows
        if any(row_count == 0 for row_count in row_counts.values()):
            raise ValueError("One or more tables have zero rows.")

        # Check if all tables have the same schema
        for table1, schema1 in initial_schema.items():
            for table2, schema2 in initial_schema.items():
                if table1 != table2:
                    if schema1 != schema2:
                        raise ValueError("Tables have different schemas.")

        # Close the cursor and connection
        cursor.close()
        conn.close()

        return row_counts

    except sqlite3.Error as error:
        # Close the cursor and connection in case of an error
        cursor.close()
        conn.close()

        raise error
