```python
import os
import re
import shelve
import urllib.parse
import stemmer

class InvertedIndex:
    def __init__(self):
        self.invertedIndex = {}
        self.forwardIndex = {}
        self.idToUrl = {}

def build_index(index, directory_path):
    index.invertedIndex = {}
    index.forwardIndex = {}
    index.idToUrl = {}

    for entry in os.scannedirs(directory_path):
        if not entry.is_dir:
            file_path = os.path.join(directory_path, entry.name)
            document_id = os.path.splitext(entry.name)[0]
            url = urllib.parse.urljoin(directory_path, entry.name)

            index.idToUrl[document_id] = url

            with open(file_path, 'r') as file:
                text = file.read()
                parsed_text = preprocess_text(text)
                index.forwardIndex[document_id] = parsed_text

                for term in parsed_text:
                    stemmed_term = stemmer.stem(term)
                    if stemmed_term in index.invertedIndex:
                        index.invertedIndex[stemmed_term].append(document_id)
                    else:
                        index.invertedIndex[stemmed_term] = [document_id]

def preprocess_text(text):
    words = re.findall(r'\w+', text.lower())
    return words

def startIndexer():
    index = InvertedIndex()
    index.shelf = shelve.open('index.db')
    build_index(index, os.getcwd())
    return index

def finishIndexer(index):
    index.shelf.close()

if __name__ == '__main__':
    index = startIndexer()
    finishIndexer(index)
```

