import os
import json
from BundleContext import BundleContext

def get_image_types():
    try:
        with open("image_cache.json", "r") as file:
            return json.load(file)
    except FileNotFoundError:
        return {"bundle_name": image_type for image_type in ["png", "jpeg", "bmp"]}

def search_images(bundle_name, image_types):
    bundle_context = BundleContext(bundle_name)
    images = []

    for entry in bundle_context.getEntries():
        if not entry.isDirectory:
            file_extension = os.path.splitext(entry.name)[1]
            if file_extension.lower() in image_types:
                images.append(entry.path)

    return images

def find_images_in_bundle(bundle_name, image_types):
    image_cache = get_image_types()
    image_cache.update({bundle_name: image_types})
    with open("image_cache.json", "w") as file:
        json.dump(image_cache, file)

    bundle_images = search_images(bundle_name, image_types)
    return bundle_images
