#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <mercurial.h>
#include <mercurial/i18n.h>
#include <mercurial/strutil.h>
#include <mercurial/error.h>
#include <mercurial/log.h>
#include <mercurial/node.h>
#include <mercurial/hash.h>
#include <mercurial/util.h>
#include <mercurial/i18n.h>
#include <stdbool.h>

typedef struct commit_parent {
    struct hg_node parent_node;
    int branch_count;
} commit_parent;

void escape_output(const char *input, char *output, size_t size) {
    size_t i = 0;
    while (i < size) {
        if (input[i] == '\n') {
            output[i] = '\\';
            i++;
            output[i++] = 'n';
        } else {
            output[i] = input[i];
            i++;
        }
    }
    output[i] = '\0';
}

bool is_branch(const struct hg_node node, const char *branch_prefix) {
    size_t prefix_len = strlen(branch_prefix);
    size_t node_len = strlen(node_to_hex(node));
    if (node_len < prefix_len) {
        return false;
    }
    return strncmp(node_to_hex(node), branch_prefix, prefix_len) == 0;
}

void count_branches(struct hg_state *state, struct hg_node node, int depth, int *branch_count) {
    commit_parent parent;
    int parent_branch_count;

    if (hg_log_parents(state, node, 1, &parent.parent_node, NULL, NULL, NULL, NULL) < 0) {
        *branch_count = depth;
        return;
    }

    parent_branch_count = 0;
    if (is_branch(parent.parent_node, "default")) {
        parent_branch_count = 1;
    }

    count_branches(state, parent.parent_node, depth + 1, &parent_branch_count);
    *branch_count = depth + parent_branch_count;

    hg_release(state);
}

int main(int argc, char *argv[]) {
    int ret = EXIT_FAILURE;
    struct hg_state *state;
    struct hg_node tip;
    int branch_count;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <repository>\n", argv[0]);
        return EXIT_FAILURE;
    }

    state = hg_init(argv[1], NULL, HG_INIT_QUIET);
    if (!state) {
        fprintf(stderr, "Failed to initialize repository: %s\n", hg_strerror(errno));
        return EXIT_FAILURE;
    }

    if (hg_tip(state, &tip) < 0) {
        fprintf(stderr, "Failed to get repository tip: %s\n", hg_strerror(errno));
        hg_release(state);
        return EXIT_FAILURE;
    }

    count_branches(state, tip, 0, &branch_count);

    printf("Number of branches at tip: %d\n", branch_count);

    hg_release(state);
    ret = EXIT_SUCCESS;

    return ret;
}
