import psycopg2.extras

def get_column_values(table_name, where_clause, column_name, db_connection):
    """
    Retrieves a list of values for the specified column from the given table,
    filtered by the provided where clause.

    @param table_name: The name of the table to query.
    @param where_clause: The filtering condition for the query.
    @param column_name: The name of the column to retrieve values from.
    @param db_connection: An established database connection.
    @return: A list of values for the specified column.
    """

    with db_connection.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cursor:
        query = f"SELECT {column_name} FROM {table_name} WHERE {where_clause};"
        cursor.execute(query)

        results = cursor.fetchall()
        column_values = [result[column_name] for result in results]

        return column_values
