```python
import os
import hashlib

def get_file_hash(file_path, max_bytes=None):
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File '{file_path}' does not exist.")

    try:
        file_size = os.path.getsize(file_path)
        if max_bytes and file_size > max_bytes:
            raise ValueError(f"File size ({file_size} bytes) exceeds maximum allowed bytes ({max_bytes}).")

        with open(file_path, "rb") as file:
            if max_bytes:
                content = file.read(max_bytes)
            else:
                content = file.read()

            hash_obj = hashlib.sha1(content)
            hexadecimal_hash = hash_obj.hexdigest()

    except (FileNotFoundError, ValueError) as e:
        raise e
    except Exception as e:
        raise RuntimeError(f"An error occurred while calculating the hash of file '{file_path}': {str(e)}")

    return hexadecimal_hash
