import json
import boto3
import os

class InputIterator:
    def __init__(self, file_path=None, bucket_name=None, fail_on_missing=False):
        self.file_path = file_path
        self.bucket_name = bucket_name
        self.fail_on_missing = fail_on_missing

    def __iter__(self):
        if self.file_path:
            self.file = open(self.file_path, 'r')
            return self

        if not self.bucket_name or not self.fail_on_missing:
            self.s3 = boto3.client('s3')
            self.object = self.s3.get_object(Bucket=self.bucket_name)
            self.data = json.load(self.object['Body'])
            return self

        raise FileNotFoundError("File or bucket not found")

    def __next__(self):
        if self.file:
            return json.load(self.file).pop(0)

        return next(self.data)

    def to_json(self, obj):
        return json.dumps(obj)

    def from_json(self, json_str):
        return json.loads(json_str)
