            if response.status != 200:
                raise HTTPError(response.reason, response.status, response.read().decode())
        except (HTTPError, URLError, ContentDecodingError, BadStatusLine, IncompleteRead, UnsupportedHTTPVersion):
            raise

def authenticate(url, username, password):
