def gb_to_kib(size_gb: int) -> str:
    # Validate input
    if size_gb <= 0:
        raise ValueError("Size must be a positive number in gigabytes")

    size_kib = int(size_gb * 1024 ** 3)
    format_str = "{} {}KiB"

    # Ensure buffer size is consistent and validated
    buffer_size = len(format_str) + len(str(size_kib))
    if buffer_size > len(format_str):
        raise MemoryError("Buffer size too small")

    return format_str.format(size_kib)
