-- Begin function definition
CREATE OR REPLACE FUNCTION rename_column_and_add_new(
  table_name TEXT,
  old_column_name TEXT,
  new_column_name TEXT,
  field_object JSONB
) RETURNS VOID AS $$
DECLARE
  new_column_type TEXT;
  new_column_constraints TEXT;
  column_exists BOOLEAN;
  constraint_exists BOOLEAN;
BEGIN
  -- Check if old column exists
  EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_name = table_name
      AND column_name = old_column_name
  ) INTO column_exists;

  -- If old column does not exist, return
  IF NOT column_exists THEN
    RETURN;
  END IF;

  -- Extract new column type and constraints from field_object
  new_column_type := (field_object->>'type')::TEXT;
  new_column_constraints := field_object->>'constraints'::TEXT;

  -- Drop old column constraint (if exists)
  IF (new_column_constraints IS NOT NULL) THEN
    EXECUTE format('ALTER TABLE %I DROP CONSTRAINT %I ON %I %s;', table_name,
                   old_column_name, table_name, new_column_name);
  END IF;

  -- Rename old column
  EXECUTE format('ALTER TABLE %I RENAME COLUMN %I TO %I;', table_name,
                 old_column_name, new_column_name);

  -- Add new column with given type and constraints
  EXECUTE format('ALTER TABLE %I ADD COLUMN %I %s;', table_name, new_column_name,
                 new_column_type);

  -- Set new column constraints (if provided)
  IF (new_column_constraints IS NOT NULL) THEN
    EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I %s ON %I %s;', table_name,
                   new_column_name, new_column_constraints, table_name, new_column_name);
  END IF;
END;
$$ LANGUAGE plpgsql;
