import psycopg2.extras.RealDictCursor
class UserRegistration:
    def __init__(self, db_config):
        self.db_config = db_config
        self.conn = None
        self.cursor = None

    def register_user(self, user):
        try:
            self.connect()
            self.cursor.execute("BEGIN")
            self.cursor.execute("INSERT INTO UserTable (username, password, email, role) VALUES (%s, %s, %s, %s)", (user["username"], user["password"], user["email"], user["role"]))
            self.conn.commit()
            print("Registration Successful")
        except psycopg2.IntegrityError as e:
            if "unique key" in str(e):
                self.handle_username_exists(user)
            else:
                raise e
        finally:
            self.cursor.execute("COMMIT")
            self.close()

    def handle_username_exists(self, user):
        print("Error: Username already exists.")
        raise UsernameAlreadyExistsException

    def connect(self):
        self.conn = psycopg2.connect(**self.db_config)
        self.cursor = self.conn.cursor(cursor_factory=RealDictCursor)

    def close(self):
        self.cursor.close()
        self.conn.close()

class UsernameAlreadyExistsException(Exception):
    pass

