RETURNS VOID AS $$
DECLARE
	trigger_name text;
	query text;
	pg_language *lang;
	exists boolean;
	new_lang oid;
BEGIN
	-- Drop existing triggers with the specified naming convention
	EXECUTE 'DROP TRIGGER IF EXISTS ' || quote_ident(table_name) || '_' || quote_ident(trigger_prefix) || '%' || ' ON ALL';

	-- Check if the required language exists and install it if necessary
	lang := pg_language_for_name('plpgsql');
	IF NOT EXISTS (SELECT * FROM pg_language WHERE lanname = 'plpgsql') THEN
