		trigger_name := quote_ident(table_name) || '_' || quote_ident(trigger_prefix) || '_' || cast(row.id AS text);
		query := 'CREATE TRIGGER ' || trigger_name || ' BEFORE INSERT ON ' || quote_ident(table_name) || ' FOR EACH ROW EXECUTE PROCEDURE your_function_name_here();';
		EXECUTE query;
	END LOOP;
END;
$$ LANGUAGE plpgsql;
