import sqlalchemy as sa

def get_table_columns(table_name, columns=None, named_tuples=False, engine):
    try:
        query = sa.text("SHOW COLUMNS FROM {}".format(table_name))
        if columns:
            query = query.where(sa.text("COLUMN_NAME IN :columns"))
            stmt = sa.text(query).bindparams(columns=sa.bindparam("columns"))
        else:
            stmt = sa.text(query)

        result = engine.execute(stmt)

        if named_tuples:
            column_names = [desc[0] for desc in result.keys()]
            return [sa.namedtuple("Column", column_names)(*row) for row in result]
        else:
            return [row for row in result]
    except sa.exc.SQLAlchemyError as e:
        print("Error while fetching columns: {}".format(e))
        return None
