import json

def json_deserialize(json_str: str, decode_keys: bool = False) -> dict:
    try:
        json_obj = json.loads(json_str)
        if decode_keys:
            for key in json_obj:
                if isinstance(key, str) and key.isdigit():
                    json_obj[key] = json.loads(json_obj[key])
