import sys
import importlib.util

def import_module_conditionally(module_name, python_version):
    try:
        specific_module = __import__(module_name, fromlist=[''])
    except ImportError:
        if python_version >= 3.8:
            try:
                common_module = importlib.import_module(module_name)
                specific_module = importlib.util.find_spec(module_name, f"path.to.common_module").load()
            except ImportError:
                raise ImportError(f"Module '{module_name}' not found for Python version {python_version}")

    except Exception as e:
        error_message = f"Error importing module '{module_name}' for Python version {python_version}: {str(e)}"
        raise ImportError(error_message)

    return specific_module

def handle_exception_and_reraise(exception, custom_message):
    error_message = f"{custom_message}: {str(exception)}"
