#include <openssl/sha.h>

#define PID_FILE "/var/run/process_unique_id.pid"

typedef struct {
    pid_t pid;
    char command[1024];
} ProcessInfo;

ProcessInfo run_process_once(char *process_name, char *args[]) {
    SHA256_CTX sha256;
    uint8_t hash[SHA256_DIGEST_LENGTH];
    int ret;
    ProcessInfo info;

    SHA256_Init(&sha256);
    SHA256_Update(&sha256, process_name, strlen(process_name));

    for (int i = 0; args[i] != NULL; i++) {
        SHA256_Update(&sha256, args[i], strlen(args[i]));
    }

    SHA256_Final(hash, &sha256);

    info.pid = 0;
    strcpy(info.command, process_name);

    for (int i = 0; args[i] != NULL; i++) {
        strcat(info.command, " ");
        strcat(info.command, args[i]);
    }

    ret = access(PID_FILE, F_OK);

    if (ret == 0) {
        FILE *pid_file = fopen(PID_FILE, "r");
        pid_t pid;
        fscanf(pid_file, "%d", &pid);
        fclose(pid_file);

        if (kill(pid, 0) > 0) {
            // Process is running, return the existing process ID
            info.pid = pid;
            return info;
        }
    }

    // Create and write the PID file
    info.pid = fork();

    if (info.pid < 0) {
        perror("Error forking process");
        exit(EXIT_FAILURE);
    }

    if (info.pid > 0) {
        // Parent process
        FILE *pid_file = fopen(PID_FILE, "w");
        fprintf(pid_file, "%d", info.pid);
        fclose(pid_file);

        // Return the process ID of the child process
        return info;
    } else {
        // Child process
        setsid();
        umask(0);

        // Hash the command line arguments and use it as the process name
        char hash_str[SHA256_DIGEST_LENGTH * 2 + 1];
        for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
            sprintf(hash_str + i * 2, "%02x", hash[i]);
        }

        char *new_name = malloc(strlen(process_name) + strlen(hash_str) + 2);
        strcpy(new_name, process_name);
        strcat(new_name, "_");
        strcat(new_name, hash_str);

        execl(process_name, process_name, args..., NULL);
