import os
import hashlib

def _safe_open(file_path, mode):
    try:
        return open(file_path, mode)
    except IOError as e:
        raise IOError("Failed to open file {}: {}".format(file_path, str(e)))

def _chunked_read(file, chunk_size):
    """Reads data in chunks of given size and returns it as a single byte string."""
    data = b''
    while True:
        chunk = file.read(chunk_size)
        if not chunk:
            break
        data += chunk
    return data

def _calculate_file_md5(file_path):
    """Calculates the MD5 hash of a file given its path."""
    md5 = hashlib.md5()
    with _safe_open(file_path, 'rb') as file:
        while True:
            chunk = _chunked_read(file, 8192)
            if not chunk:
                break
            md5.update(chunk)
    return md5.hexdigest()

def get_file_md5(file_path):
    """Calculates and returns the MD5 hash of a file given its path."""
    if not os.path.exists(file_path):
        raise FileNotFoundError("File {} does not exist.".format(file_path))

    file_md5 = _calculate_file_md5(file_path)
    return file_md5
