import hashlib
import os
import random
import string

class RegistrationProfile:
    def __init__(self, user, activation_key):
        self.user = user
        self.activation_key = activation_key

def generate_random_salt():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=5))

def generate_activation_key(user_primary_key):
    salt = generate_random_salt()
    data = user_primary_key.encode() + salt.encode()
    hash_object = hashlib.sha1(data)
    activation_key = hash_object.hexdigest()
    return activation_key, salt

def create_registration_profile(user):
