import json
import requests

def fetch_and_verify_api_response(api_url, expected_structure):
    try:
        response = requests.get(api_url, timeout=5)
        response.raise_for_status()

        json_response = json.loads(response.text)

        if not isinstance(json_response, list):
            raise ValueError("Expected a list as response, got: {}".format(json_response))

        for item in json_response:
            if not isinstance(item, dict):
                raise TypeError("Expected dictionary items in the list, got: {}".format(item))

            for key, expected_type in expected_structure.items():
                if key not in item:
                    raise KeyError("Missing key '{}' in item.".format(key))

                if not isinstance(item[key], expected_type):
                    raise TypeError("Expected key '{}' to be of type '{}', got: {}".format(key, expected_type, item[key]))

        return json_response

    except requests.exceptions.HTTPError as errh:
        raise Exception("HTTP error occurred: {}".format(errh))

    except requests.exceptions.ConnectionError as errc:
        raise Exception("Error connecting: {}".format(errc))

    except requests.exceptions.Timeout as errt:
        raise Exception("Timeout error occurred: {}".format(errt))

    except requests.exceptions.RequestException as err:
        raise Exception("An error occurred: {}".format(err))

    except ValueError as ve:
        raise Exception("Invalid JSON: {}".format(ve))

    except KeyError as ke:
        raise Exception("Missing key in expected structure: {}".format(ke))

