class ColumnFamily {
 public:
  ColumnFamily(std::string db_path, std::string column_family_name)
      : db_(OpenDB(db_path).value()),
        cf_(db_.GetColumnFamily(column_family_name.c_str())) {}

  ~ColumnFamily() {
    if (cf_) {
      db_.CloseColumnFamily(cf_);
      cf_ = nullptr;
    }
    db_.Close();
    db_.Clear();
  }

