  rocksdb::DB db_;
  rocksdb::ColumnFamily* cf_;

  static rocksdb::Status OpenDB(const std::string& db_path) {
    rocksdb::DBOptions db_options;
    db_options.create_if_missing = true;
    db_options.info_log = [](const std::string& msg) {
      std::cerr << msg << std::endl;
    };
    return rocksdb::DB::Open(db_options, db_path, &db_);
  }
};

int main(int argc, char** argv) {
  if (argc != 3) {
    std::cerr << "Usage: " << argv[0] << " <database_path> <column_family_name>"
