pub fn load_bytecode_from_archive(archive_path: &str, bytecode_name: &str) {
    let context = LLVMContext::new();
    let mut module = Module::new_with_name_in_context("loaded_bytecode", Some(&context));

    let archive_file = File::open(archive_path).expect("Failed to open archive file");
    let mut archive = tar::Archive::new(archive_file).expect("Failed to open archive");

    let bytecode_path = format!("/{}", bytecode_name);
    let bytecode_file = archive.entry(&bytecode_path).expect("Bytecode file not found in archive");

    let mut bytecode_data = Vec::new();
    bytecode_file.read_to_end(&mut bytecode_data).expect("Failed to read bytecode file");

    let bytecode_reader = Rc::new(RefCell::new(Vec::from_slice(&bytecode_data)));

    let mut builder = IrBuilder::new_in_context(context.create_function("_start", function_type(), Some(None)));
    let bytecode_module = Module::parse_memory_buffer(bytecode_reader.borrow().as_ptr(), bytecode_data.len(), None, None);

    let mut linker = ModuleLinker::new(&context);
    let linker_result = linker.link_module(&module, bytecode_module.as_ptr());

    if linker_result.is_err() {
        Err(linker_result.unwrap_err()).print_err();
        return;
    }

    let linked_module = linker_result.unwrap();
    module.import_module(linked_module.as_ptr());

    drop(bytecode_reader);
    drop(archive_file);
}

