use std::env;
use std::fs;
use std::path::Path;

fn create_dir_and_set_env(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let current_dir = env::current_dir()?;
    let base_dir = Path::new(&current_dir).join("desired_base_directory");
    let dir_path = base_dir.join(dir_name);

    // Check if directory already exists
    if fs::metadata(&dir_path).is_ok() {
        println!("Directory '{}' already exists.", dir_name);
        return Ok(());
    }

    // Create directory
    fs::create_dir_all(&dir_path)?;

    // Check if directory has correct permissions
    let permissions = fs::metadata(&dir_path)?.permissions();
    if !permissions.contains(std::fs::Permissions::OWNER_READ)
        || !permissions.contains(std::fs::Permissions::OWNER_WRITE)
        || !permissions.contains(std::fs::Permissions::OWNER_EXEC)
    {
        fs::set_permissions(&dir_path, std::fs::Permissions::OWNER_READ.grant()
            | std::fs::Permissions::OWNER_WRITE.grant()
            | std::fs::Permissions::OWNER_EXEC.grant())?;
    }

    // Set environment variable
    let dir_path_str = dir_path.to_str().unwrap();
    let mut vars = env::vars();
    let mut existing_value = vars.get("MY_ENV_VAR");

