			case GERBV_LAYERTYPE_PICKANDPLACE_BOT:
				/* Non NULL pointer is used as "not to reload" mark */
				parsed_image2 = (void *)!NULL;
				pick_and_place_parse_file_to_images(fd, &parsed_image2, &parsed_image);
				parsed_image2 = NULL;
