std::string check_struct_memory_layout(const void* struct_ptr) {
    using namespace std;
    constexpr size_t num_fields = 3;
    const char* field_names[num_fields] = {"field1", "field2", "field3"};
    alignas(std::max_align_t) char buffer[sizeof(struct S)]; // Assuming struct S
