typedef struct audio_device {
    SDL_AudioDeviceID device_id;
    SDL_AudioSpec desired_spec;
    SDL_AudioSpec observed_spec;
    bool initialized;
    void (*callback)(void *userdata, Uint16 *stream, int len);
    void *callback_userdata;
} audio_device;

audio_device *open_audio_device(SDL_AudioSpec *desired_spec, void (*callback)(void *userdata, Uint16 *stream, int len), void *callback_userdata) {
    audio_device *device = malloc(sizeof(audio_device));
    if (!device) {
        fprintf(stderr, "Failed to allocate memory for audio device\n");
        return NULL;
    }

    device->desired_spec = *desired_spec;
    device->initialized = false;
    device->callback = callback;
    device->callback_userdata = callback_userdata;

    if (SDL_Init(SDL_INIT_AUDIO) < 0) {
        fprintf(stderr, "Failed to initialize SDL: %s\n", SDL_GetError());
        free(device);
        return NULL;
    }

    if (SDL_AudioInit(desired_spec->freq, desired_spec->format, desired_spec->channels, desired_spec->samples) < 0) {
        fprintf(stderr, "Failed to initialize audio: %s\n", SDL_GetError());
        SDL_Quit();
        free(device);
        return NULL;
    }

    device->device_id = SDL_OpenAudio(&device->desired_spec, &device->observed_spec);
    if (device->device_id == 0) {
        fprintf(stderr, "Failed to open audio device: %s\n", SDL_GetError());
        SDL_CloseAudio();
        SDL_Quit();
        free(device);
        return NULL;
    }

    device->initialized = true;

    if (callback) {
        SDL_RegisterCallback(SDL_AUDIO_EVENT, callback, callback_userdata);
    }

    return device;
}

void close_audio_device(audio_device *device) {
    if (device->initialized) {
        SDL_CloseAudio();
        SDL_Quit();
        free(device);
    }
}
