use std::sync::{Arc, Mutex, RwLock};
use std::thread;
use std::sync::atomic::{AtomicUsize, Ordering};

type Bag = Arc<RwLock<VecDeque<i32>>>;

struct ConcurrentBag {
    bag: Bag,
}

impl ConcurrentBag {
    fn new() -> Self {
        ConcurrentBag {
            bag: Arc::new(RwLock::new(VecDeque::new())),
        }
    }

    fn insert(&self, value: i32) {
        let mut bag = self.bag.write().lock().unwrap();
        bag.push_back(value);
    }

    fn collect(&self) -> Vec<i32> {
        let mut result = Vec::new();
        let mut bag = self.bag.read().lock().unwrap();

        while let Some(value) = bag.pop_front() {
            result.push(value);
        }

        result
    }
}

struct ThreadData {
    bag: Arc<ConcurrentBag>,
    id: AtomicUsize,
}

impl Drop for ThreadData {
    fn drop(&mut self) {
        self.bag.insert(self.id.fetch_add(1, Ordering::SeqCst));
    }
}

