use std::process::{Command, Stdio};

pub fn run_compiler(input: &[&str], set_exit_status: Box<dyn FnOnce(i32) + Send + Sync>,) -> i32 {
    let input_vec: Vec<String> = input.iter().map(|s| s.to_string()).collect();
    let input_slice: &[String] = &input_vec;

    let output = Command::new("rustc")
        .args(input_slice)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| {
            eprintln!("Error spawning process: {}", e);
            i32::MAX
        })?;

    let status = output.wait();
    if status.is_err() {
        eprintln!("Error waiting for process: {}", status.unwrap_err());
        i32::MAX
    } else {
        let exit_status = status.unwrap().code().unwrap_or(1);
        set_exit_status(exit_status);
        exit_status
    }
}

