fn update_cargo_toml(dir: &str, verbose: bool, quiet: bool, color: bool, frozen: bool, locked: bool, manifest_path: Option<&str>) -> Result<(), Box<dyn std::error::Error>> {
    let current_dir = std::env::current_dir()?;
    let base_dir = Path::new(&current_dir).join(dir);

    let context = Context::new(".")?;
    let manifest_path = manifest_path.map(|p| Path::new(p));

    if let Some(manifest_path) = manifest_path {
        if !manifest_path.is_file() {
            return Err(Box::new(std::io::Error::new(
                std::io::ErrorKind::NotFound,
                format!("Cargo.toml not found at {}", manifest_path.display()),
            )));
        }
    } else {
        let manifest_path = context.manifest_path()?;
        if !base_dir.is_ancestor_of(manifest_path) {
            return Err(Box::new(std::io::Error::new(
                std::io::ErrorKind::NotFound,
                "Cargo.toml not found in the given directory.",
            )));
        }
    }

    let mut update_options = context.config();

    if frozen {
        update_options.frozen = true;
    }

    if locked {
        update_options.lockfile = true;
    }

    let output = if color {
        OutputFormat::Color
    } else {
        OutputFormat::Plain
    };

    context.run("update", &["--workspace"]).context("Failed to update Cargo dependencies")?;

    if let Some(manifest_path) = manifest_path {
        let mut file_contents = String::new();
        fs::read_to_string(manifest_path).context("Failed to read Cargo.toml file")?;
        file_contents = file_contents.replace("version = \"\"", &format!("version = \"{}\"", env!("CARGO_PKG_VERSION")));

        fs::write(manifest_path, file_contents)?;

        if verbose {
            println!("Cargo.toml updated successfully.");
        }
    } else {
        context.run("update", &["--workspace"]).context("Failed to update Cargo dependencies")?;

        if quiet {
            if !verbose {
                println!("Cargo.toml updated successfully.");
            }
        } else {
            let output = context.run("info", &["--json"]).context("Failed to get Cargo.toml information")?;
            let json: serde_json::Value = serde_json::from_str(&output)?;
            let version: String = json["package"]["version"].as_str().unwrap().to_string();
            println!("Cargo.toml updated successfully. New version: {}", version);
        }
    }

    Ok(())
}
