```rust use std::net::TcpListener; use std::net::TcpStream; use std::thread; use flate2::write::GzEncoder; use flate2::Compression; use flate2::write::GzWriter;

const PORT: u16 = 8080;
const NUM_THREADS: usize = num_cpus::get();

fn handle_connection(mut stream: TcpStream) {
    let (mut encoder, mut writer) = GzEncoder::new(Vec::new(), Compression::Fast);
    let mut buffer = [0; 1024];
    loop {
        let len = match stream.read(&mut buffer) {
            Ok(n) if n > 0 => n,
            Err(_) => break,
            _ => continue,
        };
        writer.write(&buffer[..len]).unwrap();
        encoder.write(&mut writer, &buffer[..len]).unwrap();
        stream.write_all(&writer.flush().unwrap()).unwrap();
    }
    drop(writer);
    drop(encoder);
    stream.shutdown().unwrap();
}

fn main() {
    println!("Listening on port {}...", PORT);
    let listener = TcpListener::bind("127.0.0.1:{}", &PORT).unwrap();
    let thread_pool = thread::ThreadPool::new(NUM_THREADS);
    for _ in listener.incoming() {
        match it {
            Ok(stream) => thread_pool.execute(move || handle_connection(stream)),
            Err(e) => eprintln!("Error handling connection: {}", e),
        }
    }
    thread_pool.join();
