import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.FileAttribute;
import java.util.EnumSet;

public static void copyFilesRecursively(String sourceDir, String destDir, String libPath, String compilerPath) {
    File srcDir = new File(sourceDir);
    File destDirFile = new File(destDir);
    if (!srcDir.exists() || !srcDir.isDirectory()) {
        throw new IllegalArgumentException("Source directory does not exist or is not a directory.");
    }
    if (destDirFile.exists() && !destDirFile.isDirectory()) {
        throw new IllegalArgumentException("Destination directory exists and is not a directory.");
    }

    if (!destDirFile.exists()) {
        Files.createDirectories(Path.of(destDir));
    }

    File libPathFile = new File(libPath);
    if (!libPathFile.isDirectory()) {
        throw new IllegalArgumentException("Library path is not a directory.");
    }

    File compilerPathFile = new File(compilerPath);
    if (!compilerPathFile.exists() || !compilerPathFile.isFile()) {
        throw new IllegalArgumentException("Compiler path does not exist or is not a file.");
    }

    File[] filesInSource = srcDir.listFiles();
    for (File file : filesInSource) {
        String srcFilePath = file.getPath();
        String destFilePath = destDirFile.toPath().resolve(file.getName()).toString();
        String libFilePath = libPathFile.toPath().resolve(file.getName()).toString();

        if (file.isDirectory()) {
            copyFilesRecursively(srcFilePath, destFilePath, libPath, compilerPath);
        } else {
            if (new File(libFilePath).exists()) {
                Path libFile = Path.of(libFilePath);
                try {
                    Files.copy(libFile, Path.of(destFilePath),
