pub fn generate_sec_web_socket_accept(key: &str) -> String {
    let mut hasher = Sha1::new();
    let mut input = key.as_bytes().to_vec();
    input.push(135); // WebSocket protocol version
    input.push(0x58); // WebSocket subprotocol version

    hasher.update(&input);
    let result = hasher.finalize();

    let mut accept = [0; 48]; // SHA-1 output is 40 bytes, but Sec-WebSocket-Accept requires 48 bytes
    accept[..result.len().into()].copy_from_slice(&result);

    let mut hex = [0; 64];
    hex[..32].copy_from_slice(&accept[..16]);
    hex[32..].copy_from_slice(&accept[16..]);

    String::from(hex.iter().map(|b| format!("{:02x}", b)).collect::<Vec<String>>().join(""))
}
