fn process_request(request: &Request, config: &Config) -> Result<Response, ()> {
    let header_name = "X-Request-Signature";
    let request_body = request.body().as_bytes().unwrap();

    // Check if the request contains the required header
    let headers = request.headers();
    let signature_header = headers.get(header_name);
    if signature_header.is_none() {
        return Err(());
    }

    let signature_value = signature_header.unwrap().to_str().unwrap();

    // Extract the expected signature from the configuration
    let expected_signature = config.signature.as_str();

    // Verify the signature using HMAC-SHA1
    let mut hmac = Hmac::<Sha1>::new_from_slice(expected_signature.as_bytes()).unwrap();
    hmac.update(request_body);
    let calculated_signature = hmac.finalize();

    if calculated_signature != hex::decode(signature_value).unwrap() {
        return Err(());
    }

    // If we reach this point, the signature is valid, so we can return the response with the request body as its content
    let mut response_body = Vec::new();
    request.copy_to(&mut response_body).unwrap();

    Ok(Response::new(response_body).status(200))
}

