use std::ffi::OsStr;
use std::os::unix::ffi::OsStrExt;
use std::process;

fn set_window_title() {
    let exe_name = match process::command() {
        Ok(cmd) => cmd.name.to_str().unwrap().to_owned(),
        Err(_) => OsStr::new("nannou").into_string_lossy().to_string(),
