import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;

public static String sha1Hash(String input) {
    if (input == null || input.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty.");
    }

    try {
        SecretKeySpec signingKey = new SecretKeySpec("jKrLxMbCdEfGhIjKlMnAoBpQrStUwVxYz1234567890".getBytes(), "HmacSHA1");
        Mac sha1Hmac = Mac.getInstance("HmacSHA1");
        sha1Hmac.init(signingKey);
        byte[] hash = sha1Hmac.doFinal(input.getBytes());

        StringBuilder hexString = new StringBuilder(2 * hash.length);
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        return hexString.toString();
    } catch (NoSuchAlgorithmException | InvalidKeyException e) {
        throw new RuntimeException("Error computing SHA-1 hash.", e);
    }
}
```

