```rust use iron::prelude::*; use std::net::SocketAddr; use std::path::PathBuf;

fn create_web_server(listen_addr: &str) -> Result<Manager<IronService>, Box<dyn std::error::Error>> {
    let mut config = Configuration::default();
    config.handle_connection_limit = Some(128);

    let mut router = Router::new();

    let static_dir = PathBuf::from("./static");
    let static_handler = Static::new(static_dir.to_str().unwrap()).handle("/{file:.*}");

    let api_handler = move |req: &mut Request| {
        let data = "Hello, API!".to_string();
        let mut response = Response::new();
        response.set(status::Ok);
        response.set(header::ContentType::plaintext());
        response.body.push_str(&data);
        Ok::<_, Error>(response)
    };

    router.mount("/", static_handler);
    router.mount("/api", Box::new(api_handler));

    let mut service = IronService::new(config);
    service.mount("/", &router);

    let addr = SocketAddr::try_from(listen_addr.parse()?).unwrap();
    let manager = Manager::try_new(service, addr)?;

    Ok(manager)
}
```

