fn compute_file_hash(repository_id: &str, file_path: &str) -> Result<String, Box<dyn std::error::Error>> {
    let mut file = File::open(file_path)?;
    let mut file_contents = Vec::new();
    file.read_to_end(&mut file_contents)?;

    let mut sha1_context = Sha1::new();
    sha1_context.update(file_contents.as_ref());
