    // Create index if it doesn't exist
    let create_index_req = CreateIndexRequest::new("file_hashes")
        .mapping(put_mapping!(
            "properties" => json!({
                "repository_id": {"type": "keyword"},
                "file_hash": {"type": "keyword"}
