    let create_index_res = client.execute(create_index_req)?;

    // Insert the hash into Elasticsearch
    let create_index_response: CreateIndexResponse = create_index_res.into();
    let index = create_index_response.index;

    let doc = json!({
        "repository_id": repository_id,
        "file_hash": hash_str
    });

    let _ = client.index(index, "file_hash_doc")
        .source(doc)
        .do()?;

    Ok(hash_str)
}
