use std::fmt;
use std::hash::{Hasher, Hmac};

#[derive(Debug, Clone)]
struct Sha1Hash(Vec<u8>);

impl PartialEq for Sha1Hash {
    fn eq(&self, other: &Self) -> bool {
        self.0 == other.0
    }
}

impl Eq for Sha1Hash {}

impl Hash for Sha1Hash {
    fn hash(&self, state: &mut Hasher) {
        state.write(&self.0);
    }
}

impl From<[u8; 20]> for Sha1Hash {
    fn from(value: [u8; 20]) -> Self {
        Self(Vec::from(value))
    }
}

fn sha1_hash(message: &str) -> Sha1Hash {
    let message = message.as_bytes();
    let mut hmac = Hmac::<HmacSha1>::new_from_slice(b"message\0").unwrap();
    hmac.update(message);
    let result = hmac.finalize();
    Sha1Hash::from(result)
}

fn main() {
    let message = "Hello, world!";
    let hash = sha1_hash(message);
    println!("{:?}", hash);
}
