use std::env;
use std::fs;
use protobuf::Message;
use tonic::transport::Certificate;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: {} <input.proto> <include.proto>", args[0]);
        return;
    }

    let input_file = &args[1];
    let include_file = &args[2];

    // Read the input .proto file
    let input_data = fs::read(input_file).expect("Failed to read input file");

    // Parse the input .proto file
    let input_descriptors = tonic::proto::Descriptors::parse_from_bytes(&input_data).unwrap();

    // Merge the include file with the input file
    let mut merged_descriptors = input_descriptors.clone();
    merge_proto_files(&mut merged_descriptors, include_file);

    // Validate the merged descriptors
    tonic::proto::validate_descriptors(&merged_descriptors).expect("Invalid Protocol Buffers schema");

    // Print the merged descriptors to stdout
    println!("{}", merged_descriptors.write_to_string().unwrap());
}

fn merge_proto_files(descriptors: &mut tonic::proto::Descriptors, file_path: &str) {
    let file_data = fs::read(file_path).expect("Failed to read include file");
    let include_descriptors = tonic::proto::Descriptors::parse_from_bytes(&file_data).unwrap();

    for service in include_descriptors.services() {
        descriptors.merge_service(service);
    }

    for message in include_descriptors.messages() {
        descriptors.merge_message(message);
    }

    for extension in include_descriptors.extensions() {
        descriptors.merge_extension(extension);
    }

    for enum_type in include_descriptors.enum_types() {
        descriptors.merge_enum_type(enum_type);
    }

    for field_mask in include_descriptors.field_masks() {
        descriptors.merge_field_mask(field_mask);
    }

    for service_extension in include_descriptors.service_extensions() {
        descriptors.merge_service_extension(service_extension);
    }

    for message_extension in include_descriptors.message_extensions() {
        descriptors.merge_message_extension(message_extension);
    }

    for enum_extension in include_descriptors.enum_extensions() {
        descriptors.merge_enum_extension(enum_extension);
    }
}
