fn recursive_copy(src: &PathBuf, dest: &PathBuf) -> Result<(), Box<dyn std::error::Error>> {
    if src == dest {
        return Ok(());
    }

    if src.is_dir() {
        let src_files = fs::read_dir(src)?;
        for entry in src_files {
            let src_entry = entry?;
            let src_path = src_entry.path();
            let dest_path = dest.join(src_entry.file_name());

            if src_path.is_dir() {
                let dest_dir = PathBuf::from(dest_path.to_str().unwrap());
                recursive_copy(&src_path, &dest_dir)?;
            } else {
                let src_file_type = fs::metadata(src_path)?;
                let dest_file_path = dest_path.with_extension(src_file_type.file_name().unwrap());

                if fs::path_exists(&dest_file_path) {
                    continue;
                }

                fs::copy(src_path, &dest_file_path)?;
            }
        }
