pub fn sha1_hash(input: Vec<u8>) -> Result<(BDict, usize), Box<dyn std::error::Error>> {
    let mut hashed_data: Vec<u8> = Vec::new();
    let mut chunk_size = 1024; // Set a reasonable chunk size
    let mut current_position = 0;

    let mut final_dict = BDict::new();

    while current_position < input.len() {
        let chunk = if input.len() - current_position < chunk_size {
            input[current_position..].to_vec()
        } else {
            input[current_position..current_position + chunk_size].to_vec()
        };

        let mut sha1 = Sha1::new();
        sha1.update(&chunk);
        let chunk_hash: [u8; 20] = sha1.finalize().into_inner();

        let chunk_dict = BDict::new()
            .insert("hash".to_string(), BValue::String(chunk_hash.iter().map(|b| b.to_string()).collect::<Vec<String>>().join(":")))
            .insert("data".to_string(), BValue::Bytes(chunk.as_slice()));

        final_dict = final_dict.insert("chunk_".to_string() + &current_position.to_string(), chunk_dict);

        current_position += chunk_size;
    }

    let mut encoder = Encoder::new();
    let final_dict_bytes = encoder.encode(&final_dict)?;

    Ok((final_dict, final_dict_bytes.len()))
}
