use crypto::md::Md5;
use crypto::digest::Digest;
use crypto::hmac;
use pbkdf2;
use std::error::Error;
use std::fmt;

#[derive(Debug, PartialEq)]
pub enum SaltError {
    InvalidLength,
}

impl fmt::Display for SaltError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match *self {
            SaltError::InvalidLength => write!(f, "Invalid salt length"),
        }
    }
}

impl Error for SaltError {}

pub fn hash_password_with_salt(password: &str, salt: &[u8]) -> Result<Vec<u8>, Box<dyn Error>> {
    if salt.len() != 16 {
        return Err(Box::new(SaltError::InvalidLength));
    }

    let mut md = Md5::new();
    md.input(salt);
    let salt_digest = md.result();

    let mut hmac = hmac::Hmac::new(Md5::new(), salt_digest);
    hmac.input(password.as_bytes());
    let password_hash = hmac.result();

    Ok(password_hash.into_vec())
}

pub fn pbkdf2_hash(password: &str, salt: &[u8], iterations: u32, key_length: u32) -> Result<Vec<u8>, Box<dyn Error>> {
    let salt_digest = hash_password_with_salt(salt, salt)?;
    let mut pbkdf2_result = [0; 64];
    pbkdf2::pbkdf2_hmac(
        password.as_bytes(),
        salt_digest.as_slice(),
        iterations,
        &mut pbkdf2_result,
        key_length as u32,
        Md5::new(),
    )?;

    Ok(pbkdf2_result.to_vec())
}
