use std::ffi::OsStr;
use std::process::Command;

fn get_program_to_open_file(path: &str) -> Result<String, String> {
    let mut browsers = vec!["BROWSER".to_owned(), "xdg-open".to_owned(), "gnome-open".to_owned(), "kde-open".to_owned()];
    let mut error_message = String::new();

    for browser in browsers {
        match try_to_open_with_browser(&browser, path) {
            Ok(program) => return Ok(program),
            Err(msg) => {
                error_message.push_str(&format!("Tried '{}' but failed: {}\n", browser, msg));
                browsers.retain(|b| b != &browser);
            }
        }
    }

    Err(format!("Could not open file '{}' with any of the following programs:\n{}\n", path, error_message))
}

fn try_to_open_with_browser(browser: &str, path: &str) -> Result<String, String> {
    match browser.as_str() {
        "BROWSER" => {
            let env_var = std::env::var("BROWSER").unwrap_or_else(|_| String::from(""));
            if env_var.is_empty() {
                return Err("Environment variable BROWSER is not set".to_owned());
            }
            let program = OsStr::new(env_var).to_str().unwrap().to_owned();
            let mut cmd = Command::new(program);
            cmd.arg(path);
            let output = cmd.output();
            match output {
                Ok(_) => Ok(program),
                Err(_) => Err("Failed to open file with program '{}'".format(program)),
            }
        }
        "xdg-open" => {
            let output = Command::new("xdg-open")
                .arg(path)
                .output()
                .map_err(|e| format!("Failed to open file with program 'xdg-open': {}", e));
            output
        }
        "gnome-open" => {
            let output = Command::new("gnome-open")
                .arg(path)
                .output()
                .map_err(|e| format!("Failed to open file with program 'gnome-open': {}", e));
            output
        }
        "kde-open" => {
            let output = Command::new("kde-open")
                .arg(path)
                .output()
                .map_err(|e| format!("Failed to open file with program 'kde-open': {}", e));
            output
        }
        _ => Err(format!("Unknown browser '{}'", browser)),
    }
}
