std::string CreateGenesisTransactionFile(const std::string& poolName, const std::vector<NodeTransaction>& nodeTransactions) {
    if (!boost::filesystem::exists(poolName)) {
        boost::filesystem::create_directory(poolName);
        if (!boost::filesystem::exists(poolName)) {
            throw std::runtime_error("Failed to create pool directory");
        }
    }

    std::string genesisFileName = boost::format("%1%.txn") % poolName;
    std::ofstream genesisFile(genesisFileName, std::ios::binary);

    if (!genesisFile.is_open()) {
        throw std::runtime_error("Failed to open genesis file for writing");
    }

    // Write genesis transaction header
    genesisFile.put('B'); // Version byte
    genesisFile.put('M'); // Magic byte
    genesisFile.put('B'); // Number of transactions

    // Write client IP and port for each node transaction
    for (const auto& nodeTransaction : nodeTransactions) {
        genesisFile.write(reinterpret_cast<const char*>(&nodeTransaction.clientIP[0]), nodeTransaction.clientIP.size());
        genesisFile.put(static_cast<char>(nodeTransaction.clientPort >> 8));
        genesisFile.put(static_cast<char>(nodeTransaction.clientPort & 0xFF));
    }

    // Write node IP and port for each node transaction
    for (const auto& nodeTransaction : nodeTransactions) {
        genesisFile.write(reinterpret_cast<const char*>(&nodeTransaction.nodeIP[0]), nodeTransaction.nodeIP.size());
        genesisFile.put(static_cast<char>(nodeTransaction.nodePort >> 8));
        genesisFile.put(static_cast<char>(nodeTransaction.nodePort & 0xFF));
    }

    // Write transaction data for each node transaction
    for (const auto& nodeTransaction : nodeTransactions) {
        for (const auto& transaction : nodeTransaction.transactions) {
            genesisFile.write(transaction.serialize().data(), transaction.serialize().size());
        }
    }

    genesisFile.close();

    return genesisFileName;
}
