#[derive(Debug)]
struct FileInfo {
    name: String,
    path: PathBuf,
    size: u64,
    md5: String,
}

fn read_file(path: &str) -> Result<FileInfo, Error> {
    let file_path = PathBuf::from(path);
    let mut file = File::open(&file_path)?;
    let mut contents = Vec::new();
    let reader = BufReader::new(&file);
    for line in reader.lines() {
        let line = line?;
        contents.push_all(line.as_bytes());
    }
    file.close()?;

    let md5 = md5::compute(&contents);
    let md5_str = hex::encode(md5.as_ref());

