use std::io::{Error as IoError, ErrorKind};
use std::net::TcpStream;
use openssl::ssl::{SslAcceptor, SslConnector, SslMethod, SslOptions, X509};
use openssl::error::ErrorStack;

pub struct RedisError {
    message: String,
}

impl RedisError {
    fn new(message: &str) -> Self {
        RedisError { message: message.to_string() }
    }
}

pub struct TlsConnectorAsync {
    connector: SslConnector,
}

impl TlsConnectorAsync {
    pub fn connect(&mut self, address: &str, handle: Option<&X509>) -> Result<(), RedisError> {
        let mut acceptor = match SslAcceptor::new(SslMethod::TLSv1_2, None) {
            Ok(acceptor) => acceptor,
            Err(e) => return Err(RedisError::new("Failed to create TlsAcceptor: {:?}", e)),
        };

        let mut options = SslOptions::new();
        options.set_peer_verify(if handle.is_some() {
            true
        } else {
            self.disable_certificate_verification()
        });

        acceptor.set_options(options);

        let mut stream = match TcpStream::connect(address) {
            Ok(stream) => stream,
            Err(e) => return Err(RedisError::new("Failed to connect to server: {:?}", e)),
        };

        let connector = match acceptor.accept(&mut stream) {
            Ok(connector) => connector,
            Err(e) => return Err(RedisError::new("Failed to accept TLS connection: {:?}", e)),
        };

        Ok(TlsConnectorAsync { connector })
    }

    fn disable_certificate_verification(&mut self) {
        self.connector.set_options(SslOptions {
            danger_accept_invalid_certs: true,
            ..Default::default()
        });
    }
}

pub fn create_tls_connector(address: &str, handle: Option<&X509>, disable_cert_verification: bool) -> Result<TlsConnectorAsync, RedisError> {
    let connector = match TlsConnectorAsync::new() {
        Ok(connector) => connector,
        Err(e) => return Err(RedisError::new("Failed to create TlsConnectorAsync: {:?}", e)),
    };

    let result = match connector.connect(address, handle) {
        Ok(_) => connector,
        Err(e) => return Err(e),
    };

    if disable_cert_verification {
        result.disable_certificate_verification();
    }

    Ok(result)
