use std::borrow::Cow; // for Cow::Borrowed and Cow::Owned
use std::error::Error; // for Result type
use std::fmt::{Display, Formatter}; // for Display trait
use std::str::Chars; // for chars() method
use std::iter::Peekable; // for Peekable<Chars>

#[derive(Debug, Clone)]
struct HeaderError {
    name: String,
    error: Box<Box<dyn Error + Send + Sync + 'static>>,
}

impl Display for HeaderError {
    fn fmt(&self, f: &mut Formatter) -> std::fmt::Result {
        write!(
            f,
            "HeaderError: name={}, error={}",
            self.name, self.error
        )
    }
}

impl Error for HeaderError {}

fn validate_header_name(name: &str) -> Result<(), HeaderError> {
    if name.is_empty() {
        Err(HeaderError {
            name: "".to_string(),
            error: Box::new(Box::new(InvalidInputError {
                message: "Empty header name".to_string(),
            })),
        })
    } else {
        Ok(())
    }
}

fn fold_line(line: &str) -> Result<Cow<str>, HeaderError> {
    let (name, value) = line.splitn(1, ": ").collect_tuple()?;
    validate_header_name(name)?;
    Ok(Cow::Owned(format!("{}: {}", name, value)))
}

fn main() {
    let input = "Content-Type: application/json";
    match fold_line(input) {
        Ok(header) => println!("{}", header),
        Err(err) => println!("Error: {}", err),
    }
}

fn fold_input_to_header(input: &str) -> Result<Cow<str>, HeaderError> {
    let chars = input.chars();
    let mut iter = chars.peekable();
    let mut header = String::new();
    let mut is_name = true;

    while let Some(c) = iter.next() {
        if c == ':' {
            is_name = false;
            let name = header.trim();
            header.clear();
            validate_header_name(name)?;
            continue;
        }
        if is_name {
            header.push(c);
        } else {
            header.push_str(&format!("{}", c));
        }
    }

    if header.is_empty() {
        Err(HeaderError {
            name: "".to_string(),
            error: Box::new(Box::new(InvalidInputError {
                message: "Empty header value".to_string(),
            })),
        })
    } else {
        Ok(Cow::Borrowed(header.as_str()))
    }
}

struct Headers {
    inner: std::collections::HashMap<String, Vec<Cow<str>>>,
}

impl Headers {
    fn new() -> Self {
        Headers {
            inner: std::collections::HashMap::new(),
        }
    }

    fn insert_raw(&mut self, name: Cow<str>, value: Cow<str>) {
        self.inner.entry(name).or_insert_with(Vec::new).push(value);
    }
}

fn main() {
    let input = "Content-Type: application/json";
    let headers = Headers::new();
    match fold_input_to_header(input) {
