fn build_reqwest_client(user_agent: &str, cert_path: &str) -> Result<Client, Box<dyn std::error::Error>> {
    let mut ssl_context = SslContextBuilder::new();
    let cert_file = File::open(cert_path)?;
    let mut cert_data = Vec::new();
    cert_file.read_to_end(&mut cert_data)?;
    let cert = X509Certificate::from_der(&cert_data)?;

    let key_file = File::open(cert_path)?;
    let mut key_data = Vec::new();
    key_file.read_to_end(&mut key_data)?;
    let key = PrivateKey::from_pkcs8(&key_data, None)?;

    ssl_context.set_private_key(Some(key)).unwrap();
    ssl_context.add_client_certs(&[cert]).unwrap();

    ClientBuilder::new()
        .user_agent(user_agent)
        .header("connection", "close")
        .ssl_context(ssl_context.build())
        .build()
}
