struct DBActor {
    pool: Arc<ThreadPoolExecutor>,
}

impl DBActor {
    fn new(pool_size: u32) -> Self {
        let pool = Arc::new(ThreadPoolExecutor::new(pool_size));
        Self { pool }
    }

    fn process_query(&self, query: String) -> Result<String, String> {
        let handle = self.pool.spawn(move || {
            // database query processing logic here
            Ok(format!("Query result for client {}: {}", query, query))
        });

        match handle.join() {
            Ok(result) => result,
            Err(_) => {
                error!("Failed to process query, error handling logic here");
                String::from("Error processing query")
            }
        }
    }
}

impl QueryClient {
    fn new(id: u32, db_actor: Arc<DBActor>, channel: Channel<u32, String>) -> Self {
        Self { id, db_actor, channel }
    }

    fn send_query(&self, query: String) {
        match self.channel.send(self.id, query) {
            Ok(_) => println!("Sent query {} to database for client {}", query, self.id),
            Err(_) => println!("Failed to send query to database for client {}", self.id),
        }
    }
}

fn main() {
    let db_actor = Arc::new(DBActor::new(10));

    let mut clients = Vec::new();

    for i in 0..10 {
        let db_actor_clone = db_actor.clone();
        let channel = Channel::unbounded();
        let client = QueryClient::new(i, db_actor_clone, channel);

        thread::spawn(move || {
            loop {
                match channel.recv() {
                    Ok((client_id, query)) => {
                        let result = db_actor.clone().process_query(query);
                        match result {
                            Ok(answer) => println!("Client {} received answer: {}", client_id, answer),
                            Err(error) => println!("Error processing query for client {}: {}", client_id, error),
                        }
                    }
                    Err(_) => break,
                }
            }
        });

        clients.push(client);
    }

    for client in clients {
        client.send_query(format!("Query for client {}", client.id));
    }

    thread::park();
}
